INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3870, 'Eliasson has also coloured the water in a harbour bright green, and in 2003 he made a work called the weather project for Tate Modern in London which consisted of a thirty meter diameter semi circular yellow panel representing the sun, hung at the top of the museums entrance hall, with a ceiling panelled with silver mirror fabric to create a reflection of the sun as if it were in water.', 3870, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3871, 'A theatrical mist made of sugar and water is fed into the hall.', 3871, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3872, 'Viewers lie on the floor to watch their reflections and to look at the sun.', 3872, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3873, 'Tracy Emin', 3873, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3874, 'British artist who was at the forefront of the Brit Art group that came to prominence in the 1990s in London.', 3874, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3875, 'Emin was born in the 1960s in Margate, a British seaside town which features prominently in her work.', 3875, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3876, 'Emin&apos;s work is essentially a diary of her life, reflecting on her state of mind particularly in relation to her love life and her emotional life.', 3876, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3877, 'Emin relates experiences that mostly remain personal, such as her abortion, her rape, her breakdown, drunken and regretted sex, good sex, the break up of relationships, her problems with alcohol and her feelings about her absent father.', 3877, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3878, 'These are represented in a wide variety of media: video, drawings, mono prints, text, neon signs, textiles, embroidery, and installation.', 3878, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3879, 'Emin&#x2019;s consistent poetry and diary writing underpins her work.', 3879, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3880, 'Her video works include &#x2018;Why I never became a dancer&#x2019; made in the early 1990s shows Emin dancing in Margate.', 3880, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3881, 'In 2000 Emin made a video in which she appears (achieved with editing) twice, as both good Tracy and bad Tracey, sitting together and chatting on a couch.', 3881, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3882, 'The two dress differently and behave differently, both are likeable in different ways, one is drinking a cup of tea and the other a glass of wine throughout what seems to be an interview of some sort, or perhaps a therapy session.', 3882, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3883, 'Emin achieved notoriety when she embroidered and appliqu&#xe9;d the inside of an ordinary one person tent with the names of all the people she had ever slept with.', 3883, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3884, 'This was quite a long list of mostly men including several male artists, but also siblings and women friends who she had shared a bed with.', 3884, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3885, 'In order to view the work the viewer had to crawl into the very small tent (which had only room for two), and recline, since there was no room to stand, in intimate proximity with both Emin&#x2019;s work and the other occupant of the tent.', 3885, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3886, 'Emin also embroidered an upholstered chair and made a series of appliqu&#xe9;d and embroidered quilts.', 3886, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3887, 'The quilts bear text legends of life and love and art, for example &#x2018;I need art like I need god&#x2019; and patterns, and are made using patterned and plain fabric and basic embroidery stitches onto bedspreads and blankets.', 3887, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3888, 'The quilts were usually dated.', 3888, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3889, 'Emin had a number of works made in neon, either from her writings or her poetry.', 3889, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3890, 'The neon letters either a single sentence or a verse, often in pink, were mounted on the gallery wall.', 3890, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3891, 'Emin consistently made drawings and mono prints, often accompanied by descriptive sentences or titles as part of the image.', 3891, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3892, 'These are often explicit, showing her menstruating, lying in a drunken heap, happy and in love, masturbating.', 3892, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3893, 'They are very simply drawn in a childish hand in pen, pencil or a blue or black ink for the mono prints, that belies their effectiveness.', 3893, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3894, 'In the mid 1990s Emin opened a shop with another artist, Sarah Lucas, selling trinkets, souvenirs and t shirts all of which were made by the artists, for example an ashtray with a picture of Damien Hirst&apos;s head (which has since become a collectors item).', 3894, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3895, 'When the shop closed Emin established the Tracey Emin Museum, essentially a live work space which she kept open to the public regularly each week and sold work from.', 3895, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3896, 'Her insistence on non exclusivity as manifested by the shop and the museum, coupled with her appropriation of &#x2018;anyone can do it&#x2019; craft methods and materials captured the zeitgeist of the time, and contributed to a surge in public interest in contemporary art.', 3896, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3897, 'Before this was seen as elitist and even if this interest was often prurient, Emin was ultimately persuasive.', 3897, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3898, 'She also took up many of the areas of investigation of women artist in the 1970s and updated them and has been extremely influential to a whole generation of artists, especially women.', 3898, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3899, 'The work that crowned Emin&#x2019;s reputation (for notoriety or otherwise) was My Bed, exhibited in the 2000 Turner Prize exhibition in London&#x2019;s Tate gallery.', 3899, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3900, 'This is the bed in which Emin spent many days during her breakdown, drinking, smoking, eating, having sex.', 3900, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3901, 'The bed and the surrounding detritus, empty bottles, food plates, glasses, pill packets, dirty clothes including underwear, overflowing ashtrays, a soiled tampon, books and magazines, was exhibited on a plinth to great public outcry.', 3901, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3902, 'Since 2000 Emin has continued to make works on paper and also to make more sculpture, including a rickety wooden tower which can be climbed, and a stuffed bird on a plinth.', 3902, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3903, 'Birds have been a part of her personal iconography throughout her career.', 3903, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3904, 'Pepe Espaliu', 3904, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3905, 'South American artist born in the 1960s who made a piece of work with a large quantity of old clothes, involving him cycling round the trunk of a tree on a platform that encircled the trunk just below the canopy.', 3905, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3906, 'Jonathan Faier', 3906, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3907, 'German artist who made a video with Johannes Rust and one other artist in which they put together a large number of clips from news footage and advertisements featuring corporate logos.', 3907, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3908, 'They edited it and added an ironic and humorous soundtrack to represent their appropriated material as a fast paced and amusing look at global capitalism and consumerism.', 3908, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3909, 'This video is an example of a way of working that emerged in the late 1990s as video editing technology became universally accessible so that anyone with a camcorder and a TV could edit video.', 3909, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3910, 'Angus Fairhurst', 3910, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3911, 'British artist born in the 1960s who makes drawings and collages and digitally animated drawing videos.', 3911, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3912, 'Mark Fairnington', 3912, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3913, 'Simon Faithfull', 3913, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3914, 'British artist who has made a number of installation and works for the web.', 3914, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3915, 'Keith Farquhar', 3915, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3916, 'German artist who makes drawings in marker pen on found surfaces such as pieces of laminate.', 3916, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3917, 'The drawings reference the graphics on the covers of 60s and 70s text books.', 3917, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3918, 'Vincent Fecteau', 3918, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3919, 'Artist working in the 1990s onwards who makes sculptures from wood, sometimes painted, with strong references to modernism.', 3919, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3920, 'Rachel Feinstein', 3920, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3921, 'American artist born in the 1960s who makes sculptures from particle board and other timber sheet material, polystyrene, paint and a variety of other media.', 3921, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3922, 'The sheet material is cut into shapes and assembled as the framework of a sculpture.', 3922, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3923, 'Sometimes it is spray painted.', 3923, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3924, 'Feinstein&apos;s work has a theatrical feel to it, as if she were making a kind of prop or stage set.', 3924, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3925, 'She made a number of works that looked like futuristic flowers.', 3925, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3926, 'Later works are made only of painted board cut into shapes, often silhouettes of people.', 3926, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3927, 'The sculptures are usually no more than two metres in height.', 3927, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3928, 'Peter Fend', 3928, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3929, 'Artist born in the 1960s who made a film of himself jumping around with only a jumper and a pair of shoes on.', 3929, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3930, 'Fischli and Weiss', 3930, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3931, 'Swiss artists born in the 1950s who work in partnership.', 3931, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3932, 'Peter Fischli and David Weiss make installation, photographic and video art.', 3932, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3933, 'They are interested in nature, animals, cause and effect and the human condition.', 3933, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3934, 'Early works consist of the artists dressed as animals filmed walking in the countryside, a series of realistic replica interiors for example a store room, the artists&#x2019; studio in which every item and piece of furniture is modelled from clay and cast in rubber, in a variety of solid colours, producing a simultaneously convincing and perplexing version of reality.', 3934, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3935, 'Fischli and Weiss made a number of photographic works in which they created art works with food.', 3935, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3936, 'For example, Still Life with Cold Meats shows an arrangement of sliced sausage, frankfurters and gherkins.', 3936, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3937, 'Photographic work is always part of their practise, most usually presented as a slide projection or light box.', 3937, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3938, 'Indeed much of Fischli and Weiss&#x2019;s video work is very static and closer to photography.', 3938, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3939, 'A slide projection featuring hundreds of images of flowers, shown grouped into seasons, each slide dissolving into the next so that a complex double image is created, takes about an hour to view.', 3939, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3940, 'It has a mesmerising effect.', 3940, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3941, 'An illuminated table, about fifteen meters long and one metre wide is used to display hundreds of images of land and city scapes, each one about six cm wide.', 3941, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3942, 'At first off putting, this work also draws the viewer in as they try to make connections between the images and inadvertently construct their own narrative.', 3942, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3943, 'Video work is often similarly open ended, as in one installation of about twelve monitors placed in a room, all showing different images of landscape, but not simultaneously so that some screens were blue while others are playing.', 3943, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3944, 'The viewer is directed to move about the room by the monitors&#x2019; apparently random showings.', 3944, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3945, 'Fischli and Weiss&#x2019;s best known static video work is Pussy, a single shot film of a black and white cat drinking milk from a saucer.', 3945, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3946, 'This was made to be projected on a huge LED screen above Times Square in New York, where it achieved a monumental quality.', 3946, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3947, 'Perhaps their best known video is The Way Things Go, a film of the progression of a series of inanimate objects caused to move by a cause and effect chain of events.', 3947, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3948, 'Using simple science, physics and common sense, and materials such as wood, metal, a variety of vessels, balls, weights, fire, steam, salt, batteries, and ice, the artists made a series of structures, balances, ramps, slopes, water channels, tubes, pipes and levers that are set in motion be each other over a period of about half and hour.', 3948, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3949, 'Basic principles of physics utilising steam for expansion, melting, burning, balancing, rocking, tipping and velocity.', 3949, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3950, 'This is for example used to propel water down a slope into a bucket which tips filling a tank with something floating on the surface which when it reaches a ball cock pushes a weight down on a platform which sets a ball rolling and so on.', 3950, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3951, 'This piece is filmed in an empty warehouse space.', 3951, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3952, 'Fischli and Weiss often make questions part of their work, as if they are involved in some kind of research.', 3952, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3953, 'The question with which they are most often associated is &#x2018;Are Animals People?&#x2019; At the Venice biennale in 2003 they presented a work in which they simply projected a series of questions on a wall in enormous letters, one of which was &#x2018;Will Happiness Find Me?&#x2019; ! Ceal Floyer.', 3953, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3954, 'British artist born in the 1960s who has made many works using light as her main medium.', 3954, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3955, 'However Floyer&apos;s earliest works are a pair of brass door fingerplates with the inscriptions pushed and pulled on them, and a red dot of the kind galleries use to indicate that a work has been sold, which in reality was a hole in the wall filled with red pigment.', 3955, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3956, 'Both are poetic interventions into the mundane, which also characterises Floyer&#x2019;s whole body of work.', 3956, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3957, 'A lot of Floyer&#x2019;s early works are slide projections.', 3957, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3958, 'Light switch, made in the early 1990s, is a slide projection of a photograph of an ordinary household light switch, projected onto a wall where a light switch might be.', 3958, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3959, 'The projector is not concealed at all.', 3959, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3960, 'The projection looks exactly like a real light switch prompting a double take, and the viewer, surprisingly, does not readily associate the projector with the image.', 3960, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3961, 'Floyer achieved full suspension of disbelief by presenting something utterly ordinary in a magical way.', 3961, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3962, 'Light Under The Door consisted of a projector placed in front of a door, projecting a strip of light the exact dimensions of the space under the door, at this space.', 3962, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3963, 'The effect was of an incredibly strong light was coming from behind the door, enough to make the viewer want to investigate, when in fact the light source was readily visible at the viewers feet.', 3963, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3964, 'In a similar vein, a photograph of an illuminated light bulb was projected on to a switched off light bulb, making it a light source in a new way.', 3964, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3965, 'A light was projected down through a light bulb, projecting the text on the bulb (brand name and wattage) onto the ground below, again prompting a kind of double take since when this work is viewed it seems like something that should happen every time a light bulb is switched on.', 3965, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3966, 'Floyer began to work with sound in the late 1990s, presenting a work in which the sound of a slide projector is recorded and pressed onto vinyl, which is played on a turntable on a plinth.', 3966, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3967, 'The viewer looks for the slide projection, which is not there, and eventually associates what they are hearing with what they see.', 3967, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3968, 'This slippage, between what is heard and seen, or what is seen and understood is Floyer&#x2019;s main interest.', 3968, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3969, 'Around the same time, she made a video of a dog just outside the frame, jumping into the frame regularly leaping for an invisible ball.', 3969, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3970, 'Once again it takes a certain amount of watching to work out what is happening.', 3970, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3971, 'An apparently abstract static image suddenly moves and turns out to be a white net curtain against a window which occasionally flaps in the breeze, and when it touches the window becomes more transparent.', 3971, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3972, 'A piece of screwed up white paper, fluttering in an eddy of wind in an empty cul de sac, resembles, when the film is looped, a white butterfly forever fluttering in the same place.', 3972, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3973, 'Floyer&#x2019;s interest in light extended to an interest in all things white, and indeed she has not used colour at all unless the object she wishes to use is coloured.', 3973, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3974, 'A till receipt is placed on the wall and seems to be nothing more than that, until the viewer realises that every object on the list is white in colour (milk, flour and lard for example).', 3974, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3975, 'In 2003 Floyer made a work for a museum in London.', 3975, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3976, 'She installed a bell ringing at regular intervals, a bit like the bell that summons an audience into an auditorium.', 3976, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3977, 'This created a sense of expectation, and a feeling in the viewer that they ought to obey the abstract summons causing them to look for a direction and finally to look towards where they perceive the sound to be emanating from.', 3977, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3978, 'This act of looking is what the artist wanted to achieve.', 3978, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3979, 'Another sound work is a recording of a drip in a bucket, played on a cassette player placed in a bucket, causing the viewer to look to the ceiling or if not to think about the sound they are hearing as being generated by a drip coming from the ceiling which they know is not there.', 3979, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3980, 'Floyer&#x2019;s project has been to reveal the beauty in the nearly intangible.', 3980, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3981, 'Laura Ford', 3981, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3982, 'British artist born in 1960s who made a number of installation works in the 1980s concerned with fairy tales and the imagination, including one performance featuring a person in a bear suit.', 3982, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3983, 'In the 1990s Ford made a large installation of actual size stuffed toy children, made in chintz fabrics of different colours, in a range of poses.', 3983, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3984, 'John Frankland', 3984, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3985, 'British artist born around 1960 who makes sculpture and installation.', 3985, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3986, 'Frankland&apos;s early works were a series of site specific installations in which he used plastic sheeting, stretched over battens, to line the walls of a space.', 3986, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3987, 'In such a way he created a second skin inner wall that appeared to be very solid and shiny but was in fact only a thin layer of cheap plastic.', 3987, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3988, 'He did this in black plastic in a cellar, in silver grey plastic on a freestanding form that looked like a giant metal wall, and in gold metal along a wall in a gallery.', 3988, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3989, 'In this last work, Lift, he arranged the battening and supports so that there was the illusion of minimal gold metal lift doors set into a gold wall, with a hemispherical convex form pushed out from the back of the plastic to represent the button for calling the lift the only detail.', 3989, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3990, 'Following this, Frankland made a work in which he painted a section of a tree trunk in bright yellow high gloss paint, using so many layers that the details of the trunk are smoothed out, giving it a first impression look of a model tree trunk.', 3990, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3991, 'The trunk is mounted on the wall at chest height defying its tremendous weight.', 3991, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3992, 'There is a contradiction between the possible lightness of the trunk if it is a fibreglass cast, and the reality of the weight of the wood.', 3992, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3993, 'Frankland later made a site specific work for a sculpture park which consisted of his selection of a one ton boulder from a quarry placed in a site of his choice.', 3993, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3994, 'Katharina Fritsch', 3994, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3995, 'Artist working in the late 1990s and early 2000s.', 3995, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3996, 'Bernard Frize', 3996, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3997, 'German artist who makes process paintings, using multiple clear and bright colours of thin paint in several distinct and apparently continuous brushstrokes, wet into wet, to create a simple repeated pattern.', 3997, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3998, 'The means of execution of the painting is puzzling as it appears that it would be impossible for the brush strokes to be juxtaposed in the way that they are.', 3998, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3999, 'Anya Gallaccio', 3999, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4000, 'British artist born in the 1960s who has made a number of installations since the 1990s.', 4000, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4001, 'One of her first installations involved paining the walls of a gallery with chocolate.', 4001, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4002, 'The colour was reminiscent of a dirty protest, the smell in contrast overpoweringly sweet.', 4002, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4003, 'She also made a curtain to hang in a gallery window from dark orange gerbera flower heads strung on threads the height of the window.', 4003, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4004, 'Gang Chen', 4004, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4005, 'Chinese artist born in the 1960s who makes paintings of luggage seen on airport x ray machines.', 4005, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4006, 'Vidya Gaston', 4006, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4007, 'Artist working in partnership with another artist who has made work in the 1990s and 2000s consisting of woollen pompoms placed on Perspex boxes.', 4007, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4008, 'The pompoms are made in the way that children make them, by threading wool around two circles of card with a hole in the middle and then cutting between the circles.', 4008, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4009, 'They are made in a range of sizes and colours, usually muted, from about 2 cm to 60 cm in diameter.', 4009, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4010, 'The plinths are various sized too.', 4010, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4011, 'The two artists have made other kinds of work together.', 4011, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4012, 'Ana Genovese', 4012, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4013, 'British sculptor born in the 1970s who make small scale models of large environments or tracts of land, for example deserts.', 4013, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4014, 'A desert complete with an oasis is be modelled on a domestic scale.', 4014, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4015, 'Genovese also makes fibreglass &#x2018;puddles&#x2019;.', 4015, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4016, 'Isa Genzken', 4016, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4017, 'German artist who makes sculptural objects and collages, for example concrete forms reminiscent of building materials placed together to form rudimentary architectural structures of about three metres in height, or long wooden spear like forms four metres tapered at both ends.', 4017, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4018, 'Other works include collections of metal cooking utensils, such as sieves, whisks, knives, colanders, graters and peelers, strung together with chains and hung in clusters on the wall.', 4018, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4019, 'Presented in this way these banal domestic objects seem somehow sexual and perverse.', 4019, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4020, 'Genzken also made a series of thirty cm square collages of nudes cut up and re joined to make strange human forms.', 4020, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4021, 'In 2002 Genzken made a series of small sculptures that look like maquettes for skyscrapers, made from found materials such as fruit crates, cellophane, printed matter, cardboard and glass, and roughly formed with copious amounts of glue oozing from the joins.', 4021, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4022, 'This work is about the re building of Berlin, the changing from a faded modernist architecture to the new skyscrapers ! Ori Gersht.', 4022, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4023, 'Artist working in the 1990s and 2000s who took a panoramic photo of a London football stadium and presented it on 25 metre gallery wall ! Liam Gillick.', 4023, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4024, 'British artist who born in around 1960 who works in a variety of media.', 4024, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4025, 'Text is integral to Gillick&apos;s work both visually and because he has written a number of books which he also designs, for example Erasmus is Late (with a yellow cover, the title punched through in ticker tape lettering), and published texts which are part of his practise.', 4025, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4026, 'In both texts and visual work he explores the legacy and iconography of modernism, in particular its architectural and graphic forms, and urban and social space.', 4026, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4027, 'There is a strongly liberal political aspect to Gillick&#x2019;s work.', 4027, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4028, 'He often uses quotation relating to politically significant historical events (such as the English Civil War) in his work, an approach which ultimately gives Gillick&#x2019;s work a didactic quality.', 4028, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4029, 'For Gillick the design of printed material is of paramount importance, equal to the construction of his sculptural works.', 4029, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4030, 'For example Gillick&#x2019;s &#x2018;Conversation Platforms&#x2019; are panels made from squares of apparently random coloured Perspex sheets set in an aluminium framework to make a grid.', 4030, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4031, 'The panel is then hung above head height and the viewer will be standing under it.', 4031, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4032, 'These works have expanded into more complex and architectural structures, featuring sections of wall as well as platforms, and even a huge suspended ceiling, always using different colours of Perspex.', 4032, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4033, 'Gillick has also made a large number of works on paper, many of them proposals for graphic design projects or architectural designs for the facades of buildings.', 4033, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4034, 'In addition to his ideas for transforming public spaces he makes proposals for social events, some of which are carried out, as for example when he scheduled a programme of yoga classes to take place in a gallery under and around his Perspex platforms.', 4034, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4035, 'Gillick&#x2019;s approach is ideological; part social scientist, part philosophical theorist, part artist, part liberal political.', 4035, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4036, 'He presents a vision of the world which has clean lines, perfectly considered typographic style, well designed building, where history can be reconsidered and there is a lot to read.', 4036, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4037, 'Kersten Glass', 4037, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4038, 'British artist born in the 1970s who paints images of female models from magazines, juxtaposed in the manner of a collage, with a text title running across.', 4038, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4039, 'The women are painted realistically, and are fashionably dressed and made up often in punk and Goth style.', 4039, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4040, 'The paintings echo 1980s design.', 4040, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4041, 'Margarita Gluzberg', 4041, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4042, 'British artist born in the 1960s who makes very realistic detailed pencil drawings of women, about two metres high.', 4042, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4043, 'Robert Gober', 4043, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4044, 'American artist born in the 1960s, Gober&#x2019;s work consider the human body and landscape.', 4044, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4045, 'He has made a series of works using wax casts of his body parts, for example legs and hands.', 4045, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4046, 'These are realistically finished down to the last hair, and installed in odd ways, for example a leg and foot may project from the wall at a right angle.', 4046, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4047, 'He has made many installations featuring body parts, for example a room papered with the artist&#x2019;s own design of wall paper, a forest of trees with sinister things going on among them and leg sculptures sticking out of wall.', 4047, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4048, 'Another theme is that of &#x2018;orifices&#x2019;.', 4048, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4049, 'Gober will often make circular openings with metal facings and plugholes, highly finished but ambiguous in terms of position and function.', 4049, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4050, 'It is as if the external world is seen as a metaphor for the human body, and the orifices in the world might lead to a mysterious interior which provokes both curiosity and repulsion.', 4050, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4051, 'Everything Gober makes has a highly detailed finish and exactly specified materials.', 4051, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4052, 'In the early 2000s he began to make huge scale installations, for example a large gallery space which is empty apart from a small grill in the floor.', 4052, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4053, 'Looking through this grill it is possible to discern an apparently real river bed and pool stretching under the floor, creating the impression that the whole gallery floor is covering a piece of nature.', 4053, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4054, 'Somewhere there is a figure of Christ.', 4054, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4055, 'Gober also made a piece of work featuring a bridal dress.', 4055, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4056, 'Steven Gontarski', 4056, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4057, 'American artist born in the 1970s who makes figurative sculptures.', 4057, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4058, 'Gontarski began in the late 90s to make life size figures made from fabric sewn tighter in the style of a stuffed toy on top of an armature.', 4058, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4059, 'The figures were distorted human forms made from shiny plastics and vinyl, elongated and featureless, their limbs often joining and intertwined.', 4059, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4060, 'The combinations of fabric alluded to garments.', 4060, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4061, 'Sometimes a part of a garment might be incorporated into the sculpture.', 4061, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4062, 'The lumpy feet might have a stripe referring to, but looking nothing like a trainer.', 4062, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4063, 'Gontarski&apos;s soft sculptures are dancers, made by combining modernist sculptural forms, for example Henry Moore, with elements from club wear.', 4063, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4064, 'Along with the sculptures he made drawings on acetate, and later on Perspex sheet.', 4064, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4065, 'These were simple outlines in fibre tip marker featuring people that he had met and odd lines from their conversation.', 4065, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4066, 'In 2000 Gontarski began to make similar figures from cast fibreglass, finished in one colour of a high gloss lacquer often pearlescent or metallic.', 4066, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4067, 'The figures began to take on a molten morphology, like a mixture of Rodin, Boccioni and the molten baddy in the film Terminator 2.', 4067, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4068, 'The figures twist and dance, and are placed on plinths made of the same material and of a part with the sculpture.', 4068, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4069, 'The plinths are sprayed with graffiti, by graffiti artists that Gontarski has invited.', 4069, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4070, 'Gontarski also made a series of busts in a similar way.', 4070, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4071, 'These refer to the generic bronze bust which one might see anywhere.', 4071, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4072, 'In Gontarski&#x2019;s smoothed out and rendered version, there might be a hole right through the face.', 4072, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4073, 'One is a virgin Mary figure painted in white.', 4073, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4074, 'Douglas Gordon', 4074, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4075, 'British artist born in the 1960s who works in a range of media, including photography, video and text.', 4075, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4076, 'Gordon is fascinated with the visual representation of psychological states, particularly in film.', 4076, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4077, 'He made an installation for which he covered the walls with a list of all the people he knows, their names applied in self adhesive lettering in columns.', 4077, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4078, 'Gordon often uses this type of lettering.', 4078, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4079, 'A small work appeared in a book consisting of a text about looking which ends by stating that by the time the reader has read the text, they will have been reading for 3 minutes.', 4079, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4080, 'He makes a comparison between the time taken to read and the time taken to look at images.', 4080, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4081, 'Gordon has made a number of video and film works.', 4081, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4082, 'He often uses back projection onto freestanding or hanging screens in the gallery.', 4082, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4083, 'One work shows a film from the thirties of two psychoanalysts talking to and subsequently restraining a hysterical female patient, finally pinning her down.', 4083, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4084, 'The film is presented played forwards and backwards, resulting in very different interpretations on the viewers part.', 4084, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4085, 'This deconstruction of found film led eventually to Gordon&#x2019;s best known work, 24 Hour Psycho.', 4085, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4086, 'The film of the same name is projected the gallery wall, slowed down so that it takes 24 hours to play from start to finish.', 4086, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4087, 'The gallery remains open during this time.', 4087, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4088, 'The Resulting film provokes all kinds of new readings, and the extreme slow motion renders the famous shower scene entirely different.', 4088, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4089, 'Gordon has made many works on paper including a number of photographs of film stars with the eyes cut out or replaced with plain paper, and a number of photographs of apparent actions such as his black finger tattoo, a photograph of his finger which is entirely black.', 4089, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4090, 'Felix Gonzales Torres', 4090, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4091, 'American artist born around 1960 who made sculptures and installations.', 4091, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4092, 'Gonzales Torres died in the late 1990s.', 4092, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4093, 'During his lifetime his father died as did many of his friends from AIDS related illness.', 4093, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4094, 'His work is preoccupied with death.', 4094, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4095, 'Gonzales Torres used a variety of media, usually with minimal intervention on his part.', 4095, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4096, 'The work he did was in choosing his material, decisions about quantity and placement.', 4096, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4097, 'For example he presented a simple stack of his own weight in sheets of newsprint.', 4097, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4098, 'The weight of his dead father in ivory coloured sweets, is laid out in an amorphous shape on the floor, the sweets are the same colour as bone and the visitor is invited to take one away.', 4098, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4099, 'A way of giving out the body of his father in an obvious parallel with the Transubstantiation.', 4099, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4100, 'This is one of a series of candy works, using different colours of sweets arranged in different abstract shaped heaps on the floor according to the subject of the work (given in the title) always to be taken away so that the work changes through interaction.', 4100, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4101, 'Another series of works are bead curtains, floor to ceiling, strung across the width of a gallery to bisect or divide it creating a new space, partially transparent, the beads are of certain specified colours.', 4101, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4102, 'One work included a performative element.', 4102, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4103, 'A Male dancer naked except for silver shorts and boots danced on a podium surrounded by lights.', 4103, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4104, 'When the dancer wasn&#x2019;t there the podium remained as the work, a plinth for an absent sculpture, the dancer, symbolic of death, the final curtain and the performance of life.', 4104, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4105, 'Gonzales Torres also made a series of light bulb works, strings of standard light bulbs to be strung in specific locations, in a tree, a stairwell for example.', 4105, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4106, 'He also made photographic works, the most well known of which is an empty bed with white sheets each of the pillows bearing the impressions left by a head.', 4106, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4107, 'Another is a photograph of flowers growing in bare soil, which is titled The Grave of Gertrude Stein.', 4107, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4108, 'Gonzales Torres&#x2019; work deals with death, the fleeting nature of life, and the idea of the memorial, by using the simplest sculptural forms.', 4108, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4109, 'Rodney Graham', 4109, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4110, 'Canadian artist born in the 1950s who since the 1980s has made works in film, video, installation, photography and sound.', 4110, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4111, 'Graham made a video showing himself as Robinson Crusoe lying beneath a palm tree sleeping until a coconut drops onto his head from the tree.', 4111, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4112, 'He sits ups, rubs his eyes, tries to focus, feels dizzy and lies down only to have the same thing happen again, and in fact the film is a loop.', 4112, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4113, 'This work portrays the endless loop of time lived out by Crusoe while stranded.', 4113, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4114, 'Another film shows a house burning down.', 4114, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4115, 'Graham made a sound work in which he took a segment of a piece of classical music which is not usually played when that piece is performed, analysed it and added it to make a playable loop.', 4115, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4116, 'He then arranged for an orchestra to play it and had it recorded.', 4116, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4117, 'Graham took a photograph of a tree in winter, and presented it upside down.', 4117, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4118, 'The branches of the tree become the roots, and the roots the branches.', 4118, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4119, 'On the theme of the inverted or retinal image Gordon also installed a pinhole camera in a horse drawn carriage, giving the viewer the opportunity to enter the carriage and view the scene outside through the camera upside down.', 4119, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4120, 'Gregory Green', 4120, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4121, 'American artist born in the 1960s who makes installation and sculpture.', 4121, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4122, 'In the early 1990s Green made an installation in a small room for which he constructed an imaginary IRA bomb factory from scratch by reading books and information freely available to the public.', 4122, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4123, 'The process of bomb making is shown taking place in a small kitchen, the materials needed strewn everywhere, empty cups and ashtrays, food and food wrappers, plates the evidence of long hours of work taking place.', 4123, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4124, 'The drain gin board contains canisters of weed killer and bags of sugar, the materials used to make explosives, and there are five litre plastic bottles with liquid undergoing some process of transformation.', 4124, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4125, 'A table is crammed with electrical equipment and tools, mostly ordinary domestic materials such as light switches, plugs, fuses, wire, insulating tape, cable connectors.', 4125, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4126, 'There is a bomb maker&#x2019;s manual open on the table.', 4126, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4127, 'The verisimilitude is such that the viewer cannot avoid the feeling that they are trespassing in a place where an illegal activity is taking place.', 4127, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4128, 'The viewer feels jumpy, as if they might be discovered by the perpetrators who they feel might be dangerous.', 4128, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4129, 'The effect of the installation is to show how close to daily life, how enmeshed in the everyday is the potential to kill.', 4129, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4130, 'Green also made several bombs complete but lacking explosive and detonators.', 4130, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4131, 'These attracted the attention of the tabloid press and in some cases the gallery that exhibited was forced to remove them.', 4131, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4132, 'One was a suitcase bomb, one was even a nuclear device, complete except for the plutonium.', 4132, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4133, 'Subsequently Green set up a pirate radio station and broadcast illegally to a free state that he had created.', 4133, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4134, 'Renee Green', 4134, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4135, 'American artist born in the 1960s, Green is known for her large scale interactive installations which have a socio political genesis.', 4135, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4136, 'In the late 1990s Green made an installation that filled a gallery with a maze like partition board structure consisting of a series of spaces, the walls painted in different colours, sometimes plain, sometimes striped.', 4136, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4137, 'Viewers walked through the structure, choosing to stop where they wished.', 4137, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4138, 'Videos are presented on monitors on the floor with bean bags and headphones strewn about.', 4138, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4139, 'Written participation in a survey is invited.', 4139, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4140, 'Photographs are on the walls.', 4140, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4141, 'One space has sitting room furniture.', 4141, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4142, 'One has a record collection and a record player.', 4142, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4143, 'Overall the viewer enters a microcosmic world that represents daily life and is asked to consider and participate in activities that illustrate how identity is constructed and how it might be possible to think in new ways about its construction.', 4143, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4144, 'Johan Grimonprez', 4144, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4145, 'Belgian artist who made a video work in the late 1990s D I A L History.', 4145, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4146, 'This projected film consists of vast amount of excerpted footage from newsreels, film and television that concerns terrorism, specifically the hijacking of an aeroplane.', 4146, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4147, 'Grimonprez has edited this footage to make a short film showing the history of hijacking and the imagery that we have of such events.', 4147, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4148, 'Lucy Gunning', 4148, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4149, 'British artist born in the 1970s who made a video titled Climbing Round my Room (mid 1990s).', 4149, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4150, 'Gunning negotiated the perimeter of her room without touching the floor, which involved climbing to the top of a wardrobe and balancing precariously on various items of furniture and using door handles and steps.', 4150, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4151, 'The resulting video presented a re articulation of an ordinary domestic space.', 4151, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4152, 'Andreas Gursky', 4152, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4153, 'Swiss photographer who takes pictures of banal scenes in which the minute is contrasted with the gigantic, creating a formal image which in some cases becomes almost abstract.', 4153, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4154, 'Gursky heightens this effect by manipulating the image in the darkroom, often altering the perspective so that the image reads as a flat picture plane rather than a representation of perspective.', 4154, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4155, 'There is usually a repetitive pattern created by the presence in the images of a mass of something, for example people or windows.', 4155, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4156, 'These effects are subtle and subversive.', 4156, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4157, 'Examples of Gursky&apos;s work from the 1990s include a container park at the port of Ferrara, where the bright colours of the containers form a patchwork pattern on the background of red soil and glowing pink light.', 4157, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4158, 'The floor of a Siemens factory is a mainly white image in which the black lines for the production line furniture and the bright colours for the electrical cable supplies create a pattern.', 4158, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4159, 'The Japanese stock exchange is a pattern in yellow and black with white added by the presence of cascading tickets and the striped jackets of the trader.', 4159, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4160, 'An expanse of plain carpet seems to be vast, skiers on slope are sticks of colour in a white space, a race course in Japan can be read as horizontal bands of colour, the display case in a Prada shoe shop is alive with glowing jewelled colour, a shopping centre is presented as bands of brass and greenery as the escalator travel down through the main atrium, a vast apartment block is a pattern of squares, a canal and dyke are horizontal stripes ! Graham Gussin.', 4160, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4161, 'British artist born 1960s who makes drawings and sometimes installations.', 4161, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4162, 'Around 1999 Gussin made a sound sensitive floor that made sounds in response to the viewer&#x2019;s footsteps, producing a re articulation of the viewer&#x2019;s action in looking.', 4162, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4163, 'Gussin made some drawings of the sound produced in this way using a computer programme that represented the sound waves as a perspective drawing.', 4163, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4164, 'Fabrice Gygi', 4164, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4165, 'Swiss artist born in the 1960s who makes installations.', 4165, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4166, 'These consist of structures in metal wood rubber and plastic, which apparently have practical function but in fact are difficult to decipher.', 4166, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4167, 'The structures or groups of structures might fill a room.', 4167, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4168, 'They have frames made from some kind of metal pole, put together using clamps and off the shelf heavy duty fixings.', 4168, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4169, 'There might be a screen like structure, a bench like one, a platform.', 4169, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4170, 'The frames might be filled in with plastic or rubber sheeting, hemmed and edged with large eyelets and then laced to the frame.', 4170, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4171, 'A bench might have an upholstered top.', 4171, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4172, 'The elements reference the gym and the club, which here seems to be an arena that implies sex and possibly violence.', 4172, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4173, 'Yet they are benign mysterious objects that invite human interaction.', 4173, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4174, 'Matthew Hale', 4174, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4175, 'British artist born in the 1960s who makes performance videos and assembled sculptures from household objects that hint at performative action.', 4175, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4176, 'Hale was one of the founders of City Racing, an artist run gallery in London in the 1990s.', 4176, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4177, 'Siobhan Hapaska', 4177, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4178, 'Irish artist born in 1965 who makes sculptures and installation.', 4178, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4179, 'An early work was eight identical life casts of a clothed young man, painted in buff colour, bearing a coffin.', 4179, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4180, 'Made in 1990s, this work seemed like a comment on the number of young men who were dying from AIDS related illnesses at that time.', 4180, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4181, 'He has also made a vaguely heart shaped wall mounted &#x2018;speaker&#x2019; constructed from teak veneer and purple felt, with a heartbeat sound playing from it.', 4181, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4182, 'St Christopher Legless was included in a room sized installation featuring a fibreglass body cast or lifelike sculpture of the saint in rags and long black beard, sitting against the wall with amputated or cut off legs, an irony for this patron saint of travellers, or a cruel blow dealt to him deliberately.', 4182, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4183, 'Echoes of kneecapping punishment in the conflict in Northern Ireland.', 4183, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4184, 'There was also a fibreglass sculpture of a motorbike, whose contours and mechanics had been smoothed out and filled in so that the whole bike turned into a kind of futuristic vehicle.', 4184, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4185, 'This was indeed reminiscent of the sculptures of Boccioni but also somehow of Rodin.', 4185, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4186, 'It was sprayed in a pearlescent white and highly polished.', 4186, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4187, 'Also a large bedlike structure, a futuristic sleeping platform made from shiny white lacquered fibreglass, the platform with ergonomic curved base, with a slit running all round the inset mattress area, from which water was pumped and ran over the sides of the base in a constant water curtain.', 4187, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4188, 'The mattress of shaggy fur, with a harness and headphones suggesting that one could strap oneself in and be transported, not literally but mentally, by the comfort and the sound and the trickling water.', 4188, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4189, 'The bed, like the motorbike, seemed to come from science fiction.', 4189, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4190, 'Mark Harris', 4190, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4191, 'British artist born around 1960 who makes conceptual work.', 4191, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4192, 'David Harrison', 4192, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4193, 'British artist born in the 1950s who makes autobiographical sculpture, paintings and drawings.', 4193, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4194, 'Harrison&#x2019;s work has a na&#xef;ve quality, the paintings are small, around 60 cm high, and sometimes awkwardly painted.', 4194, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4195, 'The drawings are made in pencil.', 4195, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4196, 'In his early work in the 1980s Harrison concentrated almost exclusively on painting cats with a highly stylised 50s appearance.', 4196, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4197, 'Later Harrison began to describe his own life and lives like his more literally in terms of encounters with people, animals and landscape.', 4197, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4198, 'For example, several paintings feature a caravan in a rural setting, and include the name of a purported guest to the caravan in the title, for example British footballer Paul Gascoigne.', 4198, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4199, 'In some of the caravan paintings a mysterious white rabbit hovers, ghost like, as if it represents the spirit of something.', 4199, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4200, 'Harrison&#x2019;s sculptures are assemblages of objects to resemble animals, in the spirit of Picasso.', 4200, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4201, 'Forks, table legs and any kind of discarded objects are given new roles as the legs of a heron, a bird&#x2019;s beak.', 4201, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4202, 'The sculptures junk like appearance belies their accurate resemblance to the animal they represent.', 4202, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4203, 'Marcus Harvey', 4203, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4204, 'Marcus Harvey is a British painter born in the 1970s who is interested in using paint and its application to produce a hidden image, or conversely to produce an image by an unusual means of application of paint.', 4204, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4205, 'Harvey made a series of works in the 1990s, which on first inspection appear to be abstract paintings with lots of impasto and brushstrokes.', 4205, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4206, 'In fact superimposed are outlines of women taken from pornographic images painted in thin black lines merging into the abstraction.', 4206, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4207, 'Once recognised, however the images are very clear.', 4207, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4208, 'In 1999 Harvey made a painting of Myra Hindley, a convicted child murderer still serving her sentence at the time, which became notorious.', 4208, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4209, 'This painting became famous by the constant press interest in the story.', 4209, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4210, 'Harvey made the ten metres high portrait, taken from the police mug shot, from the handprints of children.', 4210, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4211, 'The handprints in varying shades from white to dark grey form a kind of pixel effect, creating and image that only appears in full detail from distance, much like the effect of a billboard poster.', 4211, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4212, 'Jun Hasewaga', 4212, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4213, 'Korean artist working in Britain, born in the 1970s.', 4213, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4214, 'Hasewaga makes paintings of people on board, in shiny gloss paint with solid outlines, and then cut out.', 4214, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4215, 'Thomas Helbig', 4215, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4216, 'German artist born in the 1960s who makes paintings on hessian.', 4216, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4217, 'Matthew Higgs', 4217, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4218, 'British curator and artist born in the early 60s who makes works on paper.', 4218, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4219, 'Higgs&#x2019;s dry witty conceptual work re presents book covers, pages from books and titles, making plays on words and puns.', 4219, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4220, 'He will often make a text work in which a book, or a title is transformed by minimal intervention into a reference to the visual.', 4220, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4221, 'One series of works involved obliterating all the words on a page except the words &#x2018;There is a painting on the wall&#x2019; and placing this framed page next to a painting by another artist.', 4221, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4222, 'Higgs also made an artists publication series called Imprint 93 (from 1993 onwards) for which he invited artist to make a small pamphlet.', 4222, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4223, 'This activity bridges his practise as an artists and his work as a curator.', 4223, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4224, 'Roger Hiorns', 4224, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4225, 'Thomas Hirschhorn', 4225, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4226, 'German artist born around 1960 who makes large scale environments and installations.', 4226, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4227, 'Hirschorn&#x2019;s work evolves from a life as art philosophy that leads him to create environments and make related publications.', 4227, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4228, 'He uses found imagery, and all kinds of materials in his work, building large architectural structures in a homemade way from cardboard, silver foil, plastic bags, and any number of other found items and materials.', 4228, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4229, 'Damien Hirst', 4229, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4230, 'British artist born in the early 1960s who became one of the best known contemporary artists in Britain when he exhibited a shark preserved in formaldehyde in a glass tank titled The Impossibility of Death in the Mind of Someone Living.', 4230, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4231, 'Hirst is considered to have been the impetus fro a generation of British artists known as the Young British Artists (abbreviated to YBAs) because he curated an exhibition in an empty warehouse titled Freeze.', 4231, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4232, 'This featured his contemporaries (they were all still students) at a time when it was nearly impossible for young artists to exhibit their work in London galleries.', 4232, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4233, 'The term YBAs went on to become the collective name for all of Hirst&#x2019;s generation, including Jake and Dinos Chapman, Tracy Emin, and Sarah Lucas.', 4233, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4234, 'Hirst&#x2019;s work was purchased by the London Collector and advertising executive Charles Saatchi, who financed the shark and subsequent formaldehyde works.', 4234, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4235, 'Saatchi had the only gallery in London at the time big enough to exhibit these works.', 4235, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4236, 'Hirst made a number of formaldehyde works including a cow and her calf sliced right through into two vertical halves, exhibited in two pairs of tanks so that the viewer could walk throng the centre of the cow and the calf.', 4236, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4237, 'He also made a work consisting of a glass wall case filled with rows of fish of different species preserved by taxidermy, all facing the same way (Fish Swimming in the Same Direction) Hirst has made many paintings which fall into three series, the spin paintings (done on a circular canvas spinning horizontally which has multicoloured gloss paint thrown at it), the spot paintings (multicoloured gloss paint spots on white arranged in rows) and the butterfly paintings.', 4237, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4238, 'The first butterfly paintings were canvases covered with gloss paint in plain colours in the surface of which adhered many different types of butterfly.', 4238, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4239, 'Most recently Hirst has been covering the canvas entirely with the wings of butterflies, arranged in geometric patterns.', 4239, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4240, 'Hirst&#x2019;s paintings are made by assistants to his instructions and produced in large numbers.', 4240, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4241, 'The spot paintings have become Hirst&#x2019;s logo, and these signature spots adorned first the restaurant that Hirst opened with Charles Saatchi in London, The Pharmacy, then a Thames riverboat which takes visitors between the two Tate galleries, and finally an unmanned space vehicle which has been sent to Mars.', 4241, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4242, 'Life and death are the major preoccupations of Hirst&#x2019;s work made evident by his use of formaldehyde, insects, and medical drugs.', 4242, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4243, 'Following his work with butterflies, Hirst used flies; a cow&#x2019;s head was placed inside a three metres high glass tank, and maggots were allowed to breed in it.', 4243, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4244, 'These turned into flies, which could fly around inside the tank and an interconnected one in which there was a desk and a chair.', 4244, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4245, 'The flies eventually died, having lived their entire lives in the sealed tank.', 4245, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4246, 'Medical drugs are used by Hirst to represent both life and death and he has made several works using bottles, cartons, boxes, tubes, and other containers of drugs.', 4246, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4247, 'These are arranged in glass wall cases showing their predominantly white packaging with blocks of a huge variety of colours giving a particular visual effect when seen in the context of a gallery.', 4247, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4248, 'Hirst made a room sized installation titled Pharmacy, which contained these cases on all the walls as well as some of the oversized red, green and blue coloured glass decanters that are seen in pharmacist&#x2019;s windows.', 4248, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4249, 'Hirst also made a feature film with many of his friends as actors, shot on 35 mm with high production values.', 4249, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4250, 'In 2003 Hirst continues to make formaldehyde works, for example glass tanks containing animals&#x2019; heads with knives plunged into them, or with blood spattered on the wall around them.', 4250, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4251, 'Damien Hirst&#x2019;s work is often lampooned by the national press in cartoons.', 4251, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4252, 'Hobbypop', 4252, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4253, 'Group of German and British artists who work collaboratively.', 4253, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4254, 'Hobbypop are based in London.', 4254, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4255, 'Their paintings are often installed both on the wall and propped at angles in the centre of a gallery space.', 4255, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4256, 'The group also initiates events including guided walks, and theatrical performances.', 4256, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4257, 'Nicky Hoberman', 4257, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4258, 'British artist born in the 1960s who makes large (up to three metres high) paintings of children.', 4258, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4259, 'These are done from photographs taken by the artist of children she meets.', 4259, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4260, 'They are painted as if there is a strange, often green or bluish light cast upon them.', 4260, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4261, 'The children have exaggerated features and seem to exist in some other world.', 4261, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4262, 'There is something sinister yet saccharine about the children.', 4262, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4263, 'Hoberman applies paint smoothly and thinly, all brushstrokes softened out.', 4263, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4264, 'Candida H&#xf6;fer', 4264, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4265, 'Photographer born around 1960 who has photographed zoos, libraries and various other institutions.', 4265, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4266, 'Her images often show glamorous ornate surroundings yet have a cool restrained atmosphere.', 4266, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4267, 'Evan Holloway', 4267, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4268, 'American artist who makes skeletal models of buildings from twigs and skeletal frameworks from multi coloured metal rods.', 4268, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4269, 'Georgie Hopkins', 4269, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4270, 'British artist born in the late 1960s.', 4270, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4271, 'Roni Horn', 4271, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4272, 'American artist working from the 1980s onwards.', 4272, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4273, 'Kate Howard', 4273, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4274, 'American video artist born in the 1960s.', 4274, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4275, 'Douglas Huebler', 4275, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4276, 'Canadian conceptual artist.', 4276, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4277, 'Des Hughes', 4277, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4278, 'British artist born in the 1970s who makes resin cast sculptures of junk.', 4278, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4279, 'For example Hughes might model old nails in clay and cast them, painting them to look exactly like the real thing.', 4279, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4280, 'Marine Hugonnier', 4280, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4281, 'French artist who made a film over several months spent in Afghanistan.', 4281, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4282, 'Gary Hume', 4282, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4283, 'British artist who has represented Britain at the Venice Biennale.', 4283, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4284, 'Hume is one of the artists in the group known as Young Births Artists or YBAs who emerged in the early 90s.', 4284, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4285, 'Hume began his career making paintings from hospital doors, which he painted all over with white or cream coloured gloss paint.', 4285, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4286, 'In fact gloss household paint has become Hume&#x2019;s trademark and he never uses anything else.', 4286, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4287, 'Hume went on to make figurative paintings mostly portraits in which he vastly simplified the elements of a face, so that it consisted of one or two areas of colour and no features.', 4287, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4288, 'The paint was poured on, allowed to dry, and then the next colour added.', 4288, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4289, 'The edge of the dry part acts as a barrier to the next colour.', 4289, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4290, 'Hume painted the model Kate Moss, a virgin Mary and other images taken from famous paintings, and a baby.', 4290, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4291, 'He featured plants, and vague interiors, but all in his vastly simplified blocks of shiny colour.', 4291, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4292, 'The paintings nearly resist interpretation, which is Hume&#x2019;s intention.', 4292, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4293, 'He made a video in which he portrays himself as King Canute.', 4293, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4294, 'Around 2000 Hume began to make sculptures, bronze snowmen, very smoothed out shapes painted in shiny pale colours.', 4294, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4295, 'Per Huttner', 4295, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4296, 'Swedish artist who make socially inclusive work in which he often invites the viewer to participate.', 4296, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4297, 'Pierre Huyghe', 4297, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4298, 'Swiss artist who makes photographs and videos.', 4298, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4299, 'One photograph shows a stone frozen in mid air over a motorway.', 4299, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4300, 'The stone looks like a boulder implying impending tragedy as it will surely cause a terrible accident, until the viewer realises that it is a tiny pebble that has been photographed as it drops from a bridge over the speeding cars.', 4300, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4301, 'Cathy de Monchaux', 4301, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4302, 'British artist born in the 1960s who makes sculptures and installations.', 4302, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4303, 'De Monchaux made a number of wall mounted works in the early 1990s from machined metal templates, bolted together with velvet, fur and leather often red or purple or black which was clamped between the metal but spilled out in carefully contrived folds.', 4303, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4304, 'These constructions had a sexual fetishistic quality, they hinted at a purpose but remained ambiguous.', 4304, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4305, 'They have a slightly gothic appearance but also a heavy metal aesthetic.', 4305, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4306, 'Put simply they contrasted the supposedly masculine with the feminine, the functional with the luxurious to create decidedly feminine and visceral forms, which often alluded to the female body and genitalia in particular.', 4306, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4307, 'De Monchaux continued to develop this way of working by expanding the scale of her sculptures, making repeating units and larger more complex forms, using a wider palette of coloured fabric and other materials, and sometimes making floor based installations.', 4307, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4308, 'Yasu Ichige', 4308, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4309, 'Japanese artist living in London, Ichige makes videos usually featuring himself.', 4309, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4310, 'In one he places a car directly in front of a wall and puts his foot on the accelerator, driving into the wall without moving until the tyres catch fire and the engine gives up.', 4310, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4311, 'Another shows Ichige enter an amusement arcade dressed in full racing driver gear.', 4311, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4312, 'He sits in a seat in front of a racing game and plays the game, winning the race without dropping any points.', 4312, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4313, 'We see the game from his point of view.', 4313, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4314, 'Inventory', 4314, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4315, 'British artist group who make socially engaged and political work and publish a journal, Inventory.', 4315, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4316, 'Inventory&#x2019;s work usually consists of installations, often some kind of stand or kiosk like structure, with a variety of photographic and text works.', 4316, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4317, 'They take the position of proselytisers for a new way of life, highlighting the dystopian elements in everyday life and imagining collective actions.', 4317, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4318, 'An example is a photo collage of London in 2002 showing the city as if it were about to collapse.', 4318, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4319, 'Inventory have spray painted anti American slogans on the walls of a museum in which they were invited to show.', 4319, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4320, 'Jim Isermann', 4320, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4321, 'American artist who makes multicoloured tapestry quilts and cubes.', 4321, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4322, 'The tapestries hand stitched in repeated geometric patterns.', 4322, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4323, 'Runa Islam', 4323, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4324, 'Twentieth century artist who makes films that are concerned with ethnicity.', 4324, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4325, 'Christian Jankowski', 4325, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4326, 'German artist born in the 1970s who makes video, installation and sound work.', 4326, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4327, 'In Bank, Jankowski hired security guards to keep people out of a empty disused bank, the result of which was that people wanted to enter a space they ordinarily would have ignored.', 4327, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4328, 'In another work Jankoswki recorded a board meeting at a national art museum, and then got children to speak the transcript.', 4328, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4329, 'Because the children had no understanding of the issues discussed they gave the transcript an entirely new and rather odd emphasis.', 4329, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4330, 'Jankowski often uses actors.', 4330, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4331, 'In another work he asks actors to record the reading of the extended email correspondence between himself and his girlfriend when they were apart for several months.', 4331, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4332, 'Again he was interested in the different inflexion and emphases given to the transcript.', 4332, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4333, 'Jankoswki is interested in what happens if slight subversions are made to everyday materials and locations.', 4333, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4334, 'Chantal Joffe', 4334, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4335, 'British artist born in the 1960s, Joffe paints children and women in loose expressive style.', 4335, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4336, 'Her paintings are usually very small, no more that 20 or 30 cm high, made on board with oil paint.', 4336, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4337, 'She uses photographs as her source.', 4337, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4338, 'Joffe often exhibits groups of paintings together arranged in a line or on a grid pattern.', 4338, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4339, 'Alison Jones', 4339, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4340, 'British figurative painter who began working in the 80s and 90s.', 4340, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4341, 'at the beginning of 2000 Jones began to make site specific installations by painting directly on walls using projections of shadows (for example of people who might inhabit the room someone on their hands and knees vomiting, or a cleaner going about their work, painted in flat black silhouette) and by wallpapering architecturally complex sections of the interiors of buildings using multicoloured striped wallpaper.', 4341, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4342, 'Gareth Jones', 4342, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4343, 'British sculptor, formerly a critic and curator, Jones makes singular and highly crafted objects, a red yellow and blue cube with one side missing, a paint handkerchief made by painting several layers of white paint onto a handkerchief and peeling off the paint, a peacock feather stuck into a wall, works using unspoiled cassette tape, stainless steel minimal box floor pieces, a series of plinths made of different materials, some with words on, commenting on the display of art and turning the plinth in art object, a cape made of raffle tickets, works using LP covers, drawing pins, tape, and architectural model like constructions.', 4343, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4344, 'Often a homage to a musician, for example David bowie.', 4344, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4345, 'Sarah Jones', 4345, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4346, 'British artist who makes hard edged abstract pattern paintings that take the facades of modern buildings as her subject.', 4346, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4347, 'She minimises the detail in these and produces brightly coloured grids which have a perspective to them, the grid is in white.', 4347, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4348, 'The high gloss paint is meticulously neatly applied.', 4348, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4349, 'Zebedee Jones', 4349, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4350, 'British painter born in the 1970s who makes abstract paintings by putting a vast quantity of very thick oil paint in a single on a canvas (usually under one metre high) and spreading it across the canvas leaving the brush marks readily visible.', 4350, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4351, 'His paintings are really no more than thick layers of paint and as such they draw attention to the physicality of painting.', 4351, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4352, 'Ben Judd', 4352, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4353, 'British artist born around 1970 who takes photographs that allude to glamour photography, using amateur techniques such as Vaseline on the camera lens.', 4353, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4354, 'In 2002 he began making short video films that show groups of people involved in photo shoots and film making watching the actors and models, who are never shown.', 4354, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4355, 'Judd&#x2019;s work thus becomes a study of the viewers, of vicarious pleasures, revealing these men in their absorption.', 4355, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4356, 'Isaac Julien', 4356, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4357, 'British artist who makes films, usually presented in two or threes screen forma.', 4357, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4358, 'Julien uses 35 mm film and projects his films in especially exhibition spaces.', 4358, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4359, 'He is interested in masculine identity and sexual and ethnic specificity.', 4359, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4360, 'His films have a still, dream like quality, with high production values.', 4360, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4361, 'Alan Kane', 4361, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4362, 'British artist who worked with Jeremy Deller on a work called the Folk Archive, a collection of British folk and craft objects.', 4362, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4363, 'Ann Teresa Keersmaeker', 4363, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4364, 'Dutch artist ! Seydou Keita.', 4364, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4365, 'An African artist who photographed the extraordinary qualities he found in ordinary people.', 4365, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4366, 'The photographs are black and white.', 4366, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4367, 'Mike Kelley', 4367, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4368, 'US artist making sculptures and drawing, Kelley has a particular interest in history, politics and the state.', 4368, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4369, 'Often uses unwanted and second hand materials, car boot and charity shop purchases.', 4369, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4370, 'Series of formal sculptural works using soft toys, for example a large wall relief made off found soft toys sewn onto a found blanket, which uses abject objects to makes reference to abstract expressionist painting, and highlights craft and homemade qualities, drawing a comparison between different values assigned to cultural production.', 4370, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4371, 'Similar floor pieces &#x2013; two soft toy dogs face each other across a small blanket, somehow an encounter that seems serious and eloquent.', 4371, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4372, 'A number of different sized toys under a large grey blanket entitled Lumpenprole a jokey reference to the greyness and poverty of ordinary working lives and a pun on the German &#x2013; a lumpy grey blanket is just what the work appears to be.', 4372, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4373, 'A large collection of soft toys fills a room neatly laid out on trestle tables, all accompanied by measuring sticks, as if in some kind of statistical survey, post mortem, or the aftermath of a mass disaster like an air crash.', 4373, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4374, 'The soft toys used to represent human kind in its lowliness and vulnerability.', 4374, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4375, 'Kelley manages to use these materials in such a way as to produce a formal sculptural works that have a seriousness that belies their existence as discarded and undervalued objects.', 4375, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4376, 'In fact Kelley eschews conventional art materials on the whole.', 4376, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4377, 'A series of felt banners made in a homespun way, around six feet by four feet, in which he replicates flyers found on the street usually made by grass root organisations bearing populist messages, or even just advertisements.', 4377, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4378, 'An installation called Plato&#x2019;s cave which has large panels with drawings of American leaders like Lincoln accompanied by substantial text all round the wall.', 4378, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4379, 'Drawing with marker pen and use of handwritten text also common in Kelley&#x2019;s work.', 4379, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4380, 'Janice Kerbel', 4380, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4381, 'Canadian artist working in Britain, born in 1969.', 4381, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4382, 'Kerbels&#x2019; work is conceptual and usually research based, and is carried out in variety of media, united by her interest in desire and its link to deception.', 4382, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4383, 'Kerbel&#x2019;s research often involves a degree of controlled risk, and elements of detective work.', 4383, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4384, 'The place of desire in Kerbels work is elucidated by her invention of utopian places and ideal conditions.', 4384, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4385, 'Kerbels earliest works from the early 1990s concern subterfuge and malicious intent.', 4385, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4386, 'A table is laden with jam made from poisonous plants.', 4386, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4387, 'Snippings is a series of minute snippings taken from the clothes of strangers, who remain unaware of this affront.', 4387, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4388, 'The snippings are mounted and titled with the date and the place on the garment and type of garment from which the snipping is taken.', 4388, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4389, 'Trust Me (Remington) is typed on a blue sheet of letter paper, folded once, with a ring stain from a coffee mug on it.', 4389, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4390, 'The letter s has jumped and is higher than the rest as if it had been typed on a manual typewriter in the days when the author of a letter could be traced by mechanical faults in the way a typewriter functioned, such as a raised letter.', 4390, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4391, 'Accompanying this is a disc containing a digital typewriter style font with a raised s that Kerbel has created.', 4391, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4392, 'Kerbel&#x2019;s interest in deception led her to invent four Magic Tricks fro which she designed the apparatus as if it were flat pack furniture.', 4392, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4393, 'The tricks included levitation table and disappearance box.', 4393, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4394, 'Like much of Kerbels work the plans and drawings are the work, which is never actually realised.', 4394, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4395, 'This is intrinsic for the success of the work as it hinges on Kerbel&#x2019;s interest in the desire to do unacceptable or impossible things.', 4395, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4396, 'Places to Bury a Body illustrates this.', 4396, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4397, 'A series of photo pHs show very ordinary places such as a front garden, where there is no obvious hiding space but the acknowledgment that a hole could be dug.', 4397, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4398, 'Or a cliff top over which a body could be thrown.', 4398, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4399, 'Bank Job (1999) consists of two cork board panels onto which are pinned detailed plans for a bank robbery from an existing bank in the City of London.', 4399, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4400, 'There are reconnaissance photographs, detailed floor plans, a map of the getaway route, and an exhaustive time line of the robbery, listing all the participants, entrances and exits, times and vehicles involved.', 4400, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4401, 'Bank Job is a work which presents the inconceivable as something which anyone could carry out.', 4401, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4402, 'A number of Kerbel&#x2019;s works are concerned with how to cheat.', 4402, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4403, 'Home Fittings is a series of floor plans, made for existing rooms and buildings, on which Kerbel indicates where a person might walk in order to avoid any creaking floorboards or flooring, and where a person might stand in relation to doors to avoid casting a shadow that might give away their presence.', 4403, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4404, 'These places are indicated in the space by the insertion of thin brass rods flush with the floor.', 4404, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4405, 'Marked Decks are prints showing the backs of packs of playing cards, the patterns on which have been subtly altered to allow a person in the know to deduce the suit and number of the card.', 4405, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4406, 'A letter typed on blue paper seems to allude to a failed tryst, an unfulfilled desire.', 4406, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4407, 'A number of Kerbel&#x2019;s works deal with this explicitly, for example Bird Island (2000) a web project and book.', 4407, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4408, 'Kerbel invented an island paradise based on a real uninhabited Caribbean island, and designed a website that invited the purchase of timeshare in the island.', 4408, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4409, 'The topography, flora, fauna and the style of the buildings on the island are explained and illustrated in detail.', 4409, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4410, 'The site persuade the viewer to buy into a dream which doesn&#x2019;t exist.', 4410, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4411, 'Any applicants would receive a brochure.', 4411, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4412, 'Kerbel even invented a bird, the Exuma Emerald, which she later illustrated by commissioning a drawing from a bird illustrator and the creation of its potential song from a bird song expert, presented as a cd.', 4412, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4413, 'Further to this Kerbel made a number of drawings of fantasy islands in which she played god, taking control of the climate and thus the flora and fauna.', 4413, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4414, 'In 2003 Kerbel made a series of drawings of hypothetical planters for specified but unnamed buildings.', 4414, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4415, 'The planters and the plants they contained are designed to grow the most suitable plants for the buildings climactic conditions in the best possible way, thus the plant lists take account of light quality and direction, temperature and humidity, the planters make the most of available light and maximise the planting relevant to the size of the space.', 4415, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4416, 'The floor plans indication the light source and type, the scale and disposition of the planters, the function of the building and the climactic conditions There is a respiration garden for a Gym, for example, planters for low light in a Victorian house, a shelf garden for a student room, a hanging garden for a launderette and one for a bathroom both making use of high humidity, and circular garden for a revolving restaurant.', 4416, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4417, 'Karen Kilimnik', 4417, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4418, 'American artist born around 1960 who is primarily a painter, although she has begun to make photographic work in the 2000s.', 4418, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4419, 'Kilimnik&#x2019;s practise is project based.', 4419, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4420, 'She makes work around a particular theme and usually presents it as an installation.', 4420, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4421, 'One such project dealt with the fantasy life of teenage girls, and featured a gallery with purple painted walls, drawings on the walls with lots of text which has a diaristic quality, paintings and autumn leaves strewn on the floor.', 4421, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4422, 'Another had a Russian theme, and has paintings that have qualities of Russian icons, with Russian themes, and snow scenes, objects and stuffed animals and drifts of artificial snow on the floor.', 4422, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4423, 'Kilimnik&#x2019;s paintings are rarely more than 60 cm high.', 4423, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4424, 'Kilimnik has many pets and animals are a constant in her work, in particular a pet cockatoo, a crow called Ralph, and dogs and cats.', 4424, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4425, 'Ralph&#x2019;s portrait, Ralph in Ectoplasm, shows him both as he is and covered in ectoplasm.', 4425, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4426, 'Another installation is based on a detailed study of ballet, in particular Giselle, and features gallery walls painted dark red, the paintings and drawings in black frames depicting scenes from the ballet, imagined related scenes, and a sculpture on a plinth.', 4426, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4427, 'Some of the paintings have black velvet ribbon bows on the frame and silk flowers.', 4427, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4428, 'Kilimnik&#x2019;s work hovers close to kitschness and sweetness which is held in check by her skill as a painter and the darkness of some of her subject matter.', 4428, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4429, 'In 2001 Kilimnik made a series of photographs of central park in New York showing the park in winter in low light conditions.', 4429, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4430, 'By careful framing, the light conditions, and aided by the appearance of a horse drawn carriage used to convey tourists on sightseeing tours, Kilimnik showed the park as if it had been photographed in the nineteenth century.', 4430, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4431, 'These were shown alongside a number of landscapes and cityscapes that are also painted in an anachronistic style.', 4431, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4432, 'Kilimnik&#x2019;s work is distinctive for its combination of rich reference to the past and the history of art with an autobiographical and contemporary approach to painting.', 4432, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4433, 'Scott King', 4433, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4434, 'King is a British artist born in the 1960s and publisher of an magazine called Crash!.', 4434, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4435, 'Crash! is a broadsheet sized magazine written and designed by King and another person, which features anti establishment satire and polemic mixed with cultural criticism and appreciation in the form of poster style text, graphics and images.', 4435, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4436, 'It is witty and uncompromising, and is a hybrid of magazine and art work which is implicitly critical of the magazine publishing industry.', 4436, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4437, 'King&#x2019;s solo work draws on these approaches.', 4437, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4438, 'He has made collages from magazine images and a large number of text works often in the form of numbered lists.', 4438, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4439, 'In the 2000s King&#x2019;s texts became more autobiographical and often self deprecating.', 4439, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4440, 'They are designed and typeset in Kings very visual style.', 4440, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4441, 'One work is entitled &#x2018;Why I Never Became A Punk&#x2019; and consists of a list of the reasons for this.', 4441, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4442, 'Joanna Kirk', 4442, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4443, 'British artist who makes large scale figurative pastel drawings.', 4443, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4444, 'Michael Klega', 4444, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4445, 'German artist born in the 1960s, Klega makes wall drawings form unspoiled cassette tape wound round map pins, sculptures from plastic water bottles.', 4445, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4446, 'He utilises everyday materials like adhesive tape to make his minimal but often dryly humorous works.', 4446, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4447, 'Jochen Klein', 4447, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4448, 'German artist born in the 1960s died in the late 1990s.', 4448, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4449, 'Klein&#x2019;s water colour and collage paintings have an oneric atmosphere, as if the protagonists were lost in time.', 4449, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4450, 'The collage, usually an image from a magazine often a person, is often the starting point for a painting.', 4450, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4451, 'Klein extended the collaged image by painting out from it.', 4451, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4452, 'He used thin washes of colour on a white ground, often leaving areas deliberately unfinished, to make translucent and light filled images.', 4452, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4453, 'He uses Klein also made works on paper including a pop up book made from collaged images featuring a pop up penis as its centrefold.', 4453, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4454, 'Ulli Knall', 4454, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4455, 'Swiss artist living in Britain who makes ceramic sculptures.', 4455, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4456, 'Knall has made a series of small busts of characters from television programmes such as Star Trek, and other invented characters, as well as portraits of her friends.', 4456, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4457, 'These are modelled in a simple almost na&#xef;ve style.', 4457, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4458, 'Other works include small fountains.', 4458, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4459, 'Most of Knall work is on a domestic scale, ranging between 30 to 80 cm high.', 4459, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4460, 'The sculptures are painted and glazed carefully in realistic colours.', 4460, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4461, 'Jutta Koether', 4461, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4462, 'Koetther is a German artist born in the 1960s who makes large messy paintings and drawings with text added.', 4462, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4463, 'These are apparently autobiographical and personal but remain mysterious.', 4463, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4464, 'The paintings are large and scruffy, often appearing to have been made on the floor over a period of time.', 4464, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4465, 'Tania Kovats', 4465, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4466, 'British artists who uses model making materials to construct landscapes on shelves mounted on the wall, grassy hills and valleys with trees, rivers and lakes, microcosmic three dimensional landscapes.', 4466, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4467, 'Elke Krystufek', 4467, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4468, 'Austrian artist born in 1970s whose subject is herself and her own body portrayed in videos, drawings and paintings of herself in her daily life.', 4468, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4469, 'However Krystufek often appears naked, usually made up with the red lipstick which is characteristic of the videos and the drawings, sometimes in an abject state and her work is also a portrait of neurosis.', 4469, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4470, 'Her emotional state is usually unexplained and never indulgent.', 4470, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4471, 'A video self portrait, for example is shot with a hand held (thus never more than arms length away) as she spins around dancing.', 4471, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4472, 'Her own apartment is often the setting for the work.', 4472, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4473, 'Wolfgang Laib', 4473, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4474, 'artist working from the 1990s onwards, Laib makes installations.', 4474, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4475, 'He made a floor work by sifting bright yellow pollen over a large rectangle shape in an even layer, the colour startlingly bright.', 4475, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4476, 'The effect of this work lies in the contrast between the minimal quality of the work, the quantity of the material and the viewers knowledge of the organ and potential of the material and the work required to obtain it.', 4476, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4477, 'Jim Lambie', 4477, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4478, 'British artist working from the 1990s onwards who made a number of floor installations in which the floor of a gallery or museum is entirely covered in stripes made of plastic tape in different colours and widths, the stripes following the floor plan of the room, running round the edge of the room and moving inwards towards the centre of the room concentrically until the centre is reached.', 4478, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4479, 'Sometimes Lambie might use black and whiter tape, or metallics.', 4479, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4480, 'Lambie also made wall sculptures from ordinary domestic objects such as record player turntables, mattresses, mirrors which are covered in glitter.', 4480, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4481, 'Sean Landers', 4481, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4482, 'American artist born in the 1960s who made a number of very large text paintings in the 1990s.', 4482, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4483, 'the text on these paintings is essentially a diary of his life as an artist.', 4483, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4484, 'In these works Landy tries a new way of carrying out the traditional task of the artist to make life into art.', 4484, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4485, 'The canvas of one 3 meter high painting rolls onto the floor at the bottom, reaching toward the viewer implying a physical inclusion in the work, and in the viewing and reading space.', 4485, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4486, 'Landers went on to make a series of very large paintings after famous artists such as Picasso, copying works and adding to them, so that they are instantly recognisable but recognisable different.', 4486, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4487, 'Michael Landy', 4487, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4488, 'Landy is a British artist who was born in the 1960s.', 4488, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4489, 'He began career making obsessively detailed cartoon like drawings in black pen featuring a multitude of images and text.', 4489, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4490, 'These drawings created an alternative world of social and political comment and from them emerged a large scale installation, Scrapheap Services in the late 1990s.', 4490, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4491, 'Scrapheap Services is a fictitious company which carries out the collection and disposal of unwanted members of society.', 4491, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4492, 'What Landy showed was a collection of the trolleys, uniforms, printed literature, signage, bins and waste bags, all bearing the companies logo and livery.', 4492, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4493, 'The paper literature was stern all over the floor as if it were itself rubbish.', 4493, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4494, 'He also made a flower stall.', 4494, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4495, 'Landy&apos;s next large scale work further developed his interest in human waste and the value of inanimate objects, sentimentality and materiality.', 4495, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4496, 'This involved the professional construction of a large waste disposal plant consisting of a conveyor belt for sorting, various grading machines and a compressing, shredding and grinding machines, reducing everything to a pulp.', 4496, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4497, 'Landy passed every single item had every owned through this machine: the contents of his flat, his car, his clothes.', 4497, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4498, 'The item he found most difficult to destroy was his deceased fathers coat.', 4498, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4499, 'The machinery was installed in a temporarily empty department store ground floor and open to the public every day.', 4499, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4500, 'The list of items destroyed remains as the document of the work.', 4500, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4501, 'In 2003 Landy made a number of botanical drawings of weeds species and varieties that might be found growing in the streets and waste areas of London.', 4501, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4502, 'Abigail Lane', 4502, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4503, 'Born in eh 1960s Lane has made a number of installations.', 4503, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4504, 'For one of these she papered a gallery space a wall paper printed with bloody hand prints.', 4504, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4505, 'In the centre of the room a female figure constructed from a collection of clothes, shoes and a wig hung from a rope.', 4505, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4506, 'Langlands and Bell', 4506, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4507, 'Two artists who work together producing works that investigate architecture and the built environment and its relating to the lives of people.', 4507, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4508, 'In the late 1990s they made a work which consisted of a series of white chairs with models of buildings set into seats visible through a glass top to the seat.', 4508, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4509, 'They made a series of works about the panopticon plan for prison buildings.', 4509, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4510, 'Matthew Leahy', 4510, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4511, 'British artist born in the 1970s died in 1999.', 4511, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4512, 'Leahy made landscape paintings in particular snow capped mountains.', 4512, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4513, 'Mark Leckey', 4513, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4514, 'British artist born 1976 makes video and sound installations.', 4514, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4515, 'Leckey&#x2019;s work comes out of club and street culture, but has a serious intent.', 4515, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4516, 'His video Fiorucci made me hardcore shows intercuts footage of the British northern soul scene with hardcore house clubs, edited to make a compelling testament to transcendence through dance and music.', 4516, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4517, 'Other works come out of his experience as a dj.', 4517, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4518, 'Member of the art ban Donatella.', 4518, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4519, 'Marysia Lewandowska and Neil Cummings', 4519, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4520, 'British artists working together who make theoretical conceptual investigations into economies, culture and knowledge, resulting in a socio political project based practise which may be presented in many different forms.', 4520, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4521, 'They made a project in London with the Bank of England which was the result of a period of research.', 4521, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4522, 'They presented documentation of their research and made it possible for museum visitors to interact with their work.', 4522, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4523, 'Mark Lewis', 4523, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4524, 'British artist born in the 1950s who works in 35 mm film and video.', 4524, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4525, 'Lewis&#x2019;s work since the 1980s has stemmed from his interest in and knowledge of the history of cinema.', 4525, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4526, 'He uses the structure and visual language to construct short looped films presented as installations and longer more narrative scripted films using actors.', 4526, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4527, 'Lewis presents everyday scenes and situations through the lens of cinematic production, prompting the viewer to consider the inconsequential as a moment of grandeur, and to question what they are seeing.', 4527, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4528, 'A short looped film made in the late 1990s shot from inside a caf&#xe9; A woman is talking to a man outside on the pavement right in front of the window.', 4528, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4529, 'But there is something odd about their conversation.', 4529, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4530, 'The man doesn&#x2019;t seem to be listening to the woman.', 4530, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4531, 'Eventually a car passes and disappears mid screen.', 4531, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4532, 'Then other traffic does the same, coming from both directions, as do pedestrians.', 4532, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4533, 'Now the viewer begins to think that they are watching a split screen, a convention occasionally used in cinema to show a telephone conversation or to show two things happening simultaneously, and that in fact the couple are not talking to each other but to others.', 4533, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4534, 'Finally it becomes clear that in fact the dividing on the screen is in fact the edge of a mirror on the wall of the caf&#xe9;, which exactly reflect the street outside.', 4534, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4535, 'The woman is in fact reflected in this mirror and is talking to someone else out of view.', 4535, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4536, 'The man is seen through the window and is on his own, waiting.', 4536, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4537, 'A film made in a city housing estate shows a concrete walkway with tower blocks rising above it, the vast empty space punctuated and enlivened by children playing games.', 4537, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4538, 'Another film shows a derelict building of which only the fa&#xe7;ade and floors.', 4538, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4539, 'The camera moves towards the building extremely slowly.', 4539, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4540, 'As it moves the viewer becomes aware of the trajectory of the camera, something that is largely unnoticed usually.', 4540, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4541, 'It is moving in and down from a great height and the shot is continues.', 4541, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4542, 'The camera reaches the building and enters a window.', 4542, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4543, 'On a table in the empty roofless space is a child&#x2019;s spinning top.', 4543, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4544, 'This short looped film places the viewer in the position of the camera and makes the process of filming evident and the subject of the work.', 4544, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4545, 'The camera is finally understood to be on a very high crane which is also moving on a track, usually only associated with big budget film making.', 4545, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4546, 'Another work shows A section of an black and white silent film showing an elevated cast iron railway upside down.', 4546, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4547, 'A landscape work shows an iced over lake in a snowy landscape with a solitary skater on the ice.', 4547, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4548, 'Lewis has made narrative films using actors, including one shot in a garden in California which uses porn actors, one shot in a Californian desert hotel, Peeping Tom (a homage to the feature film of the same name) and The Pitch, which shows Lewis himself standing in the middle of the main concourse of a railway station talking to the camera, oblivious to the people around him.', 4548, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4549, 'By the end of his monologue it becomes apparent that he is pitching the idea for the very film that the viewer is watching directly to the viewer.', 4549, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4550, 'Cedar Lewisohn', 4550, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4551, 'American or Canadian artist who makes abstract pattern paintings and related drawings which reflect his work as a dj.', 4551, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4552, 'Glenn Ligon', 4552, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4553, 'American artist born in the 1960s who made work about black American identity.', 4553, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4554, 'A lot of Ligon&apos;s work took slavery and its legacy as a starting point.', 4554, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4555, 'He made installations and added text to them and also made photographic works.', 4555, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4556, 'A canvas punch bag hanging from the ceiling on a rope has a poetic story of a slave prize fighter stencilled on its white surface in black letters, as if it were both a painting and a sack.', 4556, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4557, 'This object symbolised the body of the slave, captive to be treated as an object, subjected to punches, traded as goods.', 4557, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4558, 'A boxing ring has text inscribed around it in a similar way.', 4558, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4559, 'Ligon made a version of the US Flag drawn in black with words where the stars and stripes would be.', 4559, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4560, 'In his work he drew attention to the objectification of black Americans, particularly black American men.', 4560, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4561, 'Hilary Lloyd', 4561, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4562, 'British artist born in the 1960s who makes video films that she terms sculptures.', 4562, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4563, 'Lloyds films are always presented on a specified size of monitor anything ranging from a portable personal TV with head phones to a large monitor.', 4563, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4564, 'The monitors are placed on monitor stands of a particular type, in particular relation to each other.', 4564, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4565, 'Some works may consist of two monitors places back to back.', 4565, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4566, 'The viewer is never a typically passive receiver, since they have to walk round the monitors and Lloyds work is never shown projected.', 4566, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4567, 'Lloyds films have a minimal sculptural quality.', 4567, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4568, 'She is chiefly interested in people and banal repetitive activities.', 4568, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4569, 'For example, in Colin, made in the mid 1990s, a young man standing on some derelict land between two buildings proceed to slowly pick up, examine and discard the items that he finds there, pieces of wood and metal and other kinds of refuse.', 4569, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4570, 'He does this slowly, very deliberately, as if there were some kind of purpose to his actions, which become quite compelling and graceful in repetition.', 4570, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4571, 'Colin, like most of Lloyd&#x2019;s work involving people, met the artist in a club and she persuaded him to allow her to film him.', 4571, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4572, 'She takes pains to allow her subjects to make their own decisions about what they will do as she films, arrived at through social interaction.', 4572, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4573, 'In this sense she is emphatically not directing the action.', 4573, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4574, 'Other works have featured a man pulling a jumper off over his head played in forward and reverse on back to back monitors so that it becomes a kind of dance.', 4574, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4575, 'There is one of a young man sitting on the floor cutting images out of magazines endlessly.', 4575, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4576, 'There is a film in which two teenage girls hold a length of string between them, one has ball and slowly unwinds it the other winds the string back into a ball.', 4576, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4577, 'The end of the film the girls have transferred the string from one to the other.', 4577, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4578, 'Another film shows a woman in a white trouser suit sitting on a chair one leg resting on the other knee, smoking a cigarette.', 4578, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4579, 'On the point of extinction of the cigarette the film loop begins again.', 4579, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4580, 'Most of Lloyd&apos;s work is looped, including the works that do not feature people such as one which shows a reflection on the surface of water which is somehow read, the film becoming a shimmering abstract pattern.', 4580, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4581, 'The films are always static camera single continuous shots, even one in which Lloyd attaches a camera to a skateboard and asks a skateboarder to skate.', 4581, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4582, 'The resulting film of pavement, ground and then graffiti covered walls as the skateboard goes vertical is accompanied by the sound of the wheels.', 4582, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4583, 'Similarly a film shot again form a static camera placed on the windowsill of the revolving restaurant in the post office tower show 360 degree panorama of London in the time it takes for the restaurant to revolve &#x2013; this is quite slow so the image only changes imperceptibly.', 4583, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4584, 'Lloyd made some films in which two djs are in a taxi going from one job to another, and a text and photographic work which features a dj called princess Julia.', 4584, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4585, 'Later works from the early 2000s show the spray from a fountain against backdrop of trees, ebbing and flowing with the wind and the jet of the water, and a slide projection showing waiters at a caf&#xe9; in St.', 4585, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4586, 'marks square in Venice.', 4586, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4587, 'Lloyd became interested in groups of people observed rather than single people invited to cooperate.', 4587, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4588, 'Lloyds work deals with the still moments in everyday life that can be considered as formal visual and discrete.', 4588, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4589, 'Andy Warhol is a reference point for her work.', 4589, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4590, 'Hew Locke', 4590, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4591, 'British artist who made Cardboard Palace, a maze that fills a gallery from floor to ceiling made from corrugated cardboard sheets cut into shapes a bit like a Frank Stella wall relief, with light bulbs creating shadows.', 4591, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4592, 'The cardboard is left brown with only the black felt pen outlines as adornment.', 4592, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4593, 'The maze leads to a kind of sitting room with a tea table.', 4593, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4594, 'There is lots of documentation about the British Royal Family pinned to the structures of the maze.', 4594, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4595, 'Sharon Lockhart', 4595, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4596, 'American artist born in the 1960s who makes films and photographic work.', 4596, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4597, 'Lockhart&#x2019;s work has an anthropological vision, she is interested in how the cultural life of different society groups is portrayed by those who study it, and in how this can be made visual, or even in how the artist can make a similar portrayal with very different results.', 4597, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4598, 'Lockhart made series of photographs of the inhabitants of dwellings that had been visited and described by anthropologists.', 4598, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4599, 'The dwellings are shown uninhabited, and the inhabitants shown separately.', 4599, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4600, 'Lockhart spent some time in Manaus in Brazil making a film set in the town theatre.', 4600, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4601, 'Teatro Amazonia is a hour long single shot film showing the auditorium of the theatre seen from the stage.', 4601, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4602, 'The audience in the theatre watching Lockhart&#x2019;s film are put in the position of performers on a stage watching the audience in Manaus.', 4602, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4603, 'The performance of a piece of contemporary classical music begins, sung by an invisible choir on the stage in the position of the viewers.', 4603, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4604, 'The music begins with the tuning up of the orchestra and then takes the form of a single note of orchestral noise building into a continuously mutating wall of sound, then fading.', 4604, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4605, 'The audience on the screen watch, listen fidget, get up and go out occasionally.', 4605, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4606, 'The minute detail of their behaviour becomes interesting.', 4606, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4607, 'The viewer is able to watch something that would be unwatchable without the suspense created by the voices of the choir.', 4607, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4608, 'The films titles list the audience participants, every single one of them, in groups dictated by the barrio that they live in.', 4608, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4609, 'So that the image of the audience can be seen representing the people of the city of Manaus, and in fact they do this proportionally.', 4609, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4610, 'The numbers of people from each barrio representing the relative population of each barrio.', 4610, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4611, 'This list of names also reveals the family connections of the people of the city.', 4611, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4612, 'Lockhart subsequently made a film in a Japanese gymnasium where a group of women are doing physical drill.', 4612, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4613, 'This is very regimented but balletic in the way that the space seems to be used choreographically.', 4613, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4614, 'Lockhart films in similar choreographed shots to create a mesmeric document of a strict regime, in which the scrutiny of uniformity yields fascination for minute details of difference ! Bridget Lowe.', 4614, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4615, 'British artist born in the 1960s who works with text.', 4615, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4616, 'Lowe made a work in which she took the titles of books and typeset them as a continuous text.', 4616, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4617, 'She also made a work fro the web in which a text is presented to the viewer at a controlled pace.', 4617, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4618, 'Colin Lowe and Roddy Thompson', 4618, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4619, 'British artists who work together, both born in the 1960s.', 4619, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4620, 'Lowe and Thompson have for a number years been conducting tongue in check correspondence with businesses, public agencies and institutions about art and artists.', 4620, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4621, 'They make outlandish requests, complaints or suggestions but these are made in absolutely conventional ways, most often in the form of letters which themselves constitute the artist&#x2019;s work.', 4621, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4622, 'They have also made site specific work including street banners.', 4622, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4623, 'Sarah Lucas', 4623, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4624, 'Lucas is a British artist born in the 1960s, one of the so called Frieze generation of artists who were working in London in the early 1990s.', 4624, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4625, 'She was a close friend of Tracy Emin&#x2019;s at this time and the two artist&#x2019;s opened a shop together.', 4625, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4626, 'Lucas&#x2019;s work shows a preoccupation with sex death and female identity within a framework of humorous abjection.', 4626, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4627, 'The work with which she became known was a mattress from a double bed placed against a wall, hall of it propped up, half on the floor.', 4627, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4628, 'Inserted in openings cut in the mattress were two melons at the top on one side and a bucket on the part resting on the floor below them, whilst on the other side a cucumber was inserted at an angle of 45 degrees from the mattress, at the same level as the bucket.', 4628, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4629, 'This was a crude but very expressive representation of the male and female forms reclining in bed and like a lot of Lucas&#x2019;s work a crude humour is used in a sophisticated way to represent universal sexual desires by formal but unconventional, and by implication not traditionally male sculptural means.', 4629, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4630, 'Another work in similar vein A Kebab and Two Fried Eggs consist of an old wooden table with two fried eggs placed on it at one end and a pitta bread containing doner kebab at the other end.', 4630, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4631, 'Plainly suggestive of female sexual anatomy, this work also represents the female form lying on a table, suggestive of sexual intercourse in simultaneously humorous and slightly threatening ways.', 4631, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4632, 'Other early works have become iconic, in particular a photographic self portrait, one of a continuing series, of the artist sitting in a chair with feet up on a table at the front of the image nearest the viewer, clad in work boots.', 4632, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4633, 'This uncompromising image presents Lucas as a female artist in male pose and clothes, a subject to which she returns often in these photographs.', 4633, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4634, 'She holds a beer can between her knees and pulls the ring tab, for example, and the beer which has been shaken, spurts upwards.', 4634, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4635, 'She sits on a toilet, her trousers round her ankles.', 4635, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4636, 'Her work boots which she is wearing in all the photos, are shown on their own.', 4636, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4637, 'Lucas often has a cigarette hanging from her lips.', 4637, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4638, 'These and other images portray the artist as a working man, bringing the viewers own preconceptions to their attention.', 4638, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4639, 'Small sculptures, such as a cast of the artists genitalia in a homage to Duchamp (a major influence), Lucas&#x2019;s own work boots with razor blades inserted into the sole at the toes also explore the theme of masculine and feminine identity as well as traditional artist&#x2019;s themes such as the nude body and the self portrait.', 4639, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4640, 'A collage of newspaper images from the Sun newspaper featuring vastly overweight women shows a distorted image of femininity.', 4640, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4641, 'In later works Lucas began to model forms more literally as in her series of sculptures which are covered entirely in cigarettes stuck on in a mosaic pattern, such a s motorbike and an enlarged garden gnome.', 4641, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4642, 'Quite apart from the characteristic inappropriateness of the materials the apparent cost of materials is striking.', 4642, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4643, 'The display of the materials of addiction and over consumption is in tune with the associations with drink in particular beer in the earlier work.', 4643, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4644, 'A car is used in a large installation.', 4644, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4645, 'The car has a mechanism in it that makes it bounce rhythmically, to give the impression that a couple are having sex inside and bouncing on the seat.', 4645, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4646, 'The Bunny Girl is another later work, this is a representation of a playboy bunny girl made from stuffed pantyhose draped on a chair to suggest arms and legs, and a pair of ears and a fluffy tail.', 4646, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4647, 'This utterly abject object conveys both the idea of a bunny girl astride a punters lap, or straddling a chair and the idea of a woman as flesh encased in nylon tights or even of a sex toy, a toy woman.', 4647, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4648, 'Jeff Luke', 4648, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4649, 'British artist born around 1965 died 1996.', 4649, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4650, 'Luke&#x2019;s sculptures are made essentially from rubbish and throwaway materials, yet they have a strongly formal quality.', 4650, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4651, 'His sculptures are often on the floor, usually installed and involving a large number of parts, reminiscent of American scatter art of the late 1970s.', 4651, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4652, 'A number of rubber band balls some about 60 cm in diameter, are arranged on a low plinth, as if they were a Henry Moore or Barbara Hepworth carved stone sculpture.', 4652, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4653, 'Instead the abstract forms, pebble like shapes, are the result of hours of obsessive activity.', 4653, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4654, 'Luke took a mindless doodle like activity and expanded the scale to make a sculpture.', 4654, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4655, 'Cosmetics and toiletries such as hair shampoo and conditioner, cleaning fluids, and other household liquids are places in tiny 2 cm high sample tubes, which are numbered to refer to a key telling the viewer what they contain.', 4655, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4656, 'These are then placed on a shelf in a row, creating a formal work from the great range of colours of the liquids.', 4656, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4657, 'Other works consist of unidentifiable bits of small rubbish (this quality of anonymity, a sense that the object is a part of the unknown larger whole seeming to be the criteria for selection), placed in a careful arrangement on the floor.', 4657, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4658, 'Ken Lum', 4658, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4659, 'Canadian artist ! Christina Mackie.', 4659, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4660, 'Scottish artist born in 1960 who makes sculptures and video, which are conceptual, cool and restrained and have a poetic minimalism.', 4660, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4661, 'Mackie might place a monitor showing a piece of road with traffic sounds next to a railway sleeper, or use a telephone which the viewer can pick up and listen to a sound.', 4661, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4662, 'Monitors are often placed on or situated in constructions made of old timbers.', 4662, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4663, 'Goshka Macuga', 4663, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4664, 'Polish artist living and working in London born 1970, Macuga makes environments in which she curates exhibitions.', 4664, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4665, 'She may create a cave within a gallery from crumpled brown paper, or a snowy mountain scape from fabric, and fill this space with the work of artists that she has invited to participate.', 4665, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4666, 'In 2003 she built a wooden cabinet with many doors and shelves to display works of art.', 4666, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4667, 'Her work as an artist is the exhibition environment that she has created.', 4667, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4668, 'Elisabeth Magill', 4668, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4669, 'British painter born in 1960s who made a series of paintings of luggage seen through an airport security x ray machine.', 4669, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4670, 'Later work includes paintings of trees.', 4670, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4671, 'Martin Maloney', 4671, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4672, 'British artist and former curator who pioneered &#x2018;bad painting&#x2019; in the late 1990s, making very large scale monumental figurative works often based on other paintings for example Poussin, for which he used friends and acquaintances as models in a highly ambitious kitchen sink meets Alex Katz style.', 4672, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4673, 'He also painted still lives and animals, as well as a painting cycle of gay club scenes.', 4673, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4674, 'Maloney&#x2019;s work is distinguished by the speed at which he works painting wet on wet with large brushes at speed, rarely spending more that 6 hours on a work.', 4674, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4675, 'The resulting faux clumsiness was highly controversial but Maloney is representative of a generation of artists who began to make work in hitherto scorned media such as textiles, the so called &#x2018;dumb&#x2019; art which combined a knowing intellectualism with great enthusiasm and joy in materials and a freedom from the tyranny of conventional artistic skills.', 4675, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4676, 'Maloney curated several seminal exhibitions in his own home, including Lost in Space and Die Yuppie Scum and his &#x2018;you can do it if you really want to&#x2019; attitude to success in the art world, combined with a willingness to combine the classical with the trashy made him very successful in the 1990s.', 4676, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4677, 'He works chiefly in oils, but also in watercolour, sticky tape and ceramics.', 4677, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4678, 'Margarita Manzanelli', 4678, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4679, 'An Italian painter born in 1970s who paints young women, often emaciated but fashionably dressed, in the middle of a large canvas with a plain flat background.', 4679, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4680, 'The women are characterised by their monochrome flat backgrounds, thin bodies and large often bulging eyes.', 4680, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4681, 'Christian Marclay', 4681, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4682, 'American artist born in 1957, Marclay worked as a musician and DJ before becoming an artist as well.', 4682, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4683, 'Starting from his interest in music, Marclay makes video, sound and works on paper.', 4683, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4684, 'A 2003 installation consisted of six screen projection arranged in a horizontal row, composed of film clips.', 4684, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4685, 'These were chosen from a huge range of films, documentaries, news footage, and chosen for a particular sound (pitch and quality of sound) as well as for the image.', 4685, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4686, 'Thus a singing Marilyn, marching feet, shouting, piano player, almost any thing is sampled and used.', 4686, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4687, 'Marclay built the resulting samples into a complex musical score, fifteen minutes long, which is &#x2018;played&#x2019; by the film clips.', 4687, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4688, 'The viewer is engaged in a compelling set of responses to what they hear and see, having to match sound to image and also to process responses to the image, many of which are consciously or subconsciously recognised.', 4688, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4689, 'The urge to find a narrative is continually denied, and the viewer is forced to recognise the sound as the narrative instead.', 4689, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4690, 'Maria Marshall', 4690, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4691, 'A British artist born around 1968 who has made a number of video films featuring her own children, including one of her son smoking.', 4691, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4692, 'Mike Marshall', 4692, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4693, 'A British artist born in 1970s, Marshall has made a number of films of banal everyday scenes, including a film of a water sprinkler in a garden.', 4693, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4694, 'The viewer watches the green leaves of the hedge and the waxing and waning of the spray droplets as they sparkle in the sun.', 4694, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4695, 'Marshall brings a kind of everyday sublime to the viewer&#x2019;s attention, producing moments of abstract beauty and contemplation from unexpected sources.', 4695, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4696, 'Jason Martin', 4696, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4697, 'British artist born in the 1960s who makes paintings by applying and thick layer of a single colour of oil paint and combing it with a specially designed tool the width of the canvas (up to three metres high) to add a wavy ridged pattern.', 4697, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4698, 'This catches the light giving rise to an optical effect.', 4698, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4699, 'Simon Martin', 4699, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4700, 'British artist born in 1968 whose highly finished conceptual painting and sculpture is concerned with the nature of art.', 4700, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4701, 'He has made a photo realist painting of a bright red tree frog, a painted fibreglass replica of a carved and painted wooden bird in relief, that is based on an original wood carving, and a lacquered fibreglass sculpture of a toy monkey&#x2019;s head, enlarged to about four feet in diameter and sprayed in off white gloss paint.', 4701, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4702, 'His work is laborious and labour intensive, the results of his labour producing luxurious objects that have no clear purpose, making the viewer think about them as art objects.', 4702, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4703, 'He has also made other conceptual work which is opposite in its choice of more ephemeral materials such as cardboard boxes.', 4703, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4704, 'Karl Maugham', 4704, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4705, 'Painter born 1960s who paints intensely detailed flowerbeds, every flower given individual attention, on large canvases.', 4705, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4706, 'Paul McCarthy', 4706, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4707, 'American artist who is well known for his performance work, which is always shown as a video documentation, usually displayed as part of an installation containing the props, set and costumes used in the production of the video.', 4707, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4708, 'The actual one off performance may be done in front of an audience, but they watch it on a monitor in another room, Macarthy always performing in private.', 4708, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4709, 'Macarthy appropriates folk tales and popular icons, subverting them by reacting the tales transplanted into his own bizarre and usually scatological world.', 4709, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4710, 'He draws a parallel between everyday activities and the making of art through his parody of fiction.', 4710, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4711, 'Macarthy himself usually features as main protagonist/artist.', 4711, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4712, 'He always uses theatrical costumes and sets, often using masks and props.', 4712, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4713, 'For example a work titled Heidi and the Grandfather is loosely based on the story of Heidi, but in McCarthy&#x2019;s hands becomes a tale of child abuse and perverse practices involving faecal obsession.', 4713, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4714, 'In part of the performance Heidi and the grandfather make sausages from fake faeces extracted from Heidi&#x2019;s prosthetic bottom.', 4714, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4715, 'Bossy Burger is a horror story involving a chef character that wears a mask and makes burgers.', 4715, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4716, 'The film makes reference to Sweeny Todd and a lot of tomato ketchup is used (a development from an earlier video in which Macarthy smears himself liberally from head to foot with tomato ketchup).', 4716, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4717, 'A film of a Pinocchio character is shown on a monitor in a large box construction with peepholes, which are apparently holes for Pinocchio&#x2019;s nose, and there are Pinocchio costumes complete with noses for the viewer to put on.', 4717, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4718, 'As ever, in this work Macarthy makes obvious and puerile associations with his chosen subject and lets the various elements collide to disconcerting but humorous effect.', 4718, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4719, 'He takes the Freudian claim that art is at base no more than playing with ones own excreta absolutely literally.', 4719, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4720, 'Macarthy notorious for his wittiest creation, De Kooning, also his cruellest and funniest parody of art and the art world, featuring McCarthy visiting a blue chip dealer and also dressed as a tube of paint throwing him self mindlessly against the studio walls, chanting a tuneless ditty &#x2018;De Kooning, De Kooning&#x2019;.', 4720, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4721, 'He mocks the art world&apos;s pretensions and contrasts them with the still feted work of the supposedly senile de Kooning.', 4721, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4722, 'This is perhaps the most extreme example of the way Macarthy focuses on breaking taboos.', 4722, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4723, 'In 2003 McCarthy made an installation for a London gallery which included President Bush of America and the Queen in the interior of a royal palace.', 4723, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4724, 'He also made a fifty metre high outdoor inflatable black vinyl sculpture of a figure with a Pinnochio nose.', 4724, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4725, 'MaCarthy&#x2019;s comic and clownish portrayal of senility, ketchup and fake faeces smeared over his body and surroundings to mimic blood and shit, scenes of child abuse and indecent or murderous practises: all these are grist to McCarthy&apos;s comic tragic mill, his interpretation of the darkest side of human nature as a form of slapstick.', 4725, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4726, 'Lucy McKenzie', 4726, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4727, 'Scottish artist born in the late 1970s, Mackenzie&#x2019;s practise is extensive, ranging from painting, drawing, printmaking and writing, to video, installation, dj ing, and event organising.', 4727, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4728, 'She has also used her work to promote the activities of charities, such as one that supports women in Eastern Europe who are trafficked as prostitutes.', 4728, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4729, 'Mackenzie&apos;s polymorphous practise is the result of an ideological and socially engaged approach to art as a medium with the power to transform daily life.', 4729, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4730, 'At the same time her work references early twentieth century art, particularly that of Russia and Germany both iconographic ally and in the creation of social events.', 4730, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4731, 'Her paintings and works on paper often borrow apparently anachronistic historical graphics style, and have featuring athletes, Olympic rings, and graphic and geometric patterns.', 4731, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4732, 'Or they may be graffiti like, borrowing from classical art and include text.', 4732, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4733, 'They are painted in faded out colours, drawn roughly or printed on, often on cheap paper which in itself is a symbolic act, as cheap paper and printing methods seem entirely anachronistic in western Europe today, where they are still the norm in many parts of the world.', 4733, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4734, 'In some sense Mackenzie&#x2019;s work reflects the state of the body politic, in other senses it is a reflection on the practise of art.', 4734, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4735, 'She started a club night in her native Glasgow that was and remains a focus for artists and musicians.', 4735, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4736, 'She also ran a club in Warsaw with Pauline Olowskowa, a long term collaborator, at which they presented events including music, poetry and readings.', 4736, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4737, 'A video made in 2003 shows Mackenzie and Olowskowa working together in an empty space.', 4737, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4738, 'Mackenzie is drawing Olowskowa who seems to be doing nothing but talking on the phone.', 4738, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4739, 'Mackenzie also uses text in her large paintings and painted wall sized murals.', 4739, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4740, 'A recent printed work features a year planner poster for 2004, blank, with all the weekends blocked out in yellow highlighter pen.', 4740, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4741, 'Steve McQueen', 4741, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4742, 'British artist born 1960s who works in film and Video.', 4742, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4743, 'McQueen&#x2019;s films have a wide range of subjects but share basically sculptural concerns.', 4743, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4744, 'Bear, made for his post graduate show in 1993, shows two men wrestling naked, shot from below in slight slow motion.', 4744, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4745, 'Another shows a tightrope walker shot from below, so that we focus on the soles of the feet in special shoes, wobbling on the wire.', 4745, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4746, 'In both these films by choosing an unusual viewpoint McQueen changes our perception of these spectator activities and shows the effort required to carry them out.', 4746, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4747, 'In 2001 a film shows McQueen standing before a wooden barn, which subsequently falls apart, the roof collapsing and the walls falling outwards.', 4747, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4748, 'As it falls, it seems that McQueen will be squashed by the front of the barn but in fact he is standing at the exact spot over which the window falls, leaving him standing with the window opening around him, unscathed.', 4748, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4749, 'In 2003 he made two more ambitious works The Deep, which he filmed in a mine in South Africa, and the Leap, which showed young boys jumping off a cliff.', 4749, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4750, 'The Deep takes us down to the coalface in the lift and films at eh coal face, using available light and ambient sound.', 4750, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4751, 'The result is often extremely and hard to see, with no illumination save the miners headlamps and creates the impression of a kind of hell.', 4751, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4752, 'The film culminates in a sequence shot in the miners&apos; shower and clocking out hall where each mans temperature is taken.', 4752, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4753, 'As well as seeking new ways to look at things and investigating the visual perceptions associated with sound, McQueen&#x2019;s work deals with race and the representation of race in art cinema and photography although he does not claim this for his work.', 4753, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4754, 'The Deep does this explicitly, but Bear and the Falling Barn are subtler.', 4754, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4755, 'The barn is based on part of a Charlie Chaplin film in which the same thing happens.', 4755, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4756, 'Jonathan Meese', 4756, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4757, 'German artist born around 1970 Meese made a number of works in which he covered the walls and ceiling of the exhibition space with a vast quantity of found material, photographs, drawings, images from magazines, in fact any visual material.', 4757, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4758, 'Discernable themes might emerge.', 4758, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4759, 'The effect was that of a teenage bedroom vastly expanded, with adult subject matter.', 4759, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4760, 'Sometimes the material might be sent by post to the gallery by the artist, and the gallery left to mount it on the wall as they wished.', 4760, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4761, 'Dawn Mellor', 4761, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4762, 'British artist born 1960s who paints women.', 4762, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4763, 'For a long time Mellor&#x2019;s paintings were very small and displayed in groups, subsequently she began to make bigger works.', 4763, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4764, 'Tania Merz', 4764, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4765, 'British painter born 1960s ! Alain Miller.', 4765, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4766, 'British artist born around 1960 who paints highly realistic images (for example a heart or a brain) which from a part of a larger abstract composition.', 4766, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4767, 'Lisa Milroy', 4767, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4768, 'British artist born around 1960 who makes figurative painting.', 4768, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4769, 'Milroy&#x2019;s work is essentially still life but there is an element of process painting in her work.', 4769, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4770, 'She often paints multiple versions of the same type of object, set out in rows that cover the whole picture plane, for example shoes or blue and white porcelain plates, with the effect of standardising everything she chooses to paint both in terms of the genre of thing, and in terms of the relation of one type to another.', 4770, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4771, 'So that car tyres might be treated in the same way as jewellery.', 4771, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4772, 'The objects in Milroy&#x2019;s paintings are painted in consistent way, with simple flowing brushstrokes on a flat colour ground, in realistic colours.', 4772, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4773, 'They look very real viewed from a distance, close to the canvas the paint and brushstrokes are what the eye focuses on.', 4773, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4774, 'Aleksandra Mir', 4774, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4775, 'Polish artist born in the 1960s who live in America.', 4775, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4776, 'Mir&#x2019;s work comprises socially engaged installation and events, combined with the construction of large site specific or temporary sculptures.', 4776, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4777, 'Mir often chooses to respond to a location or a situation.', 4777, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4778, 'For example she sited a military tank painted pink on a disused lot in London, where local children play.', 4778, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4779, 'The tank was photographed with women and girls dressed in pink draped over it in an ironic take on the female military mascot.', 4779, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4780, 'Mir has made a work based on the Mir space station, and most recently has made an almost life size inflatable jumbo jet which can be sited anywhere.', 4780, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4781, 'Tatsuo Miyajima', 4781, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4782, 'Japanese artist working from the late 1980s onwards who has made a large number of works using LED displays.', 4782, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4783, 'A series of works use small LED units placed on the floor or on the wall, showing a very high number, which is constantly changing.', 4783, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4784, 'This number is in fact the date and time displayed in fractions of a second.', 4784, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4785, 'Sarah Morris', 4785, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4786, 'American artist born in the 1960s who paints process based geometric pattern works based on the facades of modernist buildings.', 4786, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4787, 'Morris photographs these mostly glass and metal framed buildings whose main feature is windows, and reduces the resulting grid, distorted due to the perspective of the original photograph, to its basic elements in a computer programme.', 4787, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4788, 'The grid is painted in one colour, often white, and the &#x2018;windows&#x2019; in a number of colours, usually very bright, to create a grid pattern with a nod to Mondrian and to Bridget Riley, although it is more complex and colourful.', 4788, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4789, 'Morris uses high gloss paint very precisely applied.', 4789, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4790, 'The paintings (and similar screen print panel series) are about 3 m high and 4 m wide at their largest.', 4790, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4791, 'Morris also makes films showing the kind of architecture and city that inspires her work, for example a film shot in Miami.', 4791, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4792, 'Paul Morrison', 4792, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4793, 'British artist born in the early 1960s who began his career in the late 1990s painting trees, flowers and vegetation in silhouette.', 4793, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4794, 'Morison&#x2019;s paintings are nearly all made in black on white, showing meticulously drawn plants and trees of varying scale made into a composition, which are painted by hand absolutely flat and hard edged in black acrylic paint on white.', 4794, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4795, 'He has occasionally made negative versions in white on black.', 4795, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4796, 'Morison&#x2019;s paintings are usually around 2 metres high, and he has also made round ones.', 4796, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4797, 'His wall paintings often span 20 metres.', 4797, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4798, 'Anna Mossman', 4798, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4799, 'British artist born about 1960 who takes photographs in which she represents sensory experiences or thought processes.', 4799, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4800, 'In a photograph of a rose the rose is out of focus as if the viewer had leaned close enough to smell the roses perfume.', 4800, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4801, 'A series of photographs show people who are out of focus to the most extreme degree.', 4801, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4802, 'For these photographs Mossman asked her subjects to stay in a room alone with the camera, which was set to take a very long exposure.', 4802, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4803, 'The sitters were to tell the camera a secret.', 4803, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4804, 'The resulting image is blurred due the movement of the sitter during the telling of the secret, the blurring varying from person to person.', 4804, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4805, 'Ron Mueck', 4805, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4806, 'British sculptor born in the 1950s who after a career in film industry prosthetics began to make sculpture.', 4806, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4807, 'Dead Dad brought him to public attention, a life size model of apparently of his own dead father, made with such detail that it appeared to be real.', 4807, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4808, 'Mueck&#x2019;s work bears comparison with that of Duane Hanson in the 1960s but the difference is that Mueck experiments with scale and his figures are often naked.', 4808, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4809, 'Mueck makes his sculptures from fibreglass, which is painted, and human hair applied strand by strand.', 4809, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4810, 'He has also made a baby, a 6 meter high pregnant woman, a school girl (clothed), a post partum woman lying on her back with her child placed on her stomach, the umbilicus emerging from her vagina still attached to the baby and a man in a boat.', 4810, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4811, 'Mueck&#x2019;s sculptures are so realistic as to cease to provoke amazement after a while, since there is no doubt of their perfection.', 4811, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4812, 'Instead Mueck wants the viewer to confront the human state, which each work represents &#x2013; death, pregnancy, childbirth, and childhood &#x2013; by presenting something as close to life as possible.', 4812, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4813, 'Dave Muller', 4813, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4814, 'American artist who makes paintings in water colour on paper, some of which are quite large, for example a panoramic country scene made on several pieces of paper.', 4814, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4815, 'Muller stages three day weekend exhibitions in his own house and in galleries which he considers to be part of his practise.', 4815, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4816, 'In 2003 Muller made a series of paintings of the titles and the names of artists printed on the sleeve edges of the record collections of a number of people.', 4816, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4817, 'Vik Muniz', 4817, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4818, 'Brazilian artist who makes unconventional paintings.', 4818, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4819, 'Muniz&#x2019;s paintings are usually made from newspaper or other photographs which he collects obsessively, for example he made a series of works in which he used treacle to copy well known images such as Jackson Pollock making a painting, which try to be the most basic form of illusion in terms of making a recognisable image.', 4819, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4820, 'Juan Munoz', 4820, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4821, 'Spanish artist born in the 1950s who died in 2001.', 4821, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4822, 'Munoz, who was Spain&#x2019;s best known artist of the end of the twentieth century, made sculpture and installation.', 4822, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4823, 'One of Munoz&#x2019;s last works was a very large scale installation at Tate Modern in London.', 4823, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4824, 'Several &#x2018;elevators&#x2019; were constructed which ascend and descent through a false floor.', 4824, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4825, 'Viewers can see the elevators from the basement level and from above, and watch them ascending in space, in a way that they would never usually be seen.', 4825, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4826, 'The movement of the elevators echoes that of the pistons of a huge slow engine.', 4826, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4827, 'Muntean and Rosenblum', 4827, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4828, 'Artist partners working in the late 90s and early 2000s in London who make collaborative paintings depicting usually young people in social situations conversing.', 4828, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4829, 'Their speech is written on the painting.', 4829, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4830, 'Muntdean and Rosenblum&#x2019;s style is strongly graphic, with flat colours, and black outlines and white backgrounds are characteristic.', 4830, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4831, 'Takahashi Murikame', 4831, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4832, 'Takahashi is a Japanese painter who makes highly decorative intricate and stylised floral paintings made in a flat style which make reference to traditional Japanese painted or woven screens, but are also distinctively modern even futuristic.', 4832, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4833, 'Brightly coloured, meticulously painted and highly controlled, the paintings have a strongly graphic quality, which makes them difficult to contextualise.', 4833, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4834, 'Murikame is notably for being one of the most commercially successful artists at the turn of the twentieth century and has a large business empire.', 4834, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4835, 'Sadie Murdoch', 4835, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4836, 'British artist born in mid 1960s who began making large paintings in the early 1990s based on modernist architecture, specifically interiors, which she drew out on a white ground, usually in black and grey, partially painted using very thin paint, and then partially destroyed by pouring thin paint over the whole.', 4836, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4837, 'In the 2000s Murdoch began to make architectural models from card and paper, which she again partially destroyed.', 4837, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4838, 'Later models are more abstract and remain intact.', 4838, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4839, 'Murdoch&apos;s interest in the modernist project in art and architecture has led to explore both abstract expressionism and architecture particularly the work of Le Corbusier.', 4839, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4840, 'David Musgrave', 4840, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4841, 'British artist born in the 1960s who makes installations; Musgrave&apos;s work is essentially a sculptural representation of paint and the painted surface.', 4841, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4842, 'He cuts out various thicknesses of plastic and other sheet materials, transparent and opaque, to look as if they are poured pools of colour and places them on the floor, overlaying them.', 4842, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4843, 'The cut outs are complex shapes, as if liquid has been splashed or dropped, creating multicoloured floor pieces.', 4843, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4844, 'Musgrave has also made a number of wall reliefs which are enlarged brushstrokes, modelled and cast and painted in high gloss.', 4844, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4845, 'The mostly incidental shape and texture of the paint, the blob, the stroke is made into a very deliberate object.', 4845, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4846, 'Mike Nelson', 4846, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4847, 'British artist born in the 1960s who makes installations that are like mazes.', 4847, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4848, 'Nelson constructs a series of rooms and corridors within a gallery space, which the viewer enters through a door in the gallery.', 4848, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4849, 'Inside they are free to wander in the interior space that nelson has created but there is only one way out.', 4849, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4850, 'The first of these installations created a series of rooms that seemed to have been recently abandoned.', 4850, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4851, 'Some were like offices in a factory, others empty rooms, all had a feeling of recent presence but also of possible sinister events.', 4851, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4852, 'There are clues in the form of items pinned to the wall, furniture, but very few objects.', 4852, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4853, 'The environment seems timeless and the viewer has the disorientating experience of not being able to tell what period, country or type of building they are in.', 4853, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4854, 'the spaces are extremely real.', 4854, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4855, 'At a central point in the maze it seems that the viewer has reached the point at which they started but this is in fact a replica of that room and the determined participant carries on to discover several more rooms.', 4855, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4856, 'There are hints of the psychological pressures that are sometimes brought to bear on prisoners.', 4856, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4857, 'Another example is a maze Nelson created specifically a museum in London, in which the viewer enters what seems to be a series of back rooms at the museum, storage spaces for works of art and wrapping and packing areas.', 4857, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4858, 'It is very difficult to believe that this is an installation that has been constructed in the gallery and that the viewer has not entered behind the scenes by mistake, but for the peculiar absence of life and activity.', 4858, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4859, 'Shirin Neshat', 4859, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4860, 'Iranian artist who has made several large screen projected video installations featuring women wearing the veil and music.', 4860, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4861, 'Mariele Neudecker', 4861, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4862, 'Artists born in the 1960s who makes installations in which she creates model landscapes such as a sea, or a mountain range.', 4862, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4863, 'Jacques Nimski', 4863, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4864, 'British artist who makes intentsley detailed pencil drawings of plants that entirely fill the paper.', 4864, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4865, 'Noble and Webster', 4865, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4866, 'British artist partners born in the late 1960s who make sculpture and installation.', 4866, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4867, 'Noble and Webster&#x2019;s work is an unashamed unapologetic ode to money, creation, fame and ego combined with traditional forms, crafts and materials.', 4867, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4868, 'Their illuminated signs, which lean against the gallery wall or are mounted on it, are an example of this.', 4868, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4869, 'These may take the form of a dollar sign entirely made of white light bulbs, or of tattoo designs such as a heart stabbed by a dagger with a word on a ribbon, Las Vegas style.', 4869, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4870, 'Noble and Webster made an installation fro which they made life size models of themselves as apes, cast in fibreglass and walking on a pristine white undulating gallery floor.', 4870, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4871, 'Another consists of an enormous pile of rubbish, with a strong light projected at it, casting a shadow on the wall behind to reveal the profiles of the artists, created from careful arrangement of the rubbish but only visible as a shadow.', 4871, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4872, 'Paul Noble', 4872, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4873, 'British artist born in the 1960s who makes pencil drawings, video and animation.', 4873, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4874, 'Noble&#x2019;s earliest work consisted of book jackets made for existing books, which altered or repositioned the book in some way, usually through humour or puns, echoing the British playwright, Joe Orton&#x2019;s illicit alteration of library books.', 4874, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4875, 'The main body of Noble&#x2019;s work to date depicts his creation of a fictitious town called Nobson New Town.', 4875, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4876, 'The architecture of Nobson is constructed on the blueprints of a typographical font created by Noble whose capital letters are three dimensional blocks, enabling Nobson to draw arrangements of building that spell out words.', 4876, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4877, 'These blocks have the appearance of modernistic concrete structures and the letters are hard to read but decipherable.', 4877, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4878, 'The Nobson project is an indictment of the way of life in the west, a Swiftian satire describing an urban and rural dystopian with utopian elements.', 4878, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4879, 'The name Nobson is descriptive of the phallic forms of some of the buildings, and the phallic form is put to use everywhere from tree stumps to drawbridges.', 4879, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4880, 'There are no people in the drawings.', 4880, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4881, 'Noble&#x2019;s drawings have been made since 1997 and show every aspects of life in Nobson from the dwellings, the park, the cemetery, the factories, the sewage works, the school, the hospital, in fact every amenity and faculty a small town would have.', 4881, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4882, 'There is also a large house for the artist, which has a number of rooms and a tower.', 4882, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4883, 'The drawings are made in pencil and are about 3 metres high, extremely detailed and finely drawn so that the whole drawing can take a long while to peruse.', 4883, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4884, 'Any words spelled out by the buildings are readable from a distance only.', 4884, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4885, 'Noble also makes small drawings showing details from Nobson.', 4885, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4886, 'The words in the drawings usually spell out a political or ideological statement or quotation that deals in some way with the life of ordinary working people.', 4886, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4887, 'Noble has also represented Nobson as a photomural, for which he made a tent in the shape of a letter from the Nobson typeface and pitched in a forest.', 4887, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4888, 'Woodland animals are added to the photograph digitally as if this were a rural idyll.', 4888, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4889, 'He has made a digitally animated drawing too, which shows the factories of Nobson in a static single shot view, with very little happening save for smoke plumes emitting from chimneys and a train travelling across periodically.', 4889, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4890, 'Nils Norman', 4890, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4891, 'British artist, who makes installations, works on paper, models and written texts.', 4891, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4892, 'Norman&#x2019;s work presents ecological and sustainable models for human existence, in particular urban existence.', 4892, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4893, 'Norman draws on 1960s and 70s models for resistance, tailoring them to the new century and a new era of globalisation and anti capitalism.', 4893, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4894, 'In particular he focuses on the modernist myth of creating quality of life for every one through good practise in design and the built environment.', 4894, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4895, 'His investigations of how to put simple ideas for more socially responsible living into practise take various forms.', 4895, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4896, 'He has made a number of architectural models that demonstrate for example acts of urban resistance or reclamation such as the conversion of the flat roof of an apartment building in New York into a vegetable plot to enable the residents to be self sufficient.', 4896, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4897, 'He has also designed and built a sustainable bus called Geocruiser (2001).', 4897, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4898, 'The bus runs on converted waste fat from the catering industry and has solar panels enabling it to actually return energy to the national grid.', 4898, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4899, 'It collects rainwater and part of it is a green house with a composter enabling the bus to be used to grow food efficiently.', 4899, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4900, 'The bus also houses a library of books and texts on ecology and self sufficiency and a computer terminal with internet access, a painter and a photocopier available for public use wherever the bus stops.', 4900, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4901, 'Visitors can photocopy any texts they wish to take away.', 4901, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4902, 'Geocruiser visited several cities in the UK and in Europe.', 4902, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4903, 'Tina O&#x2019;Connell', 4903, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4904, 'Irish artist born in the early 1960s who makes large scale architectural installations often using concrete, and usually site specific.', 4904, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4905, 'Chris Ofili', 4905, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4906, 'British artist born in the late 1960s who became known and initially notorious for his pattern paintings and paintings of black women and men with elephant dung attached in the mid 1990s.', 4906, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4907, 'Ofili&apos;s figurative paintings are complex in their execution.', 4907, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4908, 'A psychedelic pattern is painted first, then a figure added, picked out and filled in exclusively with concentric lines of tiny dots of paint in many colours which follow the contours of the figure.', 4908, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4909, 'His earlier works have cut outs from pornographic magazines collaged on to the surface.', 4909, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4910, 'The whole painting is then covered with a layer of poured plastic resin, adding a physical depth to the surface.', 4910, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4911, 'Elephant dung soaked in resin is attached tot eh canvas, sometimes with words and names picked out in coloured map pins on them.', 4911, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4912, 'The paintings rest against the wall on two lumps of dung.', 4912, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4913, 'Ofili mostly made paintings of women in this series which he described as goddesses, highly stylised head and shoulders portraits of woman wearing jewellery, including a black Madonna which created a furore amongst the American Christian right for it juxtaposition of the virgin Mary with elephant dung.', 4913, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4914, 'He also made a number of full length portraits of male characters including one called Captain Shit, a black superhero.', 4914, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4915, 'Ofili continued to paint women and to make a large number of watercolours on paper, drawings and prints, until the early 00s.', 4915, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4916, 'He then made a series of paintings depicting a man and a woman, as lovers, but also as iconographic symbols of Africa and its people.', 4916, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4917, 'Ofili&apos;s continued to use the dung to represent his connection with his mother country (he had begun to use it after his first trip to see where his family had come from).', 4917, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4918, 'The lovers paintings are made in the same way, but there are fewer collaged elements.', 4918, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4919, 'Flowers and leaves are added to the backgrounds and the paintings are more reflective.', 4919, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4920, 'In 2002 he made a series of 13 works featuring a monkey, painted in the same way.', 4920, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4921, 'These are installed in an especially constructed timber lined room resembling a darkened chapel.', 4921, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4922, 'Illuminated so that they have an icon like quality each paintings is based on a different colour and titled Mono Azul, Mono Or for example, meaning Blue Monkey Gold Monkey.', 4922, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4923, 'The twelve monkeys, six on each side of the room, depict the apostles, and the gold monkey at the end of the room is Christ.', 4923, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4924, 'This work is typically both irreverent and reverent.', 4924, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4925, 'All of Ofili&#x2019;s work is characterised by a sense of the profound combined with a highly decorative surface and a dry humour.', 4925, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4926, 'He plunders popular culture and mixes influence in the same way that hip hop music does.', 4926, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4927, 'Hip hop is often cited as an importance influence on Ofili&#x2019;s work.', 4927, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4928, 'Saskia Olde Wolbers', 4928, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4929, 'Dutch artist born in around 1970 who makes videos based on models that she constructs in her studio which have a spoken narrative voiceover.', 4929, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4930, 'Olde Wolbers takes a true story, often from a newspaper; a tale of someone&#x2019;s life or something that happened to someone, and elaborates it, writing a first person narrative which Olde Wolbers chooses a person or an actor to read it.', 4930, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4931, 'She imagines a scene in which this tale might unfold and constructs a three dimensional model, which she then films.', 4931, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4932, 'The models are made from a variety of materials &#x2013; one model of an underground car park also resembles the frosted interior of a fridge but in fact is made from textured plastic sheeting and plastic bottles and cups.', 4932, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4933, 'Another of a hospital ward is made from a pet cage dipped in household gloss paint and submerged in a tank, filmed underwater.', 4933, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4934, 'The paint drips but stays in place, creating an eerie white scene.', 4934, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4935, 'Olde Wolbers films have an eerie often futuristic quality, which is at odds, both with the prosaic materials of their construction and with the true story narrative of the voiceover.', 4935, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4936, 'The narrative becomes extraordinary both in the writing and in the reading, Watching, the viewer has to grapple with interpreting what they see, which seems very real yet palpably is not and relating it to what they hear.', 4936, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4937, 'Pauline Olowskowa', 4937, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4938, 'Polish artist who makes drawings and collages, sometimes working collaboratively with Lucy Mackenzie.', 4938, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4939, 'Hans Op de Bek', 4939, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4940, 'Belgian artist who makes photographs.', 4940, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4941, 'Julian Opie', 4941, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4942, 'British artist born around 1960 who makes works in a range of media.', 4942, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4943, 'Pie&#x2019;s early work consisted of painted cut outs made in folded and bent sheet metal.', 4943, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4944, 'They stand on the floor and represent objects such as a pile books, telephones, even a painting.', 4944, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4945, 'The objects are painted in a cartoon style with black outlines.', 4945, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4946, 'They are Opie&#x2019;s way of making painting into sculpture.', 4946, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4947, 'This work demonstrated an interest in generic representation, which has sustained throughout his career.', 4947, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4948, 'In the late 1980s and early 1990s Opie made a large number of sculptures fabricated from industrial materials.', 4948, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4949, 'These fall into two groups &#x2013; case, chest or freezer like constructions and glass screen constructions.', 4949, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4950, 'The case or chest works are made from sheet metal with aluminium fittings &#x2013; for example edging, feet and ventilation grilles.', 4950, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4951, 'They are ambiguous since they are evidently non functional, with no discernible means of opening them, yet they refer visually only to functionality.', 4951, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4952, 'In them Opie refers both to modernist design and to minimal sculpture in particular referring to the work of Donald Judd.', 4952, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4953, 'The glass screen works are arrangements of toughened glass in aluminium frames to resemble doors and glass walls that might be seen at an airport or other public space.', 4953, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4954, 'The glass often has discs etched on it in a row at eye level.', 4954, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4955, 'These arrangements engage the viewer in a familiar experience of the negotiation of glass barriers, whilst considering the formal arrangement as a sculpture.', 4955, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4956, 'Opie made a number of works taken from the symbols and pictograms used in signage, developing an idea of the point at which the individual becomes generic and vice versa.', 4956, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4957, 'Opie has made many paintings and prints, usually screen prints.', 4957, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4958, 'The road paintings, Imagine You Are Driving, (around sixty cm high) were made after he drove across America, and show roads reduced to the minimum of detail &#x2013; a black road, with white lines and green verges with blue sky, each rendered in absolutely flat acrylic paint with hard edges.', 4958, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4959, 'These paintings conflate the experience of driving with the experience of the computer game and make the case for the roadscape being the contemporary landscape painting.', 4959, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4960, 'A series of night paintings are made in black with blurry circles of yellow, white and red light indicating road lamps and car headlights and rear lights.', 4960, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4961, 'Opie&#x2019;s Computer game paintings (similar sized and also two metre high versions made) are a development of the road paintings, representing the same experience of driving but this time through a version of a computer generated urban environment smoothed out so that there is no detail at all.', 4961, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4962, 'Opie took this approach into three dimensions with his model village sculptures, immaculately made and spray painted buildings with almost no detailing so that they become generic In the late 1990s continuing to work the idea of the generic Opie made a series of digital drawings of people he knew, removing all the detail from a head and shoulders photograph to produce a generic image in black on a brightly coloured background that actually retained a great deal of individuality.', 4962, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4963, 'These images were used on an album cover and became known to a much wider public.', 4963, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4964, 'He also began to make digital animations, taking the same principle and applying it to the moving image.', 4964, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4965, 'He filmed a person moving and reduced this image to the bare minimum, resulting in a moving pictogram, which still retained some of the characteristics of the individual on which it was based.', 4965, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4966, 'Gabriel Orozco', 4966, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4967, 'Brazilian sculptor who made a work called Ping Pond Table, consisting of two ping pong tables cut in half where the net would be and arranged in a cross shape with a fishpond in the vacant square area in the middle.', 4967, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4968, 'Four players can play simultaneously, the pond replacing the net as the barrier to be crossed by the ball.', 4968, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4969, 'Pepon Osorio', 4969, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4970, 'South American artist born in the 1960s died in the 1990s.', 4970, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4971, 'Osorio made a work in which he cycled around a platform built at the top of a very large tree encircling the trunk.', 4971, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4972, 'Silke Otto Knapp', 4972, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4973, 'German artist working in Britain born in the late 1960s who makes paintings using watercolour on canvas.', 4973, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4974, 'Otto Knap&#x2019;s earliest work in the 1990s was a series of female portraits taken from fashion magazines followed by a series of American landscapes sometimes in panoramic format often taken from Marlboro advertisements and form her own photographs.', 4974, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4975, 'These became more impressionistic until she began to paint in watercolour on a white ground, making a number of groups of landscapes between 40 and 80 cm high.', 4975, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4976, 'The watery paint is applied in a gestural manner pooling on the surface creating an often illusory image.', 4976, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4977, 'A Los Angeles series shows the city by day and by night, as does a group of Las Vegas paintings.', 4977, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4978, 'Otto Knap then made a number of &#x2018;vegetation&#x2019; paintings depicting the greenness of parks, gardens and glasshouses such as Kew with enough detail hinted at for the viewer to interpret the image as a landscape, as well as some yellow desert paintings.', 4978, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4979, 'More recently Otto Knap has made a number of paintings of show girls, again in watercolour, the colours predominantly red.', 4979, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4980, 'Laura Owens', 4980, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4981, 'American painter born in the 1970s who makes large semi abstract works using bare canvas as a ground to which she adds blobs of colour and small painted areas.', 4981, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4982, 'Owens paintings often include flowers and patterns and hint at landscape and nature.', 4982, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4983, 'Jorge Pardo', 4983, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4984, 'Artist whose designs interiors, furniture and lighting with a distinct reference to modernist design for specific sites.', 4984, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4985, 'Pardo became known in the 1990s for his displays of lamps and lampshades.', 4985, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4986, 'In 1999 Pardo gained a commission for a major site specific work enabling him to build a house for himself in California, which he has declared an artwork and opened to the public.', 4986, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4987, 'The house is a minimal modernist open plan building, filled with furniture and objects designed to Pardo&#x2019;s specification.', 4987, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4988, 'Philippe Parreno', 4988, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4989, 'Artist who commissioned the conception and design of and bought the rights to a Japanese Manga cartoon character named Annlee.', 4989, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4990, 'Parreno then lent Annlee to a number of other artists (including Liam Gillick and Angela Bulloch) inviting them to make work with her.', 4990, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4991, 'Some artists used her in their own digital animations.', 4991, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4992, 'Janette Parris', 4992, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4993, 'British artist born in the 1960s who makes drawings, digital animations, writes produces and directs musicals and sings in a band.', 4993, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4994, 'Her performing activities are part of her practise as an artist.', 4994, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4995, 'Parris made a series of semi autobiographical cartoons featuring a character called Plank, and also a number of video installations featuring a rag doll called Janette.', 4995, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4996, 'Richard Patterson', 4996, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4997, 'British painter born 1965, painted hyper realist figurative works, notably a very large landscape format landscape with a massively enlarged plastic toy minotaur figure perched on a motorbike handlebar, the whole painting given a slight blur by the softening of the paint but parts in sharp focus.', 4997, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4998, 'The effect is one of double take.', 4998, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (4999, 'Toby Patterson', 4999, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5000, 'Scottish artist who makes plan and design based work, and has designed skateboards.', 5000, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5001, 'Patterson is also a curator.', 5001, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5002, 'Daniel Perfect', 5002, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5003, 'British artist who makes small decorative paintings and works on paper, landscape like patterns that are reminiscent of the 1950s.', 5003, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5004, 'Simon Perriton', 5004, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5005, 'British artist born 1962 who makes paper cut outs on a large scale.', 5005, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5006, 'These are often but not always like doilies made by repeated folding and cutting, and although at first glance they appear as lacy patterns, they are in fact thematic, for example a mushroom cloud in circular symmetry with CND symbol, barbed wire, mixed in with floral patterning to create complex intricate and skilled interwoven patters of great delicacy and fragility.', 5006, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5007, 'The cut outs may be single or multicoloured and are made by sticking paper together to the required size and then cutting out the design with a scalpel.', 5007, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5008, 'Perriton sometimes layers versions or the same cut out one colour on top of another.', 5008, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5009, 'The cut outs are always displayed unframed and unmounted and hang from pins in the wall.', 5009, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5010, 'Grayson Perry', 5010, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5011, 'British artist born around 1960 who makes coiled ceramic pots and vases richly decorated with drawn images, collaged photographic and printed elements, huge variety of glazes and gold and silver leaf.', 5011, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5012, 'The pots seem like precious decorative objects but on closer inspection are revealed to bear highly politicised messages and images about issues that concern the artist for example child abuse, torture and a variety of social ills.', 5012, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5013, 'This juxtaposition of luxury objet d&#x2019;art with hard hitting message makes the vases transcend their genre.', 5013, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5014, 'The text and images on the vases describe the grimmest of childhoods and allude openly to incest, paedophilia and child abuse.', 5014, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5015, 'As an artist, Perry often appears in public as a transvestite called Claire who has a variety of dresses, including a Victorian costume and a dress embroidered with machine guns.', 5015, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5016, 'She often carries a porcelain doll, Clara, dressed in a matching costume.', 5016, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5017, 'Perry has also made photographic works of herself as Claire, and embroideries.', 5017, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5018, 'Raymond Pettibon', 5018, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5019, 'American artist who makes pen and ink drawings.', 5019, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5020, 'Pettibon&apos;s main inspirations are William Blake, surfing, film and cartoons.', 5020, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5021, 'His drawings often use the cartoon format of a black outlined box, with text at the bottom hand written in capitals, as well as thought bubbles.', 5021, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5022, 'There is rarely a drawing without text.', 5022, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5023, 'The transient medium and sometime jokey style he uses and the subject he chooses to explore belies the seriousness of Pettibon&#x2019;s intent.', 5023, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5024, 'He often alludes to the larger issues of life, death and the sublime.', 5024, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5025, 'Surfing is Pettibon&#x2019;s passion and the surfer in his work symbolise the insignificance of human kind in the face of nature.', 5025, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5026, 'The surfer might for example be shown at to top of a huge wave, and have a thought bubble with an existential thought written in it.', 5026, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5027, 'Another drawing might feature a gun, or a light bulb with a caption.', 5027, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5028, 'Some of the captions read like lines from a forties film noir.', 5028, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5029, 'Pettibon&#x2019;s drawings are either around 25 or 60 cm high, made on white paper, usually exhibited pinned to the wall unframed.', 5029, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5030, 'Elizabeth Peyton', 5030, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5031, 'Artist born in the 1960s who paints portraits of her friends and of famous people.', 5031, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5032, 'These are often pop stars, and have included the British royal family.', 5032, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5033, 'Peyton&#x2019;s work in the 1990s often captured the zeitgeist, yet her work also refers to the history of portraiture.', 5033, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5034, 'The paintings are all done from photographs.', 5034, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5035, 'Peyton always paints on board, quite small (around 50 cm high maximum) in portrait format, using translucent colour rapidly and simply applied.', 5035, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5036, 'The white paint used for the ground and the coloured paint often drips over the edge of the board.', 5036, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5037, 'Daniel Pflum', 5037, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5038, 'German artist who makes sculptures that appear to be corporate logos and signs.', 5038, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5039, 'Vong Phaophanit', 5039, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5040, 'Vietnamese artist who made an installation for which he covered the floor of a gallery with rice which concealed a red fluorescent tube running the length of the gallery which sent red glow through the rice.', 5040, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5041, 'Sarah Pickstone', 5041, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5042, 'British painter born in the early 1960s.', 5042, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5043, 'Jack Pierson', 5043, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5044, 'American artist who makes photographs, paintings, sculptures and installation.', 5044, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5045, 'Pierson&#x2019;s work is diverse &#x2013; his photographs are of everyday scenes given a fairy tale twist.', 5045, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5046, 'His paintings are really photographs printed on to the canvas using a three colour printing process that transfers pigment in discrete dots of colour.', 5046, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5047, 'His installations are various, examples are a section of wall and floor painted yellow with a cabinet with a record player on it, some LPS which the viewer is invited to play and a chair, and a section of the wall and floor painted purple with a made up single bed placed on the floor well away from the wall on which the viewer is invited to lie.', 5047, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5048, 'Pierson&#x2019;s sculpture in the main consists of phrases, sayings, and truisms spelled out with found signage lettering on the wall.', 5048, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5049, 'The lettering is all in different styles materials and sizes, some old, some new, some Perspex, some moulded plastic, and some painted or gilded wood, some cast or cut metal.', 5049, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5050, 'Hadrian Piggot', 5050, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5051, 'British artist best known for a body of work he made in the 1990s.', 5051, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5052, 'Piggot crafted porcelain sculptures that took the form of bathroom sinks, for example, their forms changed to smooth rounded abstract shapes, convex where they should be concave, entirely without function yet with the addition of chrome taps and other fittings they became surreal objects.', 5052, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5053, 'A plughole might be placed on a bulging shape where no water could ever collect.', 5053, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5054, 'Piggot had leather cases made with satin lined moulded inserts to hold the sculptures, adding to their surrealism but inferring a useful portability.', 5054, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5055, 'He also made some carvings from bars of soap.', 5055, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5056, 'Piggot late began to make photographs of landscape.', 5056, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5057, 'Keith Piper', 5057, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5058, 'British artist.', 5058, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5059, 'Michelangelo Pistoletto', 5059, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5060, 'Italian sculptor working from the 1980s onwards who makes installations usually featuring mirrors made of steel.', 5060, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5061, 'The mirrors are deployed as a literal way of making the viewer part of his work.', 5061, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5062, 'Sometimes the mirrors have something printed on them.', 5062, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5063, 'He also made an installation consisting of a mountainous pile of second hand clothes which viewers were invited to help themselves to.', 5063, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5064, 'Lari Pittman', 5064, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5065, 'American painter who became extremely popular in the 1990s for his intensely intricate and complex abstract paintings.', 5065, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5066, 'Pittman draws on a multiplicity of sources, borrowing with impunity and putting together intense compositions that owe something variously to fabric design, the 1950s, architectural drawing, pop art, cartoons, and post modern painting.', 5066, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5067, 'It is impossible to locate the source of the elements of a Pittman painting because there are just so many elements and they are so perfectly graphically intertwined.', 5067, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5068, 'But what makes Pittman&#x2019;s work particularly distinctive is the method he uses to make them.', 5068, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5069, 'The main design is outlined and painted in flat colour.', 5069, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5070, 'This in itself produces a complex very brightly coloured painting.', 5070, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5071, 'Then dots of paint, squeezed onto the canvas (the dots no more than 2 mm across) are used to outline some areas, fill in others.', 5071, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5072, 'The dots are three dimensional and it becomes hard to believe that the painting could have been made by hand, although it clearly has.', 5072, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5073, 'Pittman&#x2019;s paintings function as a bold design with an overall structure as well as a surface of patterns within patterns that seems to have more in common with embroidery than painting.', 5073, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5074, 'Sigmar Polke', 5074, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5075, 'A German artist who began working in the 1960s.', 5075, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5076, 'Polke is famous for painting on tea towels (also on bed sheets, table cloths and curtains) In fact he tends to eschew canvas as ground altogether, sometimes working on resin panels as well as a huge variety of woven and printed textiles.', 5076, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5077, 'Much of his work has photographic screen printing as well as hand painting.', 5077, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5078, 'The screen print is usually a fragment of a vastly enlarged image from a newspaper, the dots that make up the image as big as a coin, printed in black.', 5078, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5079, 'Polke&#x2019;s hand painted is usually black outlines of figures and objects.', 5079, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5080, 'Polke&#x2019;s paintings depict such subjects as war, classical myth, weaponry, and rural idyll and are notoriously resistant to interpretation.', 5080, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5081, 'Many of the images are taken from newspapers as if to address the proliferation of imagery and the difficulty of assimilating it.', 5081, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5082, 'The fabric and pattern of the background is carefully chosen.', 5082, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5083, 'Sometimes two or more contrasting panels are stitched together.', 5083, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5084, 'Polke is a painter who is concerned with surface and image, what is real and not real, how an image is read, in what order and how narrative reading can be imposed and obstructed.', 5084, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5085, 'In the late 90s and early 00s, Polke pursued his interest in enlarging printed images by making use of digital images and large format printing to produce 20m wide enlarged newspaper images, printed on vinyl coated fabric.', 5085, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5086, 'Rona Pondick', 5086, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5087, 'British artist who makes sculpture by reupholstering and altering furniture.', 5087, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5088, 'A chair might have legs like an animal for example.', 5088, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5089, 'A sofa might have its shape altered to allude to the female form.', 5089, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5090, 'Pondick&#x2019;s work is influenced by surrealism in the way she transforms an everyday object.', 5090, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5091, 'Larry Poons', 5091, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5092, 'American artist working from the 1980s onwards, Poons&#x2019; meticulous cartoon like paintings usually depict landscape with text on panels within the composition.', 5092, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5093, 'For example a gravestone or the pages of an open book might carry the text, which is painted as if it were a printed typeface.', 5093, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5094, 'Poons paints in a precise way using flat shiny colours and hard edges.', 5094, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5095, 'Kathy Prendergast', 5095, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5096, 'British artist who has made a series of abstracted map or plan drawings of cities.', 5096, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5097, 'These are extremely detailed pencil drawings about sixty cm high, showing the basic street plan and zones of a city, but without using any conventional cartographic.', 5097, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5098, 'They have the appearance of cobwebs, or organic forms.', 5098, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5099, 'Monique Prieto', 5099, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5100, 'American artist who paints large flat coloured abstracts which look at first as if they are accidental &#x2018;pours&#x2019; of colour but which in fact are drawn on a computer first.', 5100, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5101, 'Prieto says that she evolved this method of working after the birth of her children to speed up the production process, enable her to do some preparatory work at home and make the most of her time.', 5101, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5102, 'The paintings are cool, calm and reflective.', 5102, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5103, 'Lisa Prior', 5103, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5104, 'American artist who makes video works featuring her alter ego who is an expert in any chosen field.', 5104, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5105, 'Prior&#x2019;s films borrow the style of corporate or promotional video, and she appears as a psychiatrist fro example, telling the viewer about a certain psychiatric condition.', 5105, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5106, 'Or about the mental health of Vietnam veterans.', 5106, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5107, 'Or about her own dating experiences.', 5107, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5108, 'Prior&#x2019;s persona is compelling but ultimately fallible and not without humour.', 5108, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5109, 'More recently Prior has made a work which has more formal concerns.', 5109, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5110, 'She filmed a dog shaking itself, then looped this short section and slowed it down.', 5110, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5111, 'The sound of the bell on the dogs collar is transformed and the dogs shaking appears graceful and deliberate.', 5111, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5112, 'James Pyman', 5112, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5113, 'British artist born in the 1960s who makes pencil drawings on paper.', 5113, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5114, 'Pitman&#x2019;s drawings are often large, up to one and a half meters high, and depict a variety of subjects ranging from groups of people to landscapes or even just a view of waves on water.', 5114, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5115, 'They are drawn in a soft but precise way, the pencil smudged to create soft shaded areas.', 5115, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5116, 'Mark Quinn', 5116, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5117, 'British artist born in the 1960s who makes sculpture.', 5117, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5118, 'Quinn&#x2019;s best known work is Blood Head, a cast of his own head made from several pints of his frozen blood.', 5118, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5119, 'This is displayed in a refrigerated vitrine on a plinth.', 5119, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5120, 'Quinn&#x2019;s work is mostly concerned with the human body, life and death.', 5120, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5121, 'A companion work to Blood Head is Bread Head, a bust modelled from bread dough and baked.', 5121, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5122, 'Quinn pursued his interest in preservation through freezing in other works.', 5122, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5123, 'He used a species of frog, which hibernates, at sub zero temperatures in suspended animation, displaying the frog in a block of ice in a refrigerated vitrine.', 5123, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5124, 'He also made a larger work using a mass of frozen flowers.', 5124, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5125, 'Quinn also cast his own body and used it to produce a thin latex skin, which he hung form a hook in the ceiling, as if it were his own flayed skin.', 5125, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5126, 'More recently Quinn has been pursuing his work with flowers and making photographs.', 5126, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5127, 'Fiona Rae', 5127, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5128, 'British artist born around 1960 who makes abstract paintings and works on paper.', 5128, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5129, 'Rae uses the brush stroke and the mark as her subject, and in her paintings from the late 1980s to the 00s she has consistently explored the possibilities of the gesture as a formal element of composition.', 5129, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5130, 'Rae uses a huge range of colours and type of mark, from rough wide brushstrokes to thin solid lines.', 5130, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5131, 'These do not follow any figurative logic but are discrete elements that make up the whole.', 5131, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5132, 'The paintings are coloured grounds with decorative marks arranged densely over them, the marks refer Rae&#x2019;s work invokes post modern ideas of mimesis and quotation, since she is not just making a mark but reproducing generic mark making, as well as borrowing from the history of painting for her sources.', 5132, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5133, 'The paintings are usually about 2 metres high.', 5133, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5134, 'In the 2000s, Rae has introduced photo collage of found images and uses digital technology to reproduce and rescale painted areas that interest her.', 5134, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5135, 'Michael Raedecker', 5135, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5136, 'Dutch artist born in 1961 who makes figurative paintings that incorporate thread.', 5136, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5137, 'Raedecker, a former fashion student, uses thread as a drawing medium, to describe outlines, textures, surfaces and light.', 5137, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5138, 'He first paints the background, very often using thick and even pooled paint, and then hangs the canvas so that he can sew through it.', 5138, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5139, 'Sometimes the thread is pushed through wet paint, or paint applied over it so that it becomes impregnated.', 5139, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5140, 'In the late 1990s Raedecker&#x2019;s first series of thread paintings featured the interiors of hotel rooms in grey, ochre, pale pink and beige.', 5140, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5141, 'A lampshade might be filled in with satin stitch, a bedcover with a textured thread, and a rug with tufts of wool.', 5141, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5142, 'There is also a painting of an empty cinema auditorium.', 5142, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5143, 'However thread is used more unconventionally to represent light and shade.', 5143, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5144, 'Another group of works made at the same time show odd figures, often wielding guitars, their hair done in thread.', 5144, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5145, 'These figures seem as if they might be the inhabitants fop the hotel rooms.', 5145, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5146, 'They also refer obliquely to the rock group Kiss, who wear costumes and face paint.', 5146, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5147, 'The rooms are small paintings but the following group of work depicting modernist suburban houses are about 2 metres high.', 5147, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5148, 'In these, a picture window at night might be filled in with lengths of thread across its width to simulate reflective light.', 5148, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5149, 'Small knotted threads indicate shrubs and trees.', 5149, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5150, 'Like the earlier works these are based on found photographs.', 5150, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5151, 'Raedecker&#x2019;s use of thread to depict plants, shrubs and trees led him to make a group of landscape paintings, often very large.', 5151, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5152, 'These include a number of scenes of barren desert as if from a western, with stunted trees and parched earth.', 5152, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5153, 'The thread detail is used to describe plants and also shadows.', 5153, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5154, 'At this time Raedecker also made a number of more abstract works based on the shapes of male and female genitals, thread representing pubic hair, as well as a series of portraits of old men.', 5154, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5155, 'The occasional appearance of a bird in the landscapes is transferred into a number of still lives made in the early 00s.', 5155, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5156, 'These use thread more literally.', 5156, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5157, 'Areas of stitching and tufting vie for attention with increasing use of very thick paint, applied horizontally and left to dry.', 5157, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5158, 'These often include a duck or a swan like bird.', 5158, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5159, 'Neo Rauch', 5159, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5160, 'German artist who makes paintings that have both figurative and abstract elements.', 5160, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5161, 'The figures and buildings in Rauch&#x2019;s are painted in a socialist realist style, but the are part of a larger, geometric abstract composition of coloured lines and shapes.', 5161, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5162, 'The paintings are up to three metres high.', 5162, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5163, 'Tobias Rehberger', 5163, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5164, 'German artist who makes site specific sculptures and models for these which are based on garden design and horticulture.', 5164, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5165, 'Rehberger might for example make a modular planting unit in which he plants the crops grown in the area, for example maize, artichokes and sunflowers, and place this in a university concourse.', 5165, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5166, 'Or he may reconstruct municipal flowerbeds and through the planting and shape of the beds echo a municipal building.', 5166, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5167, 'Steve Reinke', 5167, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5168, 'Canadian artist who make video work.', 5168, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5169, 'Reinke&#x2019;s work 100 Short Videos, made in the mid 1990s, is just that &#x2013; 100 short films made or found by Reinke, which include film of himself as a child, film of a group of children making a news broadcast at the Canadian Broadcasting Corporation and film of gay men meeting for sex in a forest.', 5169, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5170, 'Nick Relph and Oliver Payne', 5170, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5171, 'British artists born in the late 1970s who make videos about urban culture, for example one about public toilets in London which combines music with a written narrative and poetry edited with images from footage they shot in public conveniences.', 5171, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5172, 'Jason Rhoades', 5172, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5173, 'American artist.', 5173, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5174, 'Carol Rhodes', 5174, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5175, 'British artist who makes small paintings of aerial landscapes, usually fairly ordinary areas such as airport terminals.', 5175, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5176, 'Pipilotti Rist', 5176, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5177, 'Swiss artist who makes video installations.', 5177, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5178, 'Rist, who used to be a musician, collages together still images, video footage and music, which she composes herself to make dream like sequences.', 5178, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5179, 'She uses digital effects to create saturated colour, colour changes, dissolves, blurring, mirroring, and other optical effects.', 5179, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5180, 'Rist&#x2019;s videos sometimes feature herself.', 5180, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5181, 'The films are non narrative and are looped.', 5181, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5182, 'Rist employs a variety of means of presentation; double projections that meet in a corner for example.', 5182, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5183, 'In one exhibition she provided a 2 metre high 4 metre long sofa for viewer to clamber on to and watch a video wearing headphones.', 5183, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5184, 'Matthew Ritchie', 5184, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5185, 'American artist who makes work based on charts, graphs and plans.', 5185, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5186, 'Ritchie makes large scale drawings, up to 5 metres long.', 5186, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5187, 'An example of which is his diagram using circles around the names of individuals, corporations and institutions which are connected by arrows, showing the extent to which the US government and the family President Bush is linked to the oil business !Ugo Rondinone.', 5187, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5188, 'Italian artist who makes circular target paintings with concentric circles in blurred colours that create an optical shimmer.', 5188, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5189, 'Eva Rothschild', 5189, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5190, 'British artist born in the 1970s who makes sculpture and wall based work.', 5190, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5191, 'Rothschild has made a large number of works by weaving together two contrasting wall posters, cutting them in to strips and reassembling them, turning two images into an abstracted third.', 5191, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5192, 'She often leaves part of the image as unwoven strips which hang down the wall.', 5192, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5193, 'Rothschild&#x2019;s sculptures are minimal abstract objects which have the quality of small monuments.', 5193, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5194, 'She made a work by placing hundreds of burning incense sticks into a rubber car tyre, juxtaposing the spiritual contemplation associated with the incense sticks with a reference to the burning necklace (a car tyre filled with petrol) placed round the necks of persecuted Buddhist monks in the far east.', 5194, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5195, 'Thomas Ruff', 5195, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5196, 'German artist born in the 1960s who makes photographic portraits.', 5196, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5197, 'These are head and shoulders images printed much larger than life size, the subject looking directly at the camera, expressionless.', 5197, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5198, 'Every detail of skin and hair is in sharp focus.', 5198, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5199, 'Karin Ruggaber', 5199, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5200, 'Brigit artist born in the 1960s who makes sculpture.', 5200, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5201, 'Ruggaber takes elements of furniture and architectural fixtures and fittings and transforms them into minimal sculpture, for example a hand rail upholstered in leather effect vinyl.', 5201, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5202, 'Neil Rumming', 5202, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5203, 'British artist born in the 1970s who makes large paintings up to 3 meters high and works on paper.', 5203, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5204, 'Rumming juxtaposes imagery such as cross sections from medical books, tattoos, graphic design for rock band album covers, or graphic images of flames or flowers, for example, to make a complex abstract but decorative composition painted in hard edged bright acrylic colours.', 5204, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5205, 'John Russell', 5205, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5206, 'British artist, formerly a member of Bank, who makes large scale representational paintings which are very messy and badly painted.', 5206, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5207, 'Russell also makes performances.', 5207, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5208, 'Art, artists and the art world are the subject of his often polemical work.', 5208, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5209, 'Russell sometimes collaborates with Fabienne Audeoud.', 5209, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5210, 'Johannes Rust', 5210, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5211, 'Austrian artist who made a film with Jonathan Faier !Anne Ryan.', 5211, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5212, 'Irish artist born in the 1960s who makes cowboy paintings, each one based on a still from a Hollywood western.', 5212, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5213, 'Ryan uses a palette of green grey and brown to depict men and horses in landscapes, or men in saloons.', 5213, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5214, 'Giorgio Sadotti', 5214, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5215, 'British artist born in the 1960s who has made work in a variety of media and staged events.', 5215, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5216, 'He arranged a dinner party for selected artists, dealers and curators at which the guests conversations were recorded.', 5216, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5217, 'For a work entitled Be Me he sat in a gallery all day every day and invited anyone to come and take his place.', 5217, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5218, 'Jenny Saville', 5218, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5219, 'British painter born in the late 1960s who makes monumental paintings, at least four metres high, of nude women and photographs.', 5219, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5220, 'Saville&#x2019;s subjects are often very large women and the subject of her work is really flesh.', 5220, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5221, 'A painting will consist largely of expanses of painted flesh, onto which in the early years she inscribed text as if it were cut into the flesh.', 5221, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5222, 'In the 1990s Saville made paintings of women lying on a sheet of glass so that their flesh squashed and distorted.', 5222, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5223, 'Kathy Schimert', 5223, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5224, 'American artist born in the 1960s who makes installation, video and ceramic sculpture.', 5224, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5225, 'Schimert made a film of a boy under water with wings on who represents drowned Icarus.', 5225, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5226, 'Andreas Schlaegel', 5226, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5227, 'German artist born in the 1960s who make installation and sculpture.', 5227, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5228, 'Schlaegel made a nude portrait from French fries, a sofa from washing up sponges and an arm chair from toilet rolls.', 5228, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5229, 'He became an Elvis impersonator which he considered part of his practise as an artist.', 5229, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5230, 'Adrian Scrivener', 5230, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5231, 'British artist born in the 1960s.', 5231, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5232, 'George Shaw', 5232, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5233, 'British painter who makes small landscape paintings using shiny enamel paint which depict housing estates, garages, car parks and streets in suburbia.', 5233, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5234, 'Shaw paints in a detailed and realistic way.', 5234, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5235, 'Jim Shaw', 5235, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5236, 'American artist born in the 1950s who is best known for his collection known at the Thrift Store Paintings, an expanding collection of found art from which he select for exhibition, and the Dreams drawings, daily hand drawn records of his dream life, in the form of cartoon strips with text.', 5236, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5237, 'The dreams very often feature art, artists, museums and dealers !Elsa Sighicelli.', 5237, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5238, 'American artist born in the 1960s.', 5238, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5239, 'Roman Signer', 5239, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5240, 'A German live artist who describes his works as sculptures, Signer is best known for works from the 1980s onwards.', 5240, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5241, 'Signer&#x2019;s materials are chiefly his own body, furniture, household and DIY objects and materials and explosives and his performances and actions are documented as short films and photographic sequences.', 5241, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5242, 'They nearly always take place in a field or other natural environment.', 5242, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5243, 'For example Signer stands on three boxes stacked one on the other in the middle of a field.', 5243, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5244, 'Each box is rigged to explode in sequence.', 5244, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5245, 'Signer remains standing as each one collapses, bringing him eventually to the ground.', 5245, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5246, 'Something is placed in a stream, and the action of the running water eventually causes an explosive reaction.', 5246, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5247, 'In both cases the resulting puffs of smoke is visually important to signer.', 5247, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5248, 'He also used a bright orange ball in a number of works.', 5248, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5249, 'Signer uses the formal language of sculpture, the body and the plinth, the landscape, and subverts it by adding the destructive power of explosives in a highly controlled way.', 5249, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5250, 'The works seem slapstick and humorous but in fact they are precisely organised, even the puffs of smoke are carefully planned.', 5250, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5251, 'Signer has also made some site specific firework displays.', 5251, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5252, 'DJ Simpson', 5252, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5253, 'British artist born in the 1970s who make very large (at least 4 by 5 metre) machine carved panels.', 5253, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5254, 'These are made as if they are abstract paintings.', 5254, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5255, 'Simpson uses an electric router to gouge out channels to create lines, which loop and curve over the surface, as well as other tools that can inscribe the surface that he works on.', 5255, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5256, 'He works on prepared and on found surfaces, such as laminate table tops, as well as building materials such as ply and silver insulation board, in fact any sheet material that is composed of layers so that the lines Simpson cuts out reveal the contrasting colours of the layer beneath ! Jane Simpson.', 5256, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5257, 'British artist born in the 1960s who is best known for her ice sculptures, in which she uses refrigeration and ice as a construction tool and material.', 5257, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5258, 'One of the earliest made in the early 1990s consists of two halves of a heart made from metal and brass sheet, the separated surfaces refrigerated and water added so that ice forms, sticking the heart back together.', 5258, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5259, 'Another work from the same period is a small refrigerated metal shelf on which is placed a block of butter.', 5259, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5260, 'These works are conditional &#x2013; they only remain in their intended state as long as the refrigeration process is taking place.', 5260, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5261, 'From the beginning of her career Simpson has also had an interest in vessels and containers, starting with a collection of Tupperware, which she displayed in vitrines, and photographed, the photographs enabling the plastic mass manufactured containers to transcend their reality and appear far more precious.', 5261, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5262, 'In 2000 Simpson began a series of works in which she modelled vessels depicted in paintings, for example those in Morandi paintings, casting these in rubber, and later making them from scratch in glazed porcelain.', 5262, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5263, 'These vessels are exhibited in groups on shelves and plinths.', 5263, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5264, 'This interest in functional mass produced containers led Simpson to begin to cast similar containers in rubber, and then to cast furniture, leading to a series of floppy furniture works.', 5264, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5265, 'Simpson cast stools, chairs, tables and sideboards in rubber, creating objects that absolutely refuse their function and flop in a heap on the floor almost seeming to be more like curled up or collapsed four legged animals.', 5265, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5266, 'There is an abject side to Simpson&#x2019;s work, which is contrasted with the grandeur of ambition in some of the ice sculptures.', 5266, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5267, 'An antique sideboard is cast in plaster and its top refrigerated, inviting contemplation of the function of such a piece of furniture, and highlighting the appearance of a layer of ice as a decorative surface.', 5267, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5268, 'A structure somewhat like a cross between double sided train seat, a fountain but chiefly resembling a urinal, has steel sides curving down into a trough.', 5268, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5269, 'These are refrigerated and the water flow is continuously frozen.', 5269, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5270, 'These transitional works marking the beginning of a series of works in which Simpson refrigerated already existing objects, often in situ, in order to explore the qualities of ice as a decorative surface.', 5270, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5271, 'These works include a refrigerated chandelier and ornate cast iron gates.', 5271, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5272, 'Daniel Sinsel', 5272, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5273, 'German artist who paints watercolours depicting young men and boys often naked or engaged in sex acts.', 5273, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5274, 'The figures are often shown in rural landscapes.', 5274, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5275, 'There is an idyllic atmosphere yet the figures in the paintings are clearly contemporary.', 5275, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5276, 'Sense&#x2019;s medium is traditionally associated with art of the past, with amateur art or with graphic art and illustration gives the images an ironically innocent quality.', 5276, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5277, 'Smith and Stewart', 5277, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5278, 'Artist partners, born around 1970, who made a number of performative video works before turning to installation.', 5278, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5279, 'Kiss is a video in which one partner covers the other with red lipstick kisses until there is no skin left untouched.', 5279, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5280, 'The gesture of covering someone with kisses becomes sinister as the flesh begins to take on the appearance of having been beaten, bruised or flayed.', 5280, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5281, 'In another work one partner is submerged in a bath, and the other periodically place their face into the water and breathes air into the submerged partners mouth enabling them to stay submerged.', 5281, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5282, 'These simple acts of partnership, intimacy and trust have violence and control as their counterpoint.', 5282, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5283, 'Smith and Stewart moved on to investigate ideas about control and implicit violence, for example in an installation made in 2003.', 5283, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5284, 'This consisted of a 29 metre long 4 meter high breezeblock wall constructed diagonally across the gallery, not meeting the wall at either end.', 5284, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5285, 'On one side of the wall the gallery was empty and dark.', 5285, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5286, 'On the other side the space was also dark but a chair, various amplifiers speakers and cables could be seen.', 5286, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5287, 'Projected onto the brick wall is a film of a hand covered in a black round shape, its surface bound with layers of shiny black plastic tape, knocking against a wooden board leaning against the wall.', 5287, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5288, 'The film is made on the actual wall at the actual place where it is projected, leading to a double take in the viewers mind about what is real (the board is not really there).', 5288, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5289, 'The lights turn on and off apparently in a random fashion.', 5289, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5290, 'They are pendant light bulbs.', 5290, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5291, 'The scene becomes sinister, the knocking like the sound of some possible torture or unspecified but unpleasant event.', 5291, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5292, 'Bob and Roberta Smith', 5292, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5293, 'The pseudonym of British artist Patrick Brill, born in around 1960.', 5293, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5294, 'Roberta is in fact the name of his sister, but he does not work with her.', 5294, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5295, 'Brill makes painting, sculpture and installation using basic materials such as house paint, cement, clay, and timber.', 5295, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5296, 'He has also made participatory works, inviting visitors to use clay provided to add to his collection of clay vegetables.', 5296, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5297, 'His work draws attention to the role of the artist, the status of the art object and the role of the viewer through the copious use of hand painted text, and knowingly clumsy modes of construction.', 5297, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5298, 'The text is always capitalised, painted in bright colours, a different colour for each letter, on a white background.', 5298, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5299, 'Brill&#x2019;s work is socially engaged in the sense that he acknowledges that the viewer is not to be deceived by art, also questioning the legitimising role played by commercial success and highlighting the mundane reality of most artists lives.', 5299, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5300, 'He portrays himself as a fallen hero, a failed romantic busy with the gritty reality of the important job of the artist.', 5300, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5301, 'Brill operates a kind of grass roots art politics, often creating events or action accompanied by promotional material and badges.', 5301, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5302, 'An example is his 2002 initiation to all artists to bring their old work to be destroyed in a massive purgative action.', 5302, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5303, 'His hand painted slogans are a feature of these, and by the 2000s these became the predominant form of his work.', 5303, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5304, 'Brigit Smith', 5304, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5305, 'British artist born in the 1960s.', 5305, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5306, 'Kerry Smith', 5306, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5307, 'British artist born in the 1960s who makes moulded painted fibreglass figurative sculpture.', 5307, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5308, 'She has made a pregnant school girl holding out her hand in the style of a charity collection box, and small girl who is fixed to project horizontally form the wall just about floor level.', 5308, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5309, 'Pierrick Sorin', 5309, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5310, 'French artist who makes work about knowledge and information, including a film in which he purports to be an expert explaining theories wit the aid of a white board, which he is fact making up as he goes along.', 5310, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5311, 'John Spiteri', 5311, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5312, 'Australian artist who makes figurative paintings and autobiographical videos.', 5312, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5313, 'In the videos he challenges himself alone with the camera.', 5313, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5314, 'The videos are usually a response to a song and a location.', 5314, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5315, 'For example in one film set in a bathroom Spiteri sings a rap song so fast that it is barely believable.', 5315, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5316, 'It seems clear that this is a film that has been speeded up, but in fact Spiteri has practised until he could do it perfectly.', 5316, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5317, 'In others, he samples a part of a song and uses this as the soundtrack for a self interrogation, in which he faces the camera and talks to it, such as I Can&#x2019;t Do That, a film based on a sample from a song by the pop singer Cher in which Spiteri is seen regarding himself in a mirror repeating &#x2018;I can&#x2019;t do that&#x2019; in a litany to hopelessness.', 5317, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5318, 'The alter ego that Spiteri has created for his work is a blend of a character who is not very good at life but is extremely good at the tasks carried out in the films.', 5318, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5319, 'Spiteri has also made small detailed narrative paintings that seem to be illustrations for a 1950s children&#x2019;s story.', 5319, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5320, 'These are painted in enamel paint in bright colours.', 5320, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5321, 'Spiteri has made a video of each painting that adds a narrative, consisting of an overheard conversation.', 5321, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5322, 'Since 2000 Spiteri has been making oil paintings.', 5322, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5323, 'Fergal Stapleton', 5323, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5324, 'British artist born around 1970.', 5324, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5325, 'Frances Stark', 5325, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5326, 'American artist born in the 1960s who uses a variety of media.', 5326, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5327, 'Stark also writes as part of her practise.', 5327, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5328, 'Her book The Architect and the Housewife is about her practise as an artist and the difficulty of making art at home.', 5328, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5329, 'Stark ahs made a series of videos of her cats at home in her apartment.', 5329, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5330, 'She also makes sculptures, including one of a small Perspex grandfather clock.', 5330, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5331, 'Stark makes quantities of drawings, fro example her text drawings made using carbon paper which feature a word or a number of words written out in rows each row being added to.', 5331, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5332, 'The low tech transfer quality gives this work an ephemeral quality.', 5332, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5333, 'Simon Starling', 5333, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5334, 'British artist born in the 1960s who makes sculpture by turning one thing into another.', 5334, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5335, 'For example a bible into a chair &#x2013; Starling will dismantle the bicycle, strip it down, grind, melt and otherwise reduce it to its constituents which he then recasts as another object entirely.', 5335, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5336, 'Pursuing his interest into how one thing can be made into another, Starling has also made a group of works, which are based on United Nations blueprints for agricultural implements.', 5336, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5337, 'These are instructions in how to make essential implements from freely available materials, such as oil cans, bicycle parts, and pipes.', 5337, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5338, 'Starling constructs these fully functioning implements such as ploughs, harvesters and irrigators, often painting them, and displays them as sculpture.', 5338, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5339, 'Georgina Starr', 5339, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5340, 'British artist born in the 1960s who makes video and installation art.', 5340, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5341, 'Starr creates a variety of personas and worlds and weave a fiction around herself that is sometimes quite like a children&#x2019;s story.', 5341, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5342, 'One installation in the early 1990s created a fairy tale or cartoon like environment in which the viewer could wander.', 5342, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5343, 'In 1999 she made the Bunny Lakes trilogy, a multi part work about teenage girls from a place called Bunny Lakes, based on a true story.', 5343, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5344, 'Starr&#x2019;s earliest works were very simple.', 5344, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5345, 'Crying, a video, shows Starr bursting into tears and crying sitting in front of the camera.', 5345, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5346, 'Another is a record on which a whistled tune is recorded.', 5346, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5347, 'The tune was made by chance composition &#x2013; Starr threw torn pieces of paper in the air, noted where they fell and translated this spacing into musical notation.', 5347, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5348, 'Jemima Stehli', 5348, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5349, 'British artist born in 1962, Stehli makes photographic work centring on her own body.', 5349, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5350, 'Stehli began as a sculptor whose early works included scarves several metres long knitted on very large diameter needles, which were presented folded on the floor, and wool embroidered padded panels, around sixty cm long featuring words.', 5350, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5351, 'In the early 1990s Stehli began to make resin casts of isolated parts of her own body, such as a hand complete with watch or a breast, moving on to making casts of vessels and bottles which she presented in groups, and objects such as a purse or a tray.', 5351, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5352, 'These small domestic scaled sculptures are lacquered and highly polished, often in deep reds, blues and black.', 5352, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5353, 'Stehli made a performance work for which she lay naked except for a pair of high heeled shoes motionless on the floor of a gallery, titled Shoes Chosen by the Curator in the mid 1990s.', 5353, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5354, 'She presented her own body as a sculpture and documented this by photographing it.', 5354, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5355, 'This led her to make a series of photographs of herself naked.', 5355, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5356, 'Stele&#x2019;s photographic work since this point has concentrated on the relation of the viewer to the female body.', 5356, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5357, 'She made two groups of images that alluded to bondage, in which parts of her body appear naked, the cable release of the camera highly visible.', 5357, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5358, 'One group of photographs is black, in deep shadow; the other is white and bright.', 5358, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5359, 'She then made a series based on the work of the 60s artist Allen Jones.', 5359, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5360, 'Stehli recreated Jones&#x2019; famous fibreglass sculptures of women in high heels and underwear acting as the support for glass table tops or stools, photographing herself recreating the poses, without the underwear but with the shoes.', 5360, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5361, 'The photographs are printed so that she appears life size, in black and white.', 5361, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5362, 'Stehli work has sometimes involved other people.', 5362, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5363, 'She invited women to be photographed by her naked, with herself also in the photograph.', 5363, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5364, 'She then made what has become her best known work a group of photographs taken by men.', 5364, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5365, 'She invited a number of curators and critics to come to her studio and be photographed sitting or standing as she faced them and removed her clothes except for a pair of high heels.', 5365, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5366, 'The image is composed to show her back view in the foreground and the man looking outwards.', 5366, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5367, 'Some of the men are looking at Stehli, some at the camera, some elsewhere.', 5367, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5368, 'The men hold the cable release.', 5368, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5369, 'A series of works based on a particular photograph of Helmut Newton&#x2019;s followed.', 5369, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5370, 'Stehli recreated Newton&#x2019;s black and white image of four fashion models standing naked staring at the camera in her studio, placing herself to the far side of the image, leaving space where the others are in the Newton original, on a white photographic backdrop.', 5370, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5371, 'She stands in the exact pose of the original, naked in one photograph and clothed in jeans and a t shirt in the other, in both cases holding the cable release, the cable trailing in from the camera at the bottom of the image.', 5371, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5372, 'A number of works made on this basis included a series based on the paintings of Francis Bacon.', 5372, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5373, 'For these colour photographs Stehli moves in front of the camera set on a long exposure.', 5373, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5374, 'The result is a blurred image of intense colour, distorting features and body parts in the same way that Bacon does.', 5374, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5375, 'In a similar series she uses a red silk scarf moving it around her body so that the red blurs and makes a virtually abstract image.', 5375, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5376, 'Since 2000 Stehli has made images in which she is increasingly absent.', 5376, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5377, 'A series of self portraits in her studio show her often lying on the ground at odd angles to the camera, her gaze not directed at the viewer.', 5377, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5378, 'Myra Stimson', 5378, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5379, 'British artist born in the 1960s who make paintings.', 5379, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5380, 'Stimson&apos;s early work was figurative.', 5380, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5381, 'In 2000 she made a series of paintings in which she reproduced shopping lists she had found in a supermarket.', 5381, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5382, 'Jessica Stockholder', 5382, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5383, 'American sculptor born in the 1960s who makes very large installations.', 5383, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5384, 'Stockholders early work consisted of small assemblages of timber, carpet, household objects, wool and fabric.', 5384, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5385, 'She began to make larger works &#x2013; a transitional work consisted of painting areas of a garden shed, including painting the side it blue, extending the colour over the grass in front of the shed.', 5385, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5386, 'A similar work involved a painted mattress.', 5386, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5387, 'Stockholder&#x2019;s mature work consists of much larger scale site specific installations.', 5387, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5388, 'These are described by her as paintings and are often based on landscapes or still lives, for example by C&#xe9;zanne.', 5388, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5389, 'The installations are large sprawling constructions, often emerging from or including in their structure a partial demolition of the gallery wall.', 5389, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5390, 'They appear like unfinished construction work which has a life of its own.', 5390, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5391, 'Stockholder uses lengths of timber and board, or spreads items and material over the floor to build an environment, which is transparent, can be walked through and around, and which presents multiple views according to the angle from which they are observed.', 5391, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5392, 'She adds flat planes in the form of sheet material, transparent lighting gels, fabric and carpet, and then paints certain areas.', 5392, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5393, 'She uses light in the form of light bulbs in holders, and has also added miniature fans to create movement.', 5393, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5394, 'In one installation a row of oranges sits on a shelf.', 5394, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5395, 'In another a large carpet twists as if it is flying and has collided with the installation.', 5395, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5396, 'Paint, timber and rope spill onto and extend over the floor.', 5396, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5397, 'One work is made from a bank of baths, arranged in rows then cut into with a blowtorch and painted, the orange paint extending right across the floor.', 5397, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5398, 'Another work uses a number of refrigerators arranged in a wall like structure.', 5398, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5399, 'A work made from a large pink sheet of plastic pulled up at various points by wires attached to the ceiling ahs a long title including the words &#x2018;big rock candy mountain&#x2019;.', 5399, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5400, 'Most of stockholders works have very long impenetrable titles that seem as though they may explain the work but in fact do not.', 5400, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5401, 'Tim Stoner', 5401, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5402, 'British artist born in the 1970s who makes figurative paintings of people and groups of people.', 5402, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5403, 'Stoner paints figures in silhouette with a halo of light behind them and adds a light coloured layer of paint, which serves to blur the image so that it appears as if it is viewed against the sun.', 5403, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5404, 'Thomas Struth', 5404, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5405, 'German artist who makes photographic portraits, landscapes and interiors characterised by their apparent stillness as if time has stood still.', 5405, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5406, 'Michael Stubbs', 5406, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5407, 'British artist born in the 1960s who makes paintings and sculpture about painting, for example his squashed canvases.', 5407, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5408, 'These are wall mounted works consisting of several small square canvases about fifty cm square sandwiched together with very thick layers of oil paint in a variety of colours.', 5408, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5409, 'These are bolted together through the stretchers so that the paint is squeezed out all around the edges, giving the impression that there are several hidden paintings.', 5409, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5410, 'The whole object is mounted on the wall, the top canvas blank.', 5410, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5411, 'Daniel Sturgis', 5411, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5412, 'British painter born in the 1960s who makes brightly coloured hard edged pattern paintings based on flowers.', 5412, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5413, 'Hiroshi Sugimoto', 5413, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5414, 'Japanese photographer who makes photographs of a variety of subjects, often focussing on representing light, as for example in an number of works showing the light from candles.', 5414, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5415, 'Ricky Swallow', 5415, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5416, 'Australian artist born around 1970 who makes sculpture, for example a group of works made using record turntables as their base, on which Swallow placed model making figures and constructed space ships and other futuristic vehicles, habituations and buildings, incorporating the parts of the record player in to the whole.', 5416, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5417, 'Some of the sculptures make use of the spinning of the turntable or the movement of the needle arm.', 5417, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5418, 'The whole sculpture is sprayed with grey paint and presents a very convincing and ultimately unnerving scene from a future envisaged by swallow.', 5418, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5419, 'Sarah Sze', 5419, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5420, 'American artist born in the 1960s who makes site specific installations in which she arranges a vast amount of objects and materials over an entire room and its walls and ceiling.', 5420, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5421, 'Sze chooses discarded materials, plastic bottles, cotton buds, cable, wire, paper, mass produced plastic vessels, toys, beads, sugar, glitter and hundreds of other items and materials and deploys them in a formal abstract composition also choosing to paint the walls, taking into account their form and colour.', 5421, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5422, 'The vast scale of the undertaking is part of the effect of the work producing an effect of visual satiety in the viewer.', 5422, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5423, 'Neal Tait', 5423, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5424, 'British painter born in the 1960s who makes relatively small paintings sometimes semi abstract, sometimes depicting objects.', 5424, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5425, 'He paints in a loose gestural style.', 5425, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5426, 'Tomoko Takahashi', 5426, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5427, 'British artist who makes large scale installations from discarded furniture and junk.', 5427, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5428, 'An early work in a gallery basement seemed at first sight not to be art but to be simply an excessively untidy storeroom that had perhaps been burgled.', 5428, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5429, 'Takahashi has made numerous gallery installations; one consists of office furniture and equipment, which is strewn over the space in apparent chaos.', 5429, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5430, 'In fact the arrangement is deliberate and painstaking.', 5430, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5431, 'Filing cabinets, cupboards, desks, chairs, computers, pens, telephones, faxes, lamps, kettles, lengths of electric cable and just about anything that might be found in a modern office are arranged to look as if a cataclysmic event has taken place, perhaps an earthquake, a search by government agents, creating a sense of unease.', 5431, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5432, 'The destruction of an everyday environment on such a grand scale underlines the temporality and built in in obsolescence of our surroundings.', 5432, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5433, 'Takahashi has also make a website called Word Perhect which is a hand drawn and written interface in which the viewer can select from a variety of notes, post its, scraps of paper and jottings on the back of envelopes and paper bags found in the artists studio and add read her comments about the contents.', 5433, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5434, 'The reader can type on the interface and on the notes in a font based on Takahashi&#x2019;s handwriting.', 5434, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5435, 'Sam Taylor Wood', 5435, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5436, 'British artist born in the 1960s who makes photographic and video work.', 5436, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5437, 'Taylor Wood is one of a number of artists who emerged in the early 1990s who are known as young British artists or YBAs.', 5437, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5438, 'One of Taylor Wood&#x2019;s early works, Brontosaurus, is a video of a young man dancing to disco music, naked, swinging and flapping his penis energetically in the process.', 5438, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5439, 'Another early work is a four screen video projection showing four opera singers performing La Boheme.', 5439, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5440, 'The screens on which they appear are placed in a box shape, creating the sense that they are in a room which the viewer has entered, and that they are singing together.', 5440, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5441, 'It becomes apparent that the films were shot separately and the singers are singing together but not together.', 5441, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5442, 'A similar work, showing a couple having a row in a kitchen, is projected onto the walls in a corner, one showing the man and one the woman.', 5442, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5443, 'The frame is composed so that it appears that one half of the kitchen, in which the man stands, is on one wall and the other half, in which the woman stands, is on the other.', 5443, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5444, 'This gives the illusion that the space in which the filmed event is taking place has been partly reconstructed.', 5444, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5445, 'It becomes clear that the row is in fact performed by actors who are not in the room at the same time.', 5445, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5446, 'In the late 1990s Taylor Wood began to take panoramic photographs using a camera, which is set on a slowly revolving tripod.', 5446, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5447, 'This enabled her to take a 360 degree view of a room and its occupants.', 5447, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5448, 'She choreographed a series of group portraits featuring people she knew, taking place in borrowed apartments and other places.', 5448, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5449, 'The long duration of the exposure made it possible for some of the subjects appear twice in the photograph.', 5449, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5450, 'These colour photographs are about 3 metres long.', 5450, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5451, 'Taylor wood has also made a large number of conventional photographs including landscapes portraits and self portraits.', 5451, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5452, 'One shows her sitting on the steps of a building holding a young man, who is limp in her arms, a reference to paintings of the Virgin Mary holding Jesus.', 5452, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5453, 'Juergen Teller', 5453, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5454, 'British artist, formerly a fashion photographer, who has made work about the fashion world, including photographing hopeful models at the moment the door of the agency is opened, a group of images relating to Bertolt Brecht&#x2019;s life in Berlin and the city after the wall and autobiographical work.', 5454, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5455, 'He photographed a frozen dead dog sticking out of a refuse bin.', 5455, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5456, 'Kathy Temin', 5456, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5457, 'Australian artist born in the 1960s who makes photographic, video and installation work, centring on the creation of domestic interior spaces in the gallery, fashion and fetishism.', 5457, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5458, 'Temin made an installation of Polystyrene room dividers crudely cut out in a 1960&#x2019;s lattice pattern.', 5458, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5459, 'She has made a variety of deliberately clumsily fashioned models of dwellings and spaces, and well made domestic items such as lamps and furniture.', 5459, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5460, 'Temin also made a video documentation of two people dressed in koala suits, and has done work about shoe fetishism and celebrity.', 5460, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5461, 'Thomson and Craighead', 5461, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5462, 'British artists born in the 1960s who work together.', 5462, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5463, 'David Thorpe', 5463, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5464, 'British artist born in the late 1960s who makes complex collages from coloured paper, as well as specialist paper such as bark paper.', 5464, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5465, 'Thorpe&#x2019;s early works are based on photographs of 1960s and 70s modernist buildings, seen by day and by night.', 5465, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5466, 'The image is built up from layers of paper cut to match the graduations of colour on the original.', 5466, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5467, 'A night view of a house high on a hill is made from a great range of dark blue, grey and black paper, with bright orange for the illuminated windows, in which tiny black silhouetted figures are seen.', 5467, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5468, 'Thorpe&#x2019;s views of modernist architectural ideals led him to begin to create images and to illustrate a Utopian vision.', 5468, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5469, 'The collages began to depict invented buildings with symbolic overall structural design.', 5469, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5470, 'He also designed an indoor planter which consisted several levels of mirrored glass, a small water feature and meadow plants.', 5470, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5471, 'Matthew Tickle', 5471, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5472, 'British artist born in the 1960s.', 5472, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5473, 'Wolfgang Tillmans', 5473, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5474, 'German artist born in the 1960s who makes photographic images of everyday objects and interiors, people, still lives, and abstract images made in the darkroom.', 5474, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5475, 'Tillmans, formerly a fashion photographer, pioneered the influential everyday life, snapshot style of fashion photography that are so characteristic of the 1990s in Britain.', 5475, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5476, 'Tillmans always exhibits his work in groups, unframed, pinned to the wall, printed in various sizes from postcard size to three metres high.', 5476, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5477, 'The images are produced as inkjet prints.', 5477, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5478, 'The groups are not usually obviously related in terms of subject matter but are formally related (there are exceptions such as a collection of re photographed images of young soldiers cut from newspapers).', 5478, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5479, 'Thus an image of Kate Moss, a fashion model, might be placed next to one of some socks drying on a radiator, a naked man, some rotting fruit and an ashtray, a landscape.', 5479, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5480, 'The images might be intimate or observational, and Tillmans&#x2019; work covers the range of categories including still life, landscape, cityscape, skyscraper, group and single portraiture.', 5480, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5481, 'He photographs what is close to him and does not set out to find locations or subjects.', 5481, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5482, 'A particularly well known image from the 1990s is of two friends sitting on a branch of a tree, naked except for raincoats and boots.', 5482, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5483, 'Sometimes Tillmans returns to a subject repeatedly, most famously in his work Concorde, a collection of photographs, also published as a book, of the aircraft in flight made over a period of weeks mostly at Heathrow airport where the plane spotters gather.', 5483, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5484, 'In 2000 Tillmans began to make more abstract images, using darkroom techniques and dyes to make colour images for example a pool of blurred red colour on a white ground that seems like a rose so that the connection with painting in his work, which has always been present, has become more obvious.', 5484, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5485, 'Padraig Timoney', 5485, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5486, 'British artist born in the 1960s.', 5486, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5487, 'Mark Titchener', 5487, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5488, 'British artist born in the 1960s.', 5488, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5489, 'Rirkrit Tiravanija', 5489, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5490, 'Thai artist known for his installations that are constructed to be social environments.', 5490, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5491, 'Tivrana became known in the 1990s for his noodle bar, which he designed and built from ply and timber as counter with seating, where he cooked and served bowls of noodles to viewers.', 5491, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5492, 'This is an idea which he has developed and which has taken place in a variety of locations and forms.', 5492, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5493, 'Grazia Toderi', 5493, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5494, 'Italian artist who made a digital video collage in which a model of a satellite is seen apparently floating in zero gravity inside a space consisting of a curved ceiling decorated with plaster relief which is digitally doubled to create a vault like space.', 5494, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5495, 'Fred Tomaselli', 5495, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5496, 'American artist who has made a number of works mixing painting and drawing with collage, which characteristically feature patterns made by placing dried leaves and flowers under a thick layer of poured resin.', 5496, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5497, 'Chris Tosic', 5497, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5498, 'British artist born in the 1960s who makes paintings, drawings and sculpture.', 5498, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5499, 'In 2003 Tosic made a work consisting of a group of heads carved on the end of pencils.', 5499, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5500, 'Gavin Turk', 5500, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5501, 'British artist born around 1960 who is known for his work in mixed media centring on his signature and the idea of authorship.', 5501, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5502, 'An early work of Turks is a men&#x2019;s urinal signed by him and placed on a plinth.', 5502, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5503, 'This work is a copy of a work by Marcel Duchamp.', 5503, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5504, 'Turk has made a variety of paintings of his own signature, something which is usually a tiny detail in the history of painting yet very important in terms of authentication and therefore of value.', 5504, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5505, 'Turk has painted his signature in oil paint, screen printed it and made a relief from polystyrene balls.', 5505, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5506, 'Perhaps Turks best known work is a life size wax work of Turk dressed as Johnny Rotten in the pose of Elvis Presley.', 5506, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5507, 'He later made a waxwork of himself as a person living on the streets, with filthy skin dressed in ragged clothes and shoes.', 5507, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5508, 'A companion work is an empty sleeping bag.', 5508, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5509, 'James Turrell', 5509, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5510, 'American artist who makes large scale installations, either in museum, on selected outdoor sites, or to commission.', 5510, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5511, 'Turrell combines architectural structures with natural or artificial light to create visual tricks that give the illusion of a depth or height that isn&#x2019;t there, of to focus the viewers vision on the sky.', 5511, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5512, 'An example is a gallery installation, which consists of a dark room in which there seems to be a red glowing wall panel, which seems to have some kind of activity on its surface.', 5512, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5513, 'It is only when the viewer steps right up the apparent panel that it can be discerned that there is a rectangle panel cut out of the wall, behind which is a void which is lit with red light, and in fact there is nothing there.', 5513, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5514, 'Another gallery installation is made by making window where no window is expected so that the viewer is fooled into thinking that there is a sky coloured panel on the ceiling when in fact it is the sky.', 5514, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5515, 'Turrell&apos;s outdoor installations are sometimes very large scale.', 5515, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5516, 'His observatory is a sunken earth work at the top of a specially constructed mound that is designed to harness the changing light for that geographic location at all times of year to create effects fro the viewer inside the work.', 5516, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5517, 'The viewer&#x2019;s view of the sky is controlled by the structure of the space that Turrell has designed for the observatory.', 5517, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5518, 'Luc Tuymans', 5518, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5519, 'German painter born in the 1950s who makes a large number of paintings nearly always the same size about 80 by 50 cm.', 5519, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5520, 'Tuymans&#x2019; uses a sparse palette of subdued colours, rarely mixing colours, but using a range of tones of one or two colours in each work.', 5520, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5521, 'His paintings are very simple representations of everyday subjects such as the pattern on wallpaper, flowers, furniture and objects.', 5521, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5522, 'He has been very influential for a generation of artists.', 5522, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5523, 'Keith Tyson', 5523, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5524, 'British artist who makes installations and drawings.', 5524, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5525, 'Tyson become known in the 1990s for his Artmachine, a sculpture that produced random artworks the description of which would be ejected from the machine on a card.', 5525, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5526, 'Tyson would then construct the artwork.', 5526, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5527, 'One installation consisted of a whole gallery filled by these art works linked by cables.', 5527, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5528, 'The artworks usually juxtapose household, found objects and building materials in unlikely combinations and sometimes have a kinetic or sound feature.', 5528, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5529, 'His interest in multiplication of ideas is always documented in his prolific drawing practise.', 5529, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5530, 'Tyson produces drawings often with text which address any number of scientific or eccentric inventions, everyday objects, astronomy, geography, physics and chemistry.', 5530, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5531, 'Typically these drawings are always the same size, 120 cm by 80 cm, but Tyson also produces much larger paintings.', 5531, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5532, 'Tyson also produced a black monolithic sculpture which emits a low hum as if it is a powerful minimal futuristic machine of some sort.', 5532, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5533, 'Udomski', 5533, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5534, 'Artist who makes large paintings up to 3 metres high by cutting out single letters from newspapers and magazines, sticking them onto the canvas and painting around them.', 5534, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5535, 'The resulting dense pattern, perhaps of the letter &#x2018;O&#x2019; in upper and lower case hundreds of times painted around with very dark brown paint, gives the impression of a pattern o dots.', 5535, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5536, 'Piotr Uklansky', 5536, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5537, 'Polish artist born in the 1960s living in America who works in a variety of media.', 5537, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5538, 'One of Uklansky best known works is a nightclub dance floor made from squares of coloured plastic illuminated from below, which he has installed in a number of galleries and which is permanently installed in a bar in New York.', 5538, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5539, 'Uklansky has made other floor works, including a puddle of a certain amount of water poured onto the floor, and a floor skating drawing, black rubber marks made by the artist&#x2019;s shoes when he ice skated on a gallery floor.', 5539, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5540, 'Uklansky has an interest in the ephemeral and the unnoticed.', 5540, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5541, 'An early work consisted of a number of printed colour advertising flyers, which in fact advertised nothing sensible, pushed through the door of the gallery and the surrounding area as if they were junk mail.', 5541, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5542, 'Uklanksy also makes photographic work.', 5542, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5543, 'Nazis is about 40 head and shoulders photographs of actors playing Nazi soldiers in cinema films.', 5543, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5544, 'Jeffrey Vallance', 5544, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5545, 'American artist born in the 1950s who makes installation work and writes extensively about art both as part of his practise and as a critic.', 5545, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5546, 'Vallance lives in Las Vegas where he has established The Liberace Museum to house a collection of memorabilia and artefacts related to the pianist.', 5546, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5547, 'This is in part ironic and in part a genuine tribute.', 5547, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5548, 'Vallance travels widely and part of his practise is an ethnographic investigation into the sacred objects of other cultures.', 5548, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5549, 'Vallance has made a body of work that investigates the religious relic, making relics of his own and investigating existing ones.', 5549, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5550, 'He made a Shroud by covering his face with coffee and imprinting it on a cloth.', 5550, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5551, 'He shows that the images on the Turin Shroud are in fact images of nuclear mushroom clouds and explains why he thinks this is the case.', 5551, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5552, 'He adopts a frozen chicken, calls it Binky and shows that it can be resurrected after death inn the manner of Jesus.', 5552, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5553, 'He researched in detail the whereabouts of the various relics of nails and wooden shards of the True Cross and wrote about them.', 5553, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5554, 'Vallance travelled to Tonga.', 5554, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5555, 'Before he left he corresponded with the King and asked him what gift he would like.', 5555, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5556, 'The king requested a pair of size thirteen snorkelling fins which Vallance provided.', 5556, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5557, 'The correspondence is published.', 5557, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5558, 'Lily Van der Stokker', 5558, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5559, 'Dutch artist born in the 1950s who makes wall paintings, screen prints, and self adhesive stickers.', 5559, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5560, 'Van der Stokker&#x2019;s paintings are usually made with accompanying especially made or upholstered furniture.', 5560, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5561, 'The paintings consist of flowers and other decorative elements linked by curling lines, with a few words of text, for example &#x2018;Lily is 43 years old and Jack is 62 years old&#x2019;, which surrounds a two sweater sofa with a pale beige covering.', 5561, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5562, 'Self adhesive stickers might be designed to be applied to a wall where it meets the floor.', 5562, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5563, 'A screen print has an orange green and white plaid pattern on which is a bunch of flowers with the words Thank You.', 5563, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5564, 'Van der Stokker&#x2019;s painting is usually in pastel and pretty colours, painted precisely by hand with hard edges.', 5564, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5565, 'Any text is usually in a hand writing style of lettering.', 5565, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5566, 'Julie Verhoeven', 5566, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5567, 'Artist who makes pencil drawings of women with text that take the style fashion drawings.', 5567, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5568, 'Verhoeven is also a fashion designer.', 5568, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5569, 'Bill Viola', 5569, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5570, 'America artist working in Video born in the 1950s who came to prominence in the 1990s.', 5570, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5571, 'Viola marries an interest in the representation of the human form in sculpture with a fascination for and skill in video technology.', 5571, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5572, 'Early works include an arrangement of different sized monitors from the tiniest one inch square to the more usual domestic size, removed from their casings, strewn on floor or in on work on a shelf.', 5572, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5573, 'On the monitors films of different parts of the artists body like his ear, the crook of arm or the side of his neck.', 5573, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5574, 'It is as if the monitors represent a fragmented body, making a comment on the possibility for classical figurative sculpture in the age of video.', 5574, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5575, 'Also a work installed in a corridor shaped room.', 5575, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5576, 'When the viewer enters the room and walks down it they trigger back projected videos installed behind the false walls.', 5576, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5577, 'Each one projects a person who appears to walk towards the viewer from the far distances, getting gradually larger until they are life size and stand, facing the viewer confronting them.', 5577, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5578, 'Viola used non artist as models and asked them merely to confront the camera.', 5578, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5579, 'The work has a spooky quality and leaves the viewer with an erroneous sense of control.', 5579, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5580, 'Violas best known work is a triptych large screen video projection showing his partner giving birth to their child, his mother dying and himself apparently drowning underwater.', 5580, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5581, 'Simultaneously projected with a breathing/water soundtrack, the work draws obvious parallels between birth and death, birth and being underwater, death and being underwater.', 5581, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5582, 'This work has a powerful impact not least because it features an actual birth and death.', 5582, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5583, 'The work hailed as a religious masterpiece fro the 20th century.', 5583, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5584, 'Continuing his investigation of the sculptural representation of the human from Viola has since gone on to make a series of works on smaller wall mounted plasma screens.', 5584, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5585, 'These works take famous paintings often old masters or renaissance works and recreate them in modern settings using actors and highly controlled lighting.', 5585, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5586, 'Although they are video and therefore exist in time they appear static and little happens, therefore they can be read as paintings.', 5586, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5587, 'In 2003 Viola made a work titled The Passion.', 5587, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5588, 'Sophie Von Hellerman', 5588, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5589, 'British painter who makes loosely painted images of scenes or events that imply narrative, or appear to have a literary reference.', 5589, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5590, 'Hellerman paints with great economy, using the minimum brushwork required to produce dreamlike, hazy images.', 5590, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5591, 'The figures in her paintings often appear as if they are on a stage because most of the canvas is left bare, the thin paint soaked into the canvas.', 5591, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5592, 'Inez Van Lamsweerde', 5592, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5593, 'Dutch artist who makes digitally manipulated images, drawing on her experience in fashion photography.', 5593, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5594, 'Her highly glossy stylised portraits engender a sense of unease in the viewer.', 5594, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5595, 'A beautiful blonde reclining in a swimsuit has male arms, a smiling male model has female hands created by digital alteration that is so skilful as to be initially imperceptible.', 5595, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5596, 'Jessica Voorsanger', 5596, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5597, 'British artist born in the late 1960s whose work is concerned with the mentality of the fan.', 5597, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5598, 'Her video and photographic work often has a participatory or collaborative element &#x2013; she may invite answers to questionnaires, or include peoples responses in her own work.', 5598, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5599, 'Voorsanger has made a number of works about being a David Cassidy fan and about being a football fan.', 5599, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5600, 'Voorsanger has a web site that is integral to her practise.', 5600, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5601, 'Jeff Wall', 5601, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5602, 'Makes very large scale photographic works, usually presented on light boxes.', 5602, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5603, 'Wall remakes works from art history including Hokusai&apos;s &#x2018;Wave&#x2019;, interpreting the works into a modern setting.', 5603, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5604, 'The wave is a group of people on a dyke casing paper blown into the air by the wind.', 5604, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5605, 'He made a work showing dying and wounded men in mud of a battlefield.', 5605, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5606, 'The works are recreated in the most painstaking manner to ensure absolute apparent veracity and accuracy, and photographed in larger format to ensure the sharpest highest quality image.', 5606, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5607, 'It is difficult to fault the quality of the production.', 5607, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5608, 'Mark Wallinger', 5608, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5609, 'British artist born around 1960 who has made work in a wide range of media.', 5609, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5610, 'Wallinger&#x2019;s practise includes video, sculpture, photography and painting.', 5610, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5611, 'There is a strong socio historical aspect to his work and he is interested in football, horse racing and religion.', 5611, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5612, 'Wallinger&#x2019;s early works are mostly sculpture.', 5612, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5613, 'He placed a table football game on dark green marbled plinth, made a tapestry of Munch&#x2019;s painting The Scream and made a work with a bird in a cage.', 5613, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5614, 'Another football work is a photo of Wallinger in the crowd leaving Highbury, a London football ground, carrying a banner bearing some significant words.', 5614, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5615, 'He made a series of full length portraits of his friends presented as if they were homeless people.', 5615, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5616, 'One of Wallinger&#x2019;s early videos was a comparison between the television coverage of the opening of racing at Ascot by the Queen on three successive years.', 5616, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5617, 'This is played simultaneously on three separate monitors and shows that the camera angles, shots, and commentary varies very little.', 5617, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5618, 'Wallinger has made many works about horse racing.', 5618, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5619, 'He made a number of almost life size paintings of horses in the style of Stubbs.', 5619, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5620, 'Each horse is seen in profile, standing with no saddle or bridle, on a dark green background.', 5620, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5621, 'They are painted very realistically, and composed from the front half of one parent and the rear half of the other, joined in the middle across the body.', 5621, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5622, 'In the late 1990s Wallinger and a syndicate purchased and began to race a horse named A Real Work of Art.', 5622, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5623, 'Wallinger has also made a number of works about religion.', 5623, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5624, 'One features himself carrying a blind person&#x2019;s white stick walking down an upwards escalator chanting the lords prayer which is played backwards.', 5624, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5625, 'Wallinger contributed a proposal for the empty sculpture plinth in Trafalgar Square in London.', 5625, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5626, 'Ecce Homo, a one metre high statue of a naked man (who could be a Christ figure) is made in white marble and stands on one corner of the plinth close to the edge looking outwards.', 5626, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5627, 'Rebecca Warren', 5627, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5628, 'British artist born in the 1960s who makes sculptures from clay, ceramic and bronze.', 5628, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5629, 'Warren models human figures very roughly, using lumps of clay barely fashioned, the surface not smoothed at all.', 5629, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5630, 'Figures are sometimes engaged in sexual acts.', 5630, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5631, 'Female forms are large breasted and monumental and male forms have oversized penises.', 5631, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5632, 'The clay is usually left unglazed, sometimes and the sculpture is presented on a plinth.', 5632, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5633, 'They range in size from life size down to table top size.', 5633, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5634, 'Warren has made a series of large sculptures which are homage to both the cartoonist Robert Crumb and the painter Philip Guston (who was himself influenced by Crumb).', 5634, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5635, 'Each one is a Crumb style figure (with an enormously exaggerated bottom) combined with elements of the work of a famous artist from history.', 5635, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5636, 'Warren has also made works in bronze, sometimes consisting of no more than a lump or a phallic object.', 5636, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5637, 'Gillian Wearing', 5637, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5638, 'British artist born in the 1960s whose work in a variety of media deals with identity.', 5638, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5639, 'Wearing&#x2019;s earliest work to gain popularity is called Dancing In Peckham, a video of herself with a personal stereo dancing in the middle of a busy shopping centre.', 5639, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5640, 'She also walked around her local streets with her entire head bandaged, noting the comments and attitudes that she attracted.', 5640, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5641, 'Signs That Say What You Want Them to Say, is a video and a series of photographs.', 5641, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5642, 'Wearing asked people on the street to write down, on a piece of paper that she gave them, something that they would like to say but never had.', 5642, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5643, 'She then photographed them holding the sign in front of them.', 5643, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5644, 'The resulting contrast between the expressed desire or emotion and the authors face is subject of the work.', 5644, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5645, 'Continuing her exploration of how people see themselves, Wearing made a video of herself in bed with a number of transsexuals and transvestites, and a single shot video of a local police force, standing in rows.', 5645, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5646, 'The officers remain motionless and so does the camera, so that what is a moving image becomes almost a still image.', 5646, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5647, 'Individual movements, blinking, and any tics assume the same importance as gesture and facial expression in their absence.', 5647, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5648, 'In 2003 Wearing made an number of photographs of herself dressed as members of her own family, using masks, prosthetics, wigs and make up.', 5648, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5649, 'Gary Webb', 5649, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5650, 'British artist born in the 1970s who makes abstract sculptures from a variety of building and fabrication materials, plastic, acrylic, blown glass, laminate, rubber, metal and fibreglass.', 5650, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5651, 'Webb&#x2019;s sculptures sometimes have an audio addition, piece of music, sound or a song emanating from part of the sculpture.', 5651, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5652, 'Webb draws on the legacy of 1960s and 70s sculptors like Antony Caro and David Smith, but his choice of materials is fundamentally different since he chooses more fragile or delicate materials.', 5652, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5653, 'An early work consists of a small wood veneered unit on legs with music coming from it and a plume of wood veneer.', 5653, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5654, 'Another consist of an amorphous giant pebble form lacquered in bright yellow high gloss paint with various other elements.', 5654, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5655, 'Webb used representative objects in some of his early work, such as a black skinned female doll attached to a sphere and decorated.', 5655, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5656, 'There are often references to furniture, for example the coffee table is a favourite form.', 5656, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5657, 'Sometimes a specially made blown glass element is added.', 5657, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5658, 'Webb has made moulded rubber floor tiles as part of another sculpture.', 5658, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5659, 'Webb&#x2019;s sculptures have the look of giant three dimensional collages of abstract elements that are brought together formally in the manner of traditional sculpture but do not share this appearance.', 5659, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5660, 'Nicole Wermers', 5660, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5661, 'German artist born around 1970 who makes collages.', 5661, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5662, 'Franz West', 5662, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5663, 'German artist who makes sculpture and installation and works on paper.', 5663, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5664, 'West&#x2019;s work generally features furniture, papier mach&#xe9; timber and plaster or bronze &#x2018;lumps&#x2019; and painted collage.', 5664, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5665, 'A sausage, turd or penis form appears frequently in his work whether made in papier mach&#xe9;, cast in bronze or painted into collages.', 5665, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5666, 'West has a democratic approach to art, believing that an art objects value is created as much by the viewing subject as by the artist.', 5666, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5667, 'To this end most of his sculpture is made to be touched or sat on.', 5667, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5668, 'West is probably best known for his interactive sculptures.', 5668, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5669, 'These are ungainly white plaster objects, organic amorphous white shapes that sit awkwardly on a plinth and look like joke sculptures.', 5669, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5670, 'The viewer is instructed on the label accompanying the work to pick up the object and interact with it.', 5670, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5671, 'There may be a video monitor showing a number of people doing this.', 5671, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5672, 'A curtained off area with floor to ceiling mirror may be provided, and the viewer invited to enter with the sculpture and interact with it.', 5672, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5673, 'Some of the sculptures have wire extrusions enabling them to be &#x2018;worn&#x2019;, or areas which allow then to be balanced on a shoulder.', 5673, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5674, 'The interactive sculptures each have a specific plinth, which may incorporate a mirror, or a seat and in on case a bed on which the viewer can lie with the sculpture.', 5674, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5675, 'West has made a large number of items of furniture, on which the viewer is free to sit or lounge.', 5675, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5676, 'In particular he makes chairs and sofas, simple square shapes with unconventionally deep and wide seats.', 5676, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5677, 'The furniture is made from unfinished steel concrete reinforcing rods with thin cushions upholstered in utilitarian materials such as canvas, sacking and silver insulation fabric.', 5677, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5678, 'The furniture is sometimes placed in direct relation to a sculpture, for example a chair with a Hessian cushion is placed near to a pink papier mach&#xe9; lump which is hung from the ceiling.', 5678, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5679, 'Or a pair of chairs with silver cushions are placed with a one and a half meter high sphere covered with brown parcel tape between them.', 5679, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5680, 'The furniture is designed to involve the viewer physically in West&#x2019;s work, to provoke thoughts about the idea of contemplation of art works.', 5680, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5681, 'Through his large number of lump sculptures West investigates the idea of the autonomous and intrinsically valuable art objects.', 5681, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5682, 'He create essentially lumpen abstract objects that could be said to be ugly and presents then in the same way that any sculpture would be shown.', 5682, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5683, 'The lumps range in size from around fifty cm high to two metres high and more.', 5683, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5684, 'They are made in papier mach&#xe9; on a plaster and timber frame work, sometimes with a gap left through which the inside can be viewed, and painted.', 5684, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5685, 'They are also made in bronze, cast from papier mach&#xe9; originals and painted often in pink or pale blue, sometimes multicoloured.', 5685, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5686, 'The forms of the lumps seem arbitrary although West has made a series of lump portrait heads.', 5686, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5687, 'The phallic objects which West deploys in his work a sausage, penis or turd shape appear as sculpture made from papier mach&#xe9;, bronze or resin.', 5687, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5688, 'Some are fabricated in sheet steel, cut in pieces and welded together in a patchwork.', 5688, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5689, 'These are painted in colours that seem inappropriate to the form and material such as pale pink and blue, ochre or gold.', 5689, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5690, 'West has made sculpture in this form in sizes ranging from 30 cm long to 20 metres long outdoor sculpture.', 5690, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5691, 'The phallic shape appears in West&#x2019;s collages frequently.', 5691, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5692, 'These consist of magazine cut outs usually of men and women, which are painted over in poster paint to alter their body shape.', 5692, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5693, 'They often feature half obscured sexual acts.', 5693, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5694, 'West adds sausages cut from magazine advertisements emerging from a man or woman&#x2019;s mouth, or from a man&#x2019;s trousers.', 5694, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5695, 'Martin Westwood', 5695, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5696, 'British artist born in the 1960s who makes mixed media wall work using collage, drawing, painting and papier mach&#xe9;.', 5696, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5697, 'Westwood often makes silhouette cut outs and uses spray paint over these or through doilies to create shadow effects.', 5697, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5698, 'In general his work is wall based, but he has also made installations, for example one in which he hung a number of papier mach&#xe9; forms made over balloons, which he had painted, collaged and drawn on.', 5698, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5699, 'Westwood often chooses unconventional paper for his drawings, such as newsprint, or printed material.', 5699, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5700, 'Rachel Whiteread', 5700, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5701, 'British artist born in the 1960s who makes large scale sculpture.', 5701, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5702, 'Whiteread casts the interior and the underneath of buildings, rooms and furniture in concrete, plaster, rubber and resin, making a solid form from negative space.', 5702, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5703, 'She began by casting mattresses in rubber and translucent silicon around 1990.', 5703, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5704, 'these solid forms were placed on the floor half bent to lean against the wall.', 5704, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5705, 'She also cast a bath, producing a solid block with a negative bath shape set into it which looks like a sarcophagus.', 5705, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5706, 'A basin done in the same way, and some tables and desks which are simply the solid blocks produced from the space under a table.', 5706, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5707, 'Whiteread&#x2019;s first major work is Ghost, 1993, a cast of a room in a house.', 5707, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5708, 'This work appears as a life sized plaster block (made in sections) which has the impressions of the details of the room on its surface.', 5708, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5709, 'For example a fireplace projects from the surface instead of being cut into the wall, door and window frames which are negatives set into the surface, as are door handles, skirting board and light switches.', 5709, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5710, 'Whiteread continued to make smaller objects, and in 1997 she made House, her best known work and one which became notorious.', 5710, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5711, 'House was the cast of the interior of a two storey Victorian terraced house in the east end of London.', 5711, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5712, 'The cast was made by spraying the interior with concrete and reinforcing it, then demolishing the exterior carefully.', 5712, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5713, 'The row of houses was condemned and was to be demolished to make way for a new park so Whiteread&#x2019;s work was to be temporary.', 5713, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5714, 'However it was so popular that there were calls for it to remain as a permanent public sculpture in the park.', 5714, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5715, 'There ensued a long public battle between arts bodies and the local authority with press and local residents both for and against the sculpture.', 5715, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5716, 'The sculpture was finally demolished.', 5716, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5717, 'Whiteread was commissioned to make a holocaust memorial for Vienna.', 5717, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5718, 'Her cast of the interior of a library sited in a pedestrian square was finally unveiled in 2001 after several years of wrangling between commissioning bodies, public bodies and the authorities.', 5718, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5719, 'The library is a cement block with the spines of books covering it.', 5719, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5720, 'These &#x2018;books&#x2019; are removable, each representing a person from that city who died in the holocaust.', 5720, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5721, 'Whiteread has continued to cast furniture throughout her career.', 5721, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5722, 'She began to use acrylic resin at the end of the 1990s, casting the spaces underneath a classroom full of chairs, for example.', 5722, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5723, 'Cathy Wilkes', 5723, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5724, 'Scottish artist born in the 1960s who uses found objects which she juxtaposes to make allusive sculptural works.', 5724, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5725, 'One work uses a camp beds and a man&#x2019;s tie, another a small ornament on a shelf.', 5725, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5726, 'There is an solitary and pensive quality to Wilkes&#x2019; work.', 5726, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5727, 'Stephen Willats', 5727, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5728, 'British artist born in the 1950s who makes installation, text based and graphic work.', 5728, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5729, 'Willats has also self published a number of books and pamphlets.', 5729, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5730, 'Willats investigates how people live from a social, political and geographical perspective, employing survey questionnaires, plans and charts, statistics and photography.', 5730, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5731, 'He has produced a magazine for a number years.', 5731, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5732, 'An exhibition of his work would typically feature photographs and newspaper clippings with accompanying text and detailed captions, posters printed by him, often with painted or drawn additions, video and a publication.', 5732, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5733, 'Erland Williamson', 5733, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5734, 'Born in 1965 Scottish artist Williamson made socially engaged work, before he died in 1995.', 5734, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5735, 'Williamson customised a van that he used to take the road show that he created to many different places.', 5735, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5736, 'The van contained a collapsible kiosk which the artist would set up and open as a kind of drop in centre.', 5736, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5737, 'He might set it up on a housing estate and ask residents if they wished to fill in questionnaires about where they lived, have a cup of tea, make flyers and posters themselves.', 5737, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5738, 'He acted as a grass roots activist with the intention of encouraging people to mobilise for change through his work.', 5738, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5739, 'His work, the van and the kiosk has a strongly homemade aesthetic, hand painted signage on the van and kiosk done in an amateur style in gloss paint on hardboard, hand printed posters and flyers, a heavy dependence on the photocopier, and even t shirts for sale printed with his own slogans.', 5739, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5740, 'Jane and Louise Wilson', 5740, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5741, 'British artist sisters born in the late 1960s who make large scale projected video installations.', 5741, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5742, 'An early work from the beginning of the 1990s involved them filming themselves under hypnosis to see if they were telepathic because they are twins.', 5742, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5743, 'At this time they also made a series of photographs showing parts of their bodies in empty offices, which were printed in a square format and hung at odd levels in the gallery relating to the architecture of the space.', 5743, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5744, 'These photographs were an investigation into the nature of deserted space and the human traces left in them by default.', 5744, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5745, 'The Wilson&#x2019;s then began to make the work for which they are known.', 5745, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5746, 'This usually involves the selection of a location, invariably an empty building with a specific purpose or history.', 5746, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5747, 'Examples are Greenham Common nuclear base, a law court, and a casino.', 5747, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5748, 'They film these empty spaces and add a soundtrack.', 5748, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5749, 'Sometimes the film features the artists themselves, more recently there are no people in the work.', 5749, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5750, 'The films are multi screen projections, often shown on adjacent walls so that they meet in a corner.', 5750, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5751, 'The consequent interaction of the moving images is controlled and deliberate, creating a multiple view of the same space and refusing the viewer a fixed viewpoint.', 5751, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5752, 'In some works the screens are placed at angles, freestanding, with projections on front and back.', 5752, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5753, 'The Wilsons make free use of mirroring and doubling in their work, often seen as an obvious consequence of the fact that they are twins.', 5753, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5754, 'They make run the same film both backwards and forwards so the that the images create a symmetrical pattern.', 5754, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5755, 'The way the films are edited often leads to an abstract patterning effect.', 5755, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5756, 'Richard Wilson', 5756, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5757, 'British artist who is best known for a work that was permanently installed in the Saatchi gallery in London.', 5757, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5758, 'This consists of a steel tank which is waist height.', 5758, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5759, 'The tank fills the room but there is a narrow projection into the tank allowing viewers to walk into the middle.', 5759, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5760, 'The tank is apparently filled with black oil.', 5760, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5761, 'The oil is no more than ten cm deep.', 5761, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5762, 'Its opacity, viscosity, slight movement and reflectiveness create a feeling of vulnerability and disorientation in the viewer, paradoxically coupled with an atmosphere of contemplation.', 5762, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5763, 'TJ Wilson', 5763, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5764, 'American artist who makes video using found footage, his own footage and often uses subtitles.', 5764, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5765, 'He has made a film about a roman villa and another about a baby elephant and its mother, the subtitles for these are not intrinsic to the images ! Richard Wood.', 5765, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5766, 'British artist born in the 1960s who made a series of sculptures by arranging coloured plastic storage baskets, trays and other items and melting them with a blow torch.', 5766, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5767, 'They meld together, colours mingling and are transformed into spiked and dripped structures.', 5767, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5768, 'Woods also made a cast of a rolled carpet rug and painted it to resemble the real carpet.', 5768, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5769, 'Wood and Harrison', 5769, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5770, 'British artist duo born in the 1960s who make performance videos in which they use their own bodies to create physical sculptures.', 5770, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5771, 'The artist rely on the weight and motion of their bodies and use each other as counterbalances in a series of interactions with simple props such as planks, boxes and sheets of ply.', 5771, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5772, 'They create ramps, fulcrums, towers and execute sharply performed and choreographed manoeuvres that exhaustively explore interaction of human body with flat plane and with three dimensional object.', 5772, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5773, 'The videos are shown on monitors, often each monitor shows a single work looped.', 5773, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5774, 'The ambient sound of Wood and Harrison&#x2019;s activities is often loud as sheets of timber are walked on, dropped for example.', 5774, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5775, 'Wood and Harrison aim to apply the principles of minimal sculpture to live art, reminiscent of Robert Morris&#x2019;s activity in Olympia with Carolee Schneeman and the early video work of Richard Serra and Vito Acconci.', 5775, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5776, 'Richard Woods', 5776, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5777, 'British artist born in the 1960s who makes wall paintings.', 5777, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5778, 'These consist of abstract patterned elements positioned in unconventional places, perhaps high up, across a corner, along the floor, or in some place that relates to the architecture of the building.', 5778, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5779, 'The works sometimes cover a wall, but are more usually quite small, around one metre high or wide.', 5779, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5780, 'The designs have many references: historical architectural decoration, tattoos, textile designs, architectural drawing and typography.', 5780, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5781, 'Woods refines them until the references all but disappear into his sharp edged, precise, often monotone works.', 5781, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5782, 'The works are hand painted in black, or one or two of the primary colours.', 5782, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5783, 'Christopher Wool', 5783, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5784, 'American artist who makes large abstract paintings on a heavy gauge woven paper which are mainly printed, often using fragments of found patterns, with areas of paint added, predominantly in black and white.', 5784, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5785, 'Elizabeth Wright', 5785, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5786, 'British artist born in the 1960s who makes sculpture and installation that is concerned with the relative size of objects.', 5786, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5787, 'In the mid 1990s Wright made an installation which consisted of a floor strewn with over sized cigarette butts about 40 cm long, and Marlboro packets about 30 cm long.', 5787, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5788, 'Both objects larger that life size but the wrong size in relation to each other.', 5788, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5789, 'The objects are made from cardboard and paper which is painted to look realistic.', 5789, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5790, 'Wright also made scaled down telephone directories which are actually printed and bound, supermarket carrier bags and crisp packets also printed, as well as a bicycle one third larger than life size.', 5790, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5791, 'Cerith Wyn Evans', 5791, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5792, 'Welsh artist born in the 1950s who uses a variety of media.', 5792, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5793, 'Wyn Evans&#x2019; work often includes or is based on literary or philosophical text.', 5793, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5794, 'Many of his works are subtle alterations of a pre existing object in order to transform the everyday into the sublime.', 5794, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5795, 'For example his neon exit sign in which the word is written backwards, his metal crowd barrier which is covered in gold leaf.', 5795, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5796, 'Some works of Wyn Evans works are very simple in execution, for example a large circular convex mirror and a transparent chandelier.', 5796, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5797, 'A luminous painting to read by is a 50 cm high canvas coated with luminous paint, to be hung at eh head of a bed, which is charged with enough light during the day to provide reading light at night.', 5797, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5798, 'Sometimes his work takes the form of an unobtrusive site specific intervention, for example altering the pitch of some bells strung across a stairway to bar public access in the John Soane museum in London.', 5798, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5799, 'Much of Wyn Evans&#x2019; early work is 16 mm film.', 5799, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5800, 'His film about the death of the director Pasolini shows a group of small boys playing on a beach, as behind them a text, a quotation from Pasolini, outlined in fireworks on a specially constructed frame ignites, blazes and burns away.', 5800, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5801, 'He ahs also use neon text running round a light fitting, a phrase that reads continuously with no end.', 5801, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5802, 'Wyn Evans has made a number of neon works using text that reads in a loop, or can be read forwards and backwards, as well as small neon arabesque shapes.', 5802, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5803, 'He has also made text etched onto Perspex panels that hang from the ceiling.', 5803, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5804, 'This use of quotation is given its most complex rendering in a work from 2001.', 5804, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5805, 'Wyn Evans hung a mirror ball in a gallery and projected a bright light at it.', 5805, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5806, 'The light flashes on and off in a Morse code pattern, spelling out a quotation from Oscar Wilde.', 5806, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5807, 'In 2003 Wyn Evans made a work consisting of several crystal chandeliers the bulbs of each flashing the Morse code for a particular extract from a philosophical or literary text.', 5807, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5808, 'Huang Yong Ping', 5808, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5809, 'Chinese artist working from the 1980s onwards who made a sculpture by putting books in a washing machine and moulding the resulting pulp into a sphere.', 5809, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5810, 'He also created a number of outdoor pyrotechnic events.', 5810, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5811, 'Andrea Zittel', 5811, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5812, 'American artist born in the 1960s who makes functional sculptures.', 5812, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5813, 'Zittel&apos;s series of portable living units includes a kitchen, a bedroom and a lounging area.', 5813, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5814, 'The units are made so that they can be folded away and easily transported.', 5814, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5815, 'They are made to a high specification with polished wood exteriors and upholstered interior with special fittings (lights, drop down tables, cupboards, handles and mirrors).', 5815, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5816, 'The lounging area is a purple upholstered sunken seating area, the walls of the case functioning as the walls that enclose it.', 5816, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5817, 'The kitchen is fully functional if minimal.', 5817, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (5818, 'Zittel has also designed a number of items of clothing and has made a site specific work in the desert near to where she lives.', 5818, 1, '1.1', 0);
